// Package coreapi is a client for the Entire Core API
// (us.console.entire.io and regional equivalents).
//
// Only the operations entire-api actually calls are wrapped here (serving reads
// plus off-path batch jobs like the PlanetScale importer). The full OpenAPI
// surface is documented at {CORE_API_URL}/openapi.yaml.
package coreapi

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
)

// Client talks to a single Core API base URL with a configurable HTTP
// transport. The transport carries the auth: the ingester presents its
// workload cert over entire-core's internal mTLS listener (GetRepo +
// AccountByID); local dev injects nil for an unauthenticated client.
type Client struct {
	baseURL    string
	httpClient *http.Client
}

// New builds a Client. baseURL is the Core API root (e.g.
// `https://us.console.entire.io/api/v1`).
func New(baseURL string, hc *http.Client) *Client {
	if hc == nil {
		hc = &http.Client{Timeout: 10 * time.Second, Transport: otelhttp.NewTransport(http.DefaultTransport)}
	}
	return &Client{
		baseURL:    strings.TrimRight(baseURL, "/"),
		httpClient: hc,
	}
}

// Resolve / ResolveResponse were removed: activity only ingests repos
// in its own jurisdiction, so the Repo API base is a single static
// REPO_API_URL — no per-repo placement lookup. NATS events carry repoIDs
// directly. If you need to map a human path to a repoID, do it outside
// the ingest hot path (e.g. one-off via the Core control plane).

// GetMe and its MeResponse types were removed with COR-525: the caller's
// identity (handle, home_jurisdiction) now rides on the account access token,
// so /me reads it off auth.Identity instead of calling Core per request.

type Project struct {
	ID                    string              `json:"id"`
	Name                  string              `json:"name"`
	Region                string              `json:"region"`
	PrimaryProcessingCell string              `json:"primaryProcessingCell,omitempty"`
	OwnerID               string              `json:"ownerId,omitempty"`
	OwnerType             string              `json:"ownerType,omitempty"`
	Capabilities          ProjectCapabilities `json:"capabilities,omitempty"`
}

type ProjectCapabilities struct {
	CanManageTrails bool `json:"canManageTrails"`
	CanManageAgents bool `json:"canManageAgents"`
}

type ProjectPage struct {
	Projects      []Project `json:"projects"`
	Project       *Project  `json:"project,omitempty"`
	NextPageToken string    `json:"nextPageToken,omitempty"`
}

// ListProjects returns one page of the caller's project-membership list. The
// client's transport is responsible for forwarding the caller bearer.
func (c *Client) ListProjects(ctx context.Context, pageSize int, pageToken string) (*ProjectPage, error) {
	values := url.Values{}
	if pageSize > 0 {
		values.Set("pageSize", strconv.Itoa(pageSize))
	}
	if pageToken != "" {
		values.Set("pageToken", pageToken)
	}
	u := c.baseURL + "/projects"
	if query := values.Encode(); query != "" {
		u += "?" + query
	}
	var out ProjectPage
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return nil, err
	}
	if out.Project != nil {
		out.Projects = append(out.Projects, *out.Project)
	}
	return &out, nil
}

type ProjectReference struct {
	Host    string `json:"host"`
	Project string `json:"project"`
}

type ProjectResolution struct {
	Project   *Project         `json:"project"`
	Reference ProjectReference `json:"reference"`
	// Mode is how Core checked the capabilities it returned.
	Mode CapabilityMode `json:"-"`
}

// CapabilityMode selects how Core checks GitHub namespace authority.
type CapabilityMode int

const (
	// CapabilitiesLive asks GitHub now. Only a live capability may
	// authorize a write.
	CapabilitiesLive CapabilityMode = iota
	// CapabilitiesDisplay lets Core answer from a roster up to 70 minutes
	// old. It may admit a read. It never authorizes a write.
	CapabilitiesDisplay
)

// capabilitiesDisplayQuery is Core's opt-in for display capabilities.
const capabilitiesDisplayQuery = "capabilities=display"

// getCapabilities reads u with capabilities checked in mode.
func (c *Client) getCapabilities(ctx context.Context, u string, mode CapabilityMode, out any) error {
	if mode == CapabilitiesDisplay {
		u += "?" + capabilitiesDisplayQuery
	}
	return c.do(ctx, http.MethodGet, u, out)
}

// ResolveProject resolves Core's canonical, forge-qualified public project
// reference. Namespace names are case-insensitive and canonicalized to lowercase;
// Project.Name retains its stored casing and must not be used as the public route
// name for GitHub mirror projects.
func (c *Client) ResolveProject(ctx context.Context, host, project string) (*ProjectResolution, error) {
	return c.ResolveProjectFor(ctx, host, project, CapabilitiesLive)
}

// ResolveProjectFor is ResolveProject with capabilities checked in mode.
func (c *Client) ResolveProjectFor(ctx context.Context, host, project string, mode CapabilityMode) (*ProjectResolution, error) {
	u := fmt.Sprintf("%s/projects/resolve/%s/%s", c.baseURL, url.PathEscape(host), url.PathEscape(strings.ToLower(project)))
	var out ProjectResolution
	if err := c.getCapabilities(ctx, u, mode, &out); err != nil {
		return nil, err
	}
	if out.Project == nil {
		return nil, ErrNotFound
	}
	out.Mode = mode
	out.Reference.Project = strings.ToLower(out.Reference.Project)
	return &out, nil
}

// ProjectsByIDs resolves projects through Core's internal ProjectDirectory in
// one read, keyed by id; unknown ids are absent.
func (c *Client) ProjectsByIDs(ctx context.Context, projectIDs []string) (map[string]*Project, error) {
	out := make(map[string]*Project, len(projectIDs))
	if len(projectIDs) == 0 {
		return out, nil
	}
	var resp struct {
		Projects []struct {
			ID                    string `json:"projectId"`
			Name                  string `json:"name"`
			Jurisdiction          string `json:"jurisdiction"`
			PrimaryProcessingCell string `json:"primaryProcessingCell"`
		} `json:"projects"`
	}
	err := c.doJSONHeaders(ctx, http.MethodPost,
		c.baseURL+"/projectdirectory.v1.ProjectDirectory/BatchGet",
		map[string]any{"projectIds": projectIDs}, &resp,
		map[string]string{"Connect-Protocol-Version": "1"})
	if err != nil {
		return nil, err
	}
	for _, project := range resp.Projects {
		out[project.ID] = &Project{
			ID: project.ID, Name: project.Name, Region: project.Jurisdiction,
			PrimaryProcessingCell: project.PrimaryProcessingCell,
		}
	}
	return out, nil
}

// ProjectCapabilitiesByID reads the existing caller-authorized project endpoint.
// A denial does not deny repository-scoped Trail access; metadata is not a grant.
func (c *Client) ProjectCapabilitiesByID(ctx context.Context, projectID string) (*Project, error) {
	return c.ProjectCapabilitiesByIDFor(ctx, projectID, CapabilitiesLive)
}

// ProjectCapabilitiesByIDFor is ProjectCapabilitiesByID in mode.
func (c *Client) ProjectCapabilitiesByIDFor(ctx context.Context, projectID string, mode CapabilityMode) (*Project, error) {
	var out Project
	if err := c.getCapabilities(ctx, c.baseURL+"/projects/"+url.PathEscape(projectID), mode, &out); err != nil {
		return nil, err
	}
	if out.ID != projectID {
		return nil, fmt.Errorf("core returned unexpected project ID")
	}
	return &out, nil
}

// ProjectByID resolves one project through Core's internal ProjectDirectory.
func (c *Client) ProjectByID(ctx context.Context, projectID string) (*Project, error) {
	projects, err := c.ProjectsByIDs(ctx, []string{projectID})
	if err != nil {
		return nil, err
	}
	if project, ok := projects[projectID]; ok {
		return project, nil
	}
	return nil, ErrNotFound
}

// Repo mirrors the console's Repo schema (subset used by the search service).
//
// Name is the BARE repo name (single segment, no owner/project prefix — Core
// rejects '/'). The human "org/repo" full name lives only in Path
// (/<surface>/<project>/<repo>, e.g. "/et/acme/widget" or a mirror's
// "/gh/owner/repo"); RepoFullName derives it. Path is populated on single-repo
// responses (create, get) and omitted from list responses.
type Repo struct {
	ID              string    `json:"id"`
	Forge           RepoForge `json:"provider"`
	OwningProjectID string    `json:"owningProjectId"`
	Name            string    `json:"name"`
	Path            string    `json:"path,omitempty"`
	// FullName is Core's resolved "owner/repo" for a mirror, sent on the
	// single-repo read. It's empty for a native repo (whose name is in Path) and
	// empty against a Core that predates the field, so RepoFullName falls back to
	// the Path derivation — matching today's behavior until Core ships it.
	FullName    string `json:"fullName,omitempty"`
	ClusterSlug string `json:"clusterSlug,omitempty"`
	Foreign     bool   `json:"foreign,omitempty"`
	// Jurisdiction is the repo's HOME region as Core reports it — the serving
	// core's own for a local repo, the global registry's stamp for a foreign
	// placement. The seed paths stamp it onto repos.jurisdiction so a cell never
	// labels a foreign placement as local (which would poison ReposByGroup's
	// origin→local-placement resolution and silently empty /me/sessions). Empty
	// against a Core predating the field; seeding then falls back to the cell's
	// own jurisdiction, matching the pre-field behavior.
	Jurisdiction string      `json:"jurisdiction,omitempty"`
	Mirror       *RepoMirror `json:"mirror,omitempty"`
	ObjectFormat string      `json:"objectFormat,omitempty"`
	State        string      `json:"state,omitempty"`
	IsPublic     bool        `json:"isPublic,omitempty"`
	// RepoGroupID is the group ULID for native and mirrored repos.
	// Core may omit it before registry publication or when serving an older wire format.
	RepoGroupID string `json:"repoGroupId,omitempty"`
	// Primaries names the repo group's two primaries — {git_data, processing} —
	// on the single-repo read. It is the bus-independent hook for the
	// processing-primary flag: ingest's ensureRepo self-heals the flag when
	// Primaries.Processing equals the repo it just grouped (see
	// store.SelfHealProcessingPrimary). Core populates it whenever the repo's group
	// resolves, but returns it NIL for a native-mirror placement read by its own
	// ULID (the group is keyed by the PRIMARY's ULID), so a mirror never
	// self-elects. Nil against a Core predating the field; the self-heal then
	// no-ops and the bus arm remains the only writer.
	Primaries *RepoPrimaries `json:"primaries,omitempty"`
	// DetachedAt is when a detach made the repo group's GitHub mirror native;
	// nil for a group that never detached and against a Core predating the
	// field. Ingest reads it to tell a pending repo.detached from a forge
	// conflict.
	DetachedAt *time.Time `json:"detachedAt,omitempty"`
}

// RepoPrimaries is the decode subset of Core's repo-group primaries: GitData is
// the immutable git-content home (forge-qualified, e.g. "github:12345" or the
// native primary's own identity), unused here; Processing is the placement elected
// to do the group's per-event work exactly once — its repo ULID, or "" when no
// placement is currently eligible. Ingest reads Processing to self-heal the flag.
type RepoPrimaries struct {
	GitData    string `json:"git_data"`
	Processing string `json:"processing"`
}

// The repo's placement-independent activity origin — the mirrored upstream's
// shared repo_group ULID — is resolved on two paths, by design. It is primarily a
// data-plane fact: the repo_refs_v1 ref event carries it as repo_group_id and
// ingest stamps it onto repos.repo_group_id, so a live push resolves it at ref
// scale without a Core round-trip. Core exposes the same ULID as Repo.RepoGroupID
// so the paths that don't ride a ref event (the per-repo backfill re-forward) can
// still resolve it — see ensureRepo's fallback. entire-core mints and provisions
// the repo_group, so both paths agree.

// RepoFullName returns the human "org/repo" full name. It prefers Core's
// resolved FullName — which carries a mirror's "owner/repo" that the Path can't
// (Core omits the path for mirror/foreign rows) — and otherwise derives it from
// the Path (/<surface>/<project>/<repo> → "<project>/<repo>"; a GitHub mirror's
// "/gh/<owner>/<repo>" → "<owner>/<repo>"). Returns "" when both are absent
// (e.g. foreign rows against a Core predating FullName) so the caller can fall
// back.
func (r *Repo) RepoFullName() string {
	if r.FullName != "" {
		return r.FullName
	}
	p := strings.Trim(r.Path, "/")
	if p == "" {
		return ""
	}
	// Drop the surface prefix segment (et / gh / git); keep <project>/<repo>.
	if i := strings.IndexByte(p, '/'); i >= 0 {
		return p[i+1:]
	}
	return ""
}

// GitHubMirrorFullName returns Core's GitHub "owner/repo" for a mirror, else "".
// Core fills FullName only for a github-forge repo, from github_repos. The Path
// derivation is never a GitHub name (native "<project>/<repo>", lowercased /gh/ alias).
func (r *Repo) GitHubMirrorFullName() string {
	if r.Forge != RepoForgeGitHub {
		return ""
	}
	return r.FullName
}

type RepoMirror struct {
	Forge          string `json:"provider"`
	RemoteOwner    string `json:"remoteOwner"`
	RemoteRepo     string `json:"remoteRepo"`
	RemoteURL      string `json:"remoteUrl,omitempty"`
	InstallationID int64  `json:"installationId,omitempty"` // GitHub installation id is numeric
	IsPrivate      bool   `json:"isPrivate,omitempty"`
}

// GetRepo fetches metadata for a single repo by id.
func (c *Client) GetRepo(ctx context.Context, repoID string) (*Repo, error) {
	u := fmt.Sprintf("%s/repos/%s", c.baseURL, url.PathEscape(repoID))
	var out Repo
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// ResyncMirror asks the cell-local Core to resync a mirror placement
// (POST /mirrors/{id}/resync), used best-effort by ingest to sync a code repo's
// SEPARATE external checkpoints repo after a branch push (ENT-1172): those
// checkpoint pushes land on refs/entire/checkpoints/* of a different remote, which
// emits no GitHub webhook, so mirror-pipeline never syncs them on its own. repoID
// is the checkpoint repo's mirror-placement ULID.
//
// A 202 is success. Non-2xx maps to an error the caller log-and-swallows: 404
// (unknown/suspended placement) → ErrNotFound, 409 (no GitHub App installation on
// file) and 503 (publisher unwired) → a formatted error. Core minute-buckets the
// synthetic push webhook it publishes, so the central stream's dedup collapses
// bursts — the caller fires per branch push without its own dedup and never retries.
func (c *Client) ResyncMirror(ctx context.Context, repoID string) error {
	u := fmt.Sprintf("%s/mirrors/%s/resync", c.baseURL, url.PathEscape(repoID))
	return c.do(ctx, http.MethodPost, u, nil) // 202, no body → out nil
}

// GitHubInstallationToken obtains a short-lived GitHub App installation token
// for one mirror repository through Core's RFC 8693 exchange. The configured
// HTTP transport presents entire-api's SPIFFE workload certificate; there is
// intentionally no bearer subject token. Core re-verifies targetRepoID and the
// source owner/repo against its mirror metadata before minting.
//
// The returned expiry is absolute, derived from the response's expires_in at
// the moment it was read. It is NOT a full hour from now — Core serves these
// from its own cache for most of a token's life, so a successful mint commonly
// returns one with well under an hour left. Callers that cache the token must
// honour this instant rather than assume a lifetime.
//
// A zero expiry means Core reported no usable expires_in. An expiry at or before
// now means it reported an already-dead token; the two are distinct, so a caller
// can bound an unstated lifetime differently from a stated one.
func (c *Client) GitHubInstallationToken(ctx context.Context, targetRepoID, sourceOwner, sourceRepo, reason string) (string, time.Time, error) {
	if targetRepoID == "" || sourceOwner == "" || sourceRepo == "" || reason == "" {
		return "", time.Time{}, errors.New("coreapi: installation token exchange requires target repo, source owner/repo, and reason")
	}
	form := url.Values{}
	form.Set("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange")
	form.Set("requested_token_type", "urn:entire:token-type:github-installation-token")
	form.Set("target_repo", targetRepoID)
	form.Set("source_owner", sourceOwner)
	form.Set("source_repo", sourceRepo)
	form.Set("reason", reason)

	u := c.baseURL + "/api/authz/sts/token"
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, u, strings.NewReader(form.Encode()))
	if err != nil {
		return "", time.Time{}, fmt.Errorf("coreapi: installation token request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return "", time.Time{}, fmt.Errorf("coreapi: installation token exchange: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		preview, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return "", time.Time{}, &InstallationTokenError{Status: resp.StatusCode, Body: strings.TrimSpace(string(preview))}
	}
	var out struct {
		AccessToken string          `json:"access_token"`
		ExpiresIn   json.RawMessage `json:"expires_in"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", time.Time{}, fmt.Errorf("coreapi: decode installation token response: %w", err)
	}
	if out.AccessToken == "" {
		return "", time.Time{}, errors.New("coreapi: installation token response omitted access_token")
	}
	// Anchored after the read, so transit time counts against the lifetime
	// rather than being credited to it — erring towards an earlier expiry.
	return out.AccessToken, expiresInToExpiry(out.ExpiresIn, time.Now()), nil
}

// The read API's authorization no longer goes through Core's /access family:
// it queries the regional read-only SpiceDB directly via
// authz.Reader (internal/authz, wired through internal/auth.AccessChecker).
// Core stays the source for control-plane reads only (GetMe, GetRepo,
// AccountByID).

// Account is an Entire account's identity + home placement, used by the
// ingester to attribute activity to its pusher and pick the forwarding home.
// HomeJurisdiction is the residency domain and the account's only placement
// fact — it is what the forwarder routes by (a user_activity event is
// account-addressed). Core does not model a per-account cluster, and a
// jurisdiction is not a cluster (it contains clusters), so there is nothing to
// derive: an empty HomeJurisdiction is unresolved, never guessed.
type Account struct {
	AccountID        string `json:"accountId"`
	HomeJurisdiction string `json:"homeJurisdiction"`
	// Approved is the account's live waitlist state (COR-940); nil against a Core
	// that predates the field, so absence never fabricates a verdict.
	Approved *bool `json:"approved,omitempty"`
}

// No display-name / GitHub-login fields here: Account is specifically the pusher's
// home-placement shape, used by the forwarder path. Commit-author resolution uses
// AuthorAccounts (POST /author-accounts, COR-659) + AccountIdentities
// (POST /accounts/identities, COR-516) — both in this file — and the
// commitAuthorUsername / firstCommitAuthorUsername render is live as of COR-660.

// AccountByID resolves an account ULID to its home placement via
// GET /accounts/{id}. Called by PusherResolver.Resolve and the PlanetScale
// importer; wired in production today.
//
// Contract the caller relies on, and the reason it is three-valued: an unknown
// id returns ErrNotFound and an account with no placement returns ErrNoHome —
// both PERMANENT, so the caller attributes nothing and never guesses a home. A
// transport error is returned as-is, the one RETRYABLE outcome, so the caller
// naks rather than caching a miss or laundering an outage into a permanent
// attribution failure.
func (c *Client) AccountByID(ctx context.Context, accountID string) (*Account, error) {
	if accountID == "" {
		return nil, ErrNotFound
	}
	u := fmt.Sprintf("%s/accounts/%s", c.baseURL, url.PathEscape(accountID))
	var out Account
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return nil, err
	}
	if out.HomeJurisdiction == "" {
		return nil, ErrNoHome
	}
	if out.AccountID == "" {
		out.AccountID = accountID // endpoint may echo only the placement
	}
	return &out, nil
}

// ResolveAccountByGitHubLogin maps a GitHub login to its entire-core account
// ULID, via the internal identity service (GET /identity/handles/github/{login}).
//
// Used off the serving path by the PlanetScale importer to remap legacy
// entire.io rows (keyed by GitHub login) onto entire-api account ULIDs. An
// unknown handle returns ErrNotFound so the caller can skip+count the row
// rather than fail the run. A login can change on an upstream rename; the
// importer is re-runnable, so a later run heals any drift.
func (c *Client) ResolveAccountByGitHubLogin(ctx context.Context, login string) (string, error) {
	if login == "" {
		return "", ErrNotFound
	}
	u := fmt.Sprintf("%s/identity/handles/github/%s", c.baseURL, url.PathEscape(login))
	var out struct {
		AccountID string `json:"accountId"`
	}
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return "", err
	}
	if out.AccountID == "" {
		return "", ErrNotFound
	}
	return out.AccountID, nil
}

// ResolveAccountByUsername maps a claimed Entire username to its account
// ULID via GET /accounts/by-username/{username} (ENT-2884). An unclaimed or
// unknown username returns ErrNotFound; the trail actor input contract maps
// that to a 422 naming the value.
func (c *Client) ResolveAccountByUsername(ctx context.Context, username string) (string, error) {
	if username == "" {
		return "", ErrNotFound
	}
	u := fmt.Sprintf("%s/accounts/by-username/%s", c.baseURL, url.PathEscape(username))
	var out struct {
		AccountID string `json:"accountId"`
	}
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return "", err
	}
	if out.AccountID == "" {
		return "", ErrNotFound
	}
	return out.AccountID, nil
}

// ResolveAccountByGitHubID maps a GitHub numeric user id to its entire-core
// account ULID, via GET /identity/providers/github/{id}. The id is the stable
// identity key, so unlike ResolveAccountByGitHubLogin this read survives a
// rename and is unambiguous on a legacy case collision. An unknown id returns
// ErrNotFound: an external contributor with no Entire account.
func (c *Client) ResolveAccountByGitHubID(ctx context.Context, id int64) (string, error) {
	if id <= 0 {
		return "", ErrNotFound
	}
	u := fmt.Sprintf("%s/identity/providers/github/%d", c.baseURL, id)
	var out struct {
		AccountID string `json:"accountId"`
	}
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return "", err
	}
	if out.AccountID == "" {
		return "", ErrNotFound
	}
	return out.AccountID, nil
}

// RepoCollaborator is one account with effective access to a repo, as served by
// ListRepoCollaborators. Handle is "provider:label" (e.g. "github:octocat") and
// can be empty when no handle resolves for the account; AccountID is always
// present. Role is "reader" or "writer". Username is empty until claimed.
type RepoCollaborator struct {
	AccountID string `json:"accountId"`
	Username  string `json:"username,omitempty"`
	Handle    string `json:"handle"`
	Role      string `json:"role"`
}

// ListRepoCollaborators fetches one page of accounts with effective access to
// a repo, via GET /repos/{repoID}/collaborators. Core paginates the result
// (keyset over account_id); pageSize/pageToken forward verbatim, and the
// returned nextPageToken is empty once the caller has reached the last page.
func (c *Client) ListRepoCollaborators(ctx context.Context, repoID string, pageSize int, pageToken string) ([]RepoCollaborator, string, error) {
	q := url.Values{}
	if pageSize > 0 {
		q.Set("pageSize", strconv.Itoa(pageSize))
	}
	if pageToken != "" {
		q.Set("pageToken", pageToken)
	}
	u := fmt.Sprintf("%s/repos/%s/collaborators", c.baseURL, url.PathEscape(repoID))
	if len(q) > 0 {
		u += "?" + q.Encode()
	}
	var out struct {
		Collaborators []RepoCollaborator `json:"collaborators"`
		NextPageToken string             `json:"nextPageToken"`
	}
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return nil, "", err
	}
	return out.Collaborators, out.NextPageToken, nil
}

// GitHubTokenSeed is one decrypted legacy GitHub token to seed into entire-core's
// global github_user_tokens (POST /github-tokens/seed). The json tags are the
// snake_case wire contract the endpoint expects. GitHubID is the stable key
// entire-core resolves the account on (not the mutable username). AccessExpiresAt
// is nil when the legacy row had no expiry — it marshals to a JSON null, which the
// endpoint reads as "no known expiry".
type GitHubTokenSeed struct {
	GitHubID        int64      `json:"github_id"`
	GitHubUsername  string     `json:"github_username"`
	AccessToken     string     `json:"access_token"`
	RefreshToken    string     `json:"refresh_token"` // "" when the legacy row had no refresh token
	AccessExpiresAt *time.Time `json:"access_expires_at"`
}

// SeedGitHubToken seeds one decrypted legacy GitHub token into entire-core over
// its internal mTLS listener (POST /github-tokens/seed), used off the serving path
// by the PlanetScale importer. entire-core resolves the account by github_id and
// seeds only when absent, returning the outcome as a status string:
//
//	"seeded"             — the token was written
//	"skipped_no_account" — github_id resolved to no entire-core account
//	"skipped_exists"     — the account already had a token (not overwritten)
//
// Seeding on github_id (never overwriting an existing token) is what makes the
// import idempotent and re-runnable: a second run of an already-seeded account
// returns "skipped_exists". The status is returned verbatim for the caller to
// tally; a transport/HTTP error is returned as-is so the run can retry the row.
func (c *Client) SeedGitHubToken(ctx context.Context, seed GitHubTokenSeed) (string, error) {
	u := c.baseURL + "/github-tokens/seed"
	var out struct {
		Status string `json:"status"`
	}
	if err := c.doJSON(ctx, http.MethodPost, u, seed, &out); err != nil {
		return "", err
	}
	return out.Status, nil
}

// AutomationGrant grants RepoID read access to an automation (ENT-1435); a
// nil ExpiresAt is a non-expiring grant.
type AutomationGrant struct {
	RepoID    string     `json:"repo_id"`
	ExpiresAt *time.Time `json:"expires_at,omitempty"`
}

// AutomationSpec describes one automation for CreateAutomations to create or upsert.
type AutomationSpec struct {
	RepoGroupID string `json:"repo_group_id"`
	Class       string `json:"class"`
	// ProviderID is the workload identity provider whose token the job
	// presents. REQUIRED: it is part of the automation's natural key in core
	// (repo_group_id, class, provider_id, job), so an omitted or malformed one
	// is a 400 and nothing is written.
	//
	// It must be the SAME provider the caller then writes the binding against.
	// The row and its binding are what say which token may present as this
	// automation, and core does not cross-check them — a row naming one
	// provider while its binding names another looks correct and is not.
	ProviderID string            `json:"provider_id"`
	Job        string            `json:"job"`
	Grants     []AutomationGrant `json:"grants"`
}

// Automation is entire-core's automation resource, returned by CreateAutomations and GetRepoGroupAutomations.
type Automation struct {
	ID          string    `json:"id"`
	RepoGroupID string    `json:"repo_group_id"`
	Class       string    `json:"class"`
	ProviderID  string    `json:"provider_id"`
	Job         string    `json:"job"`
	CreatedAt   time.Time `json:"created_at"`
}

// CreateAutomations creates automations via POST /automations, inline grants
// included. Core upserts on (repo_group_id, class, provider_id, job): a rerun with the same
// key returns the existing automation id and REPLACES its grant set — see
// server.bindRunnerAutomation's pre-check comment for why that makes a naive
// rerun dangerous across placements.
func (c *Client) CreateAutomations(ctx context.Context, specs []AutomationSpec) ([]Automation, error) {
	u := c.baseURL + "/automations"
	var out struct {
		Automations []Automation `json:"automations"`
	}
	if err := c.doJSON(ctx, http.MethodPost, u, map[string]any{"automations": specs}, &out); err != nil {
		return nil, err
	}
	return out.Automations, nil
}

// AutomationBindingRequest binds an automation to an OIDC provider, scoped by
// AttributeFilter — an exact-match claim set, never a wildcard.
type AutomationBindingRequest struct {
	ProviderID      string          `json:"provider_id"`
	AttributeFilter json.RawMessage `json:"attribute_filter,omitempty"`
}

// RepoULIDFilterKey is the canonical attribute naming an Entire repo ULID.
// entire-core reserves "repository" for a forge coordinate (COR-1451, entiredb
// ADR 20260908-canonical-attribute-one-value-space).
//
// The transitional alias is gone: entiredb #3585's oidcfed migration 008
// rewrote every stored runner binding filter onto this key, and #3586 dropped
// "repository" from the runner provider's mapping. A filter still keyed that
// way now pins an attribute no runner token carries, so its exchange fails
// closed — which is why the two comparisons below no longer fold the old key
// onto this one. Folding it would report a dead binding as a match and leave
// the drift unreported.
const RepoULIDFilterKey = "entire_repo_id"

// AutomationBinding is entire-core's binding resource, returned by CreateAutomationBinding.
type AutomationBinding struct {
	ID              string          `json:"id"`
	AutomationID    string          `json:"automation_id"`
	ProviderID      string          `json:"provider_id"`
	AttributeFilter json.RawMessage `json:"attribute_filter"`
	CreatedAt       time.Time       `json:"created_at"`
}

// ErrBindingExists is returned when a binding for the (automation, provider) pair already exists; see CreateAutomationBinding.
var ErrBindingExists = errors.New("coreapi: automation binding already exists")

// CreateAutomationBinding binds automationID to an OIDC provider via POST
// /automations/{id}/bindings. A 409 here means a binding for this
// (automation, provider) pair already exists — this is entire-api's first
// multi-call sequence against core where a mid-sequence failure leaves
// partial state, and a duplicate binding means "already configured", not an
// error, so it is surfaced as ErrBindingExists (wrapped with the response
// body) rather than a generic failure, letting the caller treat it as
// success-with-a-note instead of aborting.
func (c *Client) CreateAutomationBinding(ctx context.Context, automationID string, req AutomationBindingRequest) (*AutomationBinding, error) {
	u := fmt.Sprintf("%s/automations/%s/bindings", c.baseURL, url.PathEscape(automationID))
	var out AutomationBinding
	if err := c.doJSON(ctx, http.MethodPost, u, req, &out); err != nil {
		var statusErr *StatusError
		if errors.As(err, &statusErr) && statusErr.Status == http.StatusConflict {
			return nil, fmt.Errorf("%w: %s", ErrBindingExists, statusErr.Body)
		}
		return nil, err
	}
	return &out, nil
}

// GetAutomationBindings reads back every binding on an automation, via GET
// /automations/{id}/bindings. Core dedups bindings on (automation, provider)
// alone, so a 409 from CreateAutomationBinding says nothing about the stored
// attribute filter — this is how a caller checks it. The route is paginated,
// and the binding being looked for may sit on any page, so the cursor is
// followed to exhaustion rather than reading only the first page.
//
// A walk that cannot be completed returns an error, never a short list: callers
// decide automation OWNERSHIP from this result, and a partial list reads as
// "no foreign bindings" — which would classify another placement's automation
// as solely ours and clobber its grants. Truncation must fail closed.
func (c *Client) GetAutomationBindings(ctx context.Context, automationID string) ([]AutomationBinding, error) {
	base := fmt.Sprintf("%s/automations/%s/bindings", c.baseURL, url.PathEscape(automationID))
	var all []AutomationBinding
	seen := map[string]bool{}
	cursor := ""
	// Bindings are one-per-provider, so a healthy walk is a couple of pages;
	// the cap only ever trips on a server paging pathologically (a cycle longer
	// than a self-reference, or an unbounded stream).
	for page := 0; page < maxBindingPages; page++ {
		u := base
		if cursor != "" {
			u += "?cursor=" + url.QueryEscape(cursor)
		}
		var out struct {
			Bindings   []AutomationBinding `json:"bindings"`
			NextCursor string              `json:"next_cursor"`
		}
		if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
			return nil, err
		}
		all = append(all, out.Bindings...)
		if out.NextCursor == "" {
			return all, nil
		}
		// Any repeat, not just an immediate self-reference: an A->B->A cycle
		// would otherwise spin until the cap.
		if seen[out.NextCursor] {
			return nil, fmt.Errorf("coreapi: listing bindings for automation %s: server repeated pagination cursor %q, so the list cannot be read completely", automationID, out.NextCursor)
		}
		seen[out.NextCursor] = true
		cursor = out.NextCursor
	}
	return nil, fmt.Errorf("coreapi: listing bindings for automation %s: still paginating after %d pages, so the list cannot be read completely", automationID, maxBindingPages)
}

// maxBindingPages bounds GetAutomationBindings's cursor walk so a server that
// pages without end fails the command instead of hanging it.
const maxBindingPages = 100

// GetRepoGroupAutomations reads back the automations held for a repo_group, via
// GET /repo-groups/{groupID}/automations.
//
// That route is NOT paginated, which is why this reads a single response while
// GetAutomationBindings above walks a cursor. Core's handler returns every row
// from a bare SELECT over repo_group_id, and its response carries no
// next_cursor field at all — so one response is the complete set, and there is
// no later page for this to miss.
func (c *Client) GetRepoGroupAutomations(ctx context.Context, repoGroupID string) ([]Automation, error) {
	u := fmt.Sprintf("%s/repo-groups/%s/automations", c.baseURL, url.PathEscape(repoGroupID))
	var out struct {
		Automations []Automation `json:"automations"`
	}
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return nil, err
	}
	return out.Automations, nil
}

// DeleteAutomation deletes an automation via DELETE /automations/{id}. Core
// sweeps its SpiceDB grants BEFORE dropping the row (automation.SweepAndDelete)
// and returns 204 whether or not the row still existed — deleting is
// idempotent, so there is no not-found case for a caller to handle.
func (c *Client) DeleteAutomation(ctx context.Context, automationID string) error {
	u := fmt.Sprintf("%s/automations/%s", c.baseURL, url.PathEscape(automationID))
	return c.do(ctx, http.MethodDelete, u, nil)
}

// AutomationGrantView is one repo grant as GET /automations/{id}/grants
// (COR-1127) reports it: SpiceDB truth, not the last body written to
// PUT .../grants — the two can diverge (an out-of-band revoke, a partial
// write), which is exactly the drift a reconciler needs to detect.
type AutomationGrantView struct {
	RepoGroupID string     `json:"repo_group_id,omitempty"`
	ExpiresAt   *time.Time `json:"expires_at,omitempty"`
}

// GetAutomationGrants reads an automation's current grants via GET
// /automations/{id}/grants. Unpaginated, per COR-1127: a grant set is bounded
// by its declaring repo group's own repo count, which core's handler keeps
// small in practice.
func (c *Client) GetAutomationGrants(ctx context.Context, automationID string) ([]AutomationGrantView, error) {
	u := fmt.Sprintf("%s/automations/%s/grants", c.baseURL, url.PathEscape(automationID))
	var out struct {
		AutomationID string                `json:"automation_id"`
		Grants       []AutomationGrantView `json:"grants"`
	}
	if err := c.do(ctx, http.MethodGet, u, &out); err != nil {
		return nil, err
	}
	return out.Grants, nil
}

// do performs the HTTP request and decodes a JSON body into out.
func (c *Client) do(ctx context.Context, method, url string, out any) error {
	req, err := http.NewRequestWithContext(ctx, method, url, nil)
	if err != nil {
		return fmt.Errorf("coreapi: new request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("coreapi: %s %s: %w", method, url, err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode == http.StatusNotFound {
		return ErrNotFound
	}
	if resp.StatusCode >= 400 {
		preview, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return &StatusError{Method: method, URL: url, Status: resp.StatusCode, Body: strings.TrimSpace(string(preview))}
	}
	if out == nil {
		return nil
	}
	if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
		return fmt.Errorf("coreapi: decode response: %w", err)
	}
	return nil
}

// ErrNotFound is returned when the API returns 404.
var ErrNotFound = errors.New("coreapi: not found")

// ErrNoHome is returned when core-api resolves an account but it carries no
// home jurisdiction. Distinct from ErrNotFound on purpose: both are PERMANENT
// for the read, but they are different facts ("no such account" vs. "an account
// with no placement"), and collapsing them cost us the ability to tell a deleted
// account from an unplaced one (ENT-1816). Prod currently has zero unplaced
// accounts; COR-1073 (home moves) is where that stops being theoretical.
var ErrNoHome = errors.New("coreapi: account has no home jurisdiction")

// StatusError is returned for a non-2xx, non-404 core-api response (404 maps
// to ErrNotFound instead, per the do/doJSON contract above) — a TYPED error,
// rather than the status embedded only in an opaque message string, so a
// caller can classify by HTTP status class. Introduced for the PlanetScale
// importer's row-vs-systemic error taxonomy (ENT-1173-adjacent "log and
// skip" work): a 401/403 from core-api means the WHOLE run's credentials are
// bad, not that this one row is malformed, so it needs to be distinguishable
// from a generic 4xx/5xx. Error() renders the identical text the old
// fmt.Errorf produced, so no caller depending on the message format breaks.
// InstallationTokenError is Core's non-200 answer to an installation token
// exchange. Denied tells a transient refusal apart from one that recurs until
// an operator acts, so a caller can stop retrying the latter.
type InstallationTokenError struct {
	Status int
	Body   string
}

func (e *InstallationTokenError) Error() string {
	return fmt.Sprintf("coreapi: installation token exchange: status %d: %s", e.Status, e.Body)
}

// installationGrantMissing is Core's body when GitHub's own mint was refused
// (its 422 on an installation that does not cover the repo), see entiredb
// core/api/sts_token.go. A bare 403 "permission denied" is a different case:
// the (workload, reason) pair is not admitted, which a Core deploy fixes.
const installationGrantMissing = "github installation grant missing"

// Denied reports whether Core refused the mint because no GitHub installation
// grant covers the repo. That answer repeats until someone installs the app,
// so a caller may stop retrying. Every other refusal, including a 403 for a
// reason Core has not admitted yet, reads as transient.
func (e *InstallationTokenError) Denied() bool {
	if e.Status != http.StatusForbidden {
		return false
	}
	var body struct {
		Error string `json:"error"`
	}
	return json.Unmarshal([]byte(e.Body), &body) == nil && body.Error == installationGrantMissing
}

type StatusError struct {
	Method string
	URL    string
	Status int
	Body   string
}

func (e *StatusError) Error() string {
	return fmt.Sprintf("coreapi: %s %s: status %d: %s", e.Method, e.URL, e.Status, e.Body)
}

// IsAuthFailure reports whether the response was a 401 Unauthorized or 403
// Forbidden — a credential/permission problem that will recur on every
// subsequent request, not a per-row anomaly (see the importer's
// rowErrorIsSystemic, which treats this as SYSTEMIC).
func (e *StatusError) IsAuthFailure() bool {
	return e.Status == http.StatusUnauthorized || e.Status == http.StatusForbidden
}

// AuthorAccount / LinkedIdentity / AuthorAccounts mirror entire-core's
// lookupAuthorAccounts response (COR-659). The two arms are independently
// optional: account-only, identity-only (external contributor, no Entire
// account), both, or neither (total miss).
type AuthorAccount struct {
	ID               string `json:"id"`
	HomeJurisdiction string `json:"homeJurisdiction"`
}
type LinkedIdentity struct {
	Provider string `json:"provider"`
	ID       string `json:"id"`
	Login    string `json:"login"`
}
type AuthorAccounts struct {
	Account    *AuthorAccount   `json:"account,omitempty"`
	Identities []LinkedIdentity `json:"identities,omitempty"`
}

// GitHubLogin returns the github identity's login if present, else "".
// Relies on entire-core returning at most one github identity per author, so
// the first match is the primary handle.
func (a AuthorAccounts) GitHubLogin() string {
	login, _, _ := a.GitHubIdentity()
	return login
}

// GitHubIdentity returns the author's primary GitHub login and numeric id (as
// the raw string Core sends), with ok=false when the author has no linked GitHub
// identity. Relies on entire-core returning at most one github identity per
// author, so the first match is the primary handle.
func (a AuthorAccounts) GitHubIdentity() (login, id string, ok bool) {
	for _, idn := range a.Identities {
		if idn.Provider == "github" {
			return idn.Login, idn.ID, true
		}
	}
	return "", "", false
}

// authorAccountsBatchSize bounds how many emails ride a single /author-accounts
// POST. Core resolves per email — not a set-based query: each email is a short
// identity chain (negative-cache -> verified_emails -> GitHub handle -> account) of
// a few reads, some on the global pool (cross-region round trips from a
// non-primary-region core), fanned out only ~8 at a time. So a batch's resolve time
// scales with its size in dozens of serialized cross-region rounds, against the
// caller's 10s timeout, and any one chain's error aborts the whole batch. A modest
// batch keeps each request well under that and shrinks the retry blast radius; the
// merged result is identical to a single call — Core keys each result by its input
// email, so batches never collide.
const authorAccountsBatchSize = 100

// AuthorAccounts resolves commit author emails → account + linked identities,
// via entire-core's internal-mTLS lookupAuthorAccounts (POST /author-accounts).
// The result is keyed by the *input* email (Core echoes the input keys; do not
// re-normalize). Emails absent from the response map to the zero AuthorAccounts.
//
// Emails are resolved in batches of authorAccountsBatchSize per POST and the
// per-batch results merged, keeping each request body and Core-side resolve
// bounded regardless of how large the input set is.
func (c *Client) AuthorAccounts(ctx context.Context, emails []string) (map[string]AuthorAccounts, error) {
	res := make(map[string]AuthorAccounts, len(emails))
	u := c.baseURL + "/author-accounts"
	for start := 0; start < len(emails); start += authorAccountsBatchSize {
		end := start + authorAccountsBatchSize
		if end > len(emails) {
			end = len(emails)
		}
		var out struct {
			Results map[string]AuthorAccounts `json:"results"`
		}
		if err := c.doJSON(ctx, http.MethodPost, u, map[string]any{"emails": emails[start:end]}, &out); err != nil {
			return nil, err
		}
		for email, acct := range out.Results {
			res[email] = acct
		}
	}
	return res, nil
}

type RepoForge string

const (
	RepoForgeGitHub RepoForge = "github"
	RepoForgeEntire RepoForge = "entire"
)

// Known reports whether f is one of the admitted forge values. The single
// definition of the forge domain — every "is this a forge we serve" check must
// call this rather than re-spelling the set, so a new forge is admitted in one
// place.
func (f RepoForge) Known() bool {
	return f == RepoForgeGitHub || f == RepoForgeEntire
}

// RepoName is a repo's globally-consolidated display identity, as served by the
// batch resolve below: the human "org/repo" full name, forge, and visibility.
// It is the shown-not-stored fact the /me foreign-repo resolver merges into a
// foreign row.
type RepoName struct {
	FullName string
	Forge    RepoForge
	Private  bool
}

// ResolveRepoNames batch-resolves repo ULIDs → their consolidated display name,
// forge, and visibility via entire-core's global repo view (POST /repos/names).
// It is the last-resort resolver for the /me surface: a foreign repo with no
// placement in the reader cell has no local metadata, so the identity is fetched
// from Core at read time and shown, not stored.
//
// Access-gated by the CALLER's bearer, which the transport forwards (this client
// is built per request over a bearer-forwarding transport, NOT the workload cert):
// Core reveals a name only for a repo the bearer can pull, exactly as its
// consolidated repo list already does — the same forward-the-bearer posture the
// gateway applies to proxied reads. A repo the caller cannot pull, or that Core
// cannot resolve, is simply omitted from the result (like AccountIdentities), so
// the caller degrades to the bare id rather than leaking a name or failing.
//
// The result is keyed by the input repoId; ids absent from the response map to no
// entry. GetRepo can't serve this because it omits the path/name for foreign/mirror
// rows, which is why this batch companion exists.
func (c *Client) ResolveRepoNames(ctx context.Context, repoIDs []string) (map[string]RepoName, error) {
	if len(repoIDs) == 0 {
		return map[string]RepoName{}, nil
	}
	u := c.baseURL + "/repos/names"
	var out struct {
		Repos []struct {
			RepoID    string    `json:"repoId"`
			FullName  string    `json:"fullName"`
			Forge     RepoForge `json:"provider"`
			IsPrivate bool      `json:"isPrivate"`
		} `json:"repos"`
	}
	if err := c.doJSON(ctx, http.MethodPost, u, map[string]any{"repoIds": repoIDs}, &out); err != nil {
		return nil, err
	}
	res := make(map[string]RepoName, len(out.Repos))
	for _, r := range out.Repos {
		res[r.RepoID] = RepoName{FullName: r.FullName, Forge: r.Forge, Private: r.IsPrivate}
	}
	return res, nil
}

const providerGitHub = "github"

// AccountHandle is one of an account's linked identity handles.
type AccountHandle struct {
	Provider       string `json:"provider"`
	Handle         string `json:"handle"`
	ProviderUserID string `json:"providerUserId"`
	IsPrimary      bool   `json:"isPrimary"`
}

// AccountIdentity is one account's linked handles across every provider, plus
// its Core-known display name, avatar, and username. Each is "" when Core
// has none for the account — never a placeholder.
type AccountIdentity struct {
	Handles     []AccountHandle
	DisplayName string
	AvatarURL   string
	Username    string
}

// GitHubIdentity returns the account's primary GitHub handle and provider id,
// falling back to its first GitHub handle when none is marked primary. Core
// also sorts primary-first, but selecting on the flag keeps this correct
// independently of the order it sends.
func (a AccountIdentity) GitHubIdentity() (login, id string, ok bool) {
	var first *AccountHandle
	for i, h := range a.Handles {
		if h.Provider != providerGitHub {
			continue
		}
		if h.IsPrimary {
			return h.Handle, h.ProviderUserID, true
		}
		if first == nil {
			first = &a.Handles[i]
		}
	}
	if first == nil {
		return "", "", false
	}
	return first.Handle, first.ProviderUserID, true
}

func (a AccountIdentity) GitHubLogin() string {
	login, _, _ := a.GitHubIdentity()
	return login
}

// IsZero reports whether Core returned nothing for the account: no handle, display
// name, avatar, or username.
func (a AccountIdentity) IsZero() bool {
	return len(a.Handles) == 0 && a.DisplayName == "" && a.AvatarURL == "" && a.Username == ""
}

func NewGitHubIdentity(login, id string) AccountIdentity {
	return AccountIdentity{Handles: []AccountHandle{{Provider: providerGitHub, Handle: login, ProviderUserID: id, IsPrimary: true}}}
}

// ParseGitHubID parses Core's raw string GitHub id (LinkedIdentity.ID /
// AccountHandle.ProviderUserID) to a nullable int64: "" or an unparseable value
// → nil (treated as no id). GitHub numeric ids fit comfortably in int64, the
// BIGINT column's range.
func ParseGitHubID(s string) *int64 {
	if s == "" {
		return nil
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return nil
	}
	return &n
}

// AccountIdentities batch-resolves account ULIDs → linked identity handles, via
// entire-core's internal-mTLS read (POST /accounts/identities). The
// result is keyed by accountId; an account with no handle at all is omitted by
// Core and absent from the map, but one with only a non-GitHub handle still
// gets a row.
func (c *Client) AccountIdentities(ctx context.Context, accountIDs []string) (map[string]AccountIdentity, error) {
	if len(accountIDs) == 0 {
		return map[string]AccountIdentity{}, nil
	}
	u := c.baseURL + "/accounts/identities"
	var out struct {
		Identities []struct {
			AccountID   string          `json:"accountId"`
			Handles     []AccountHandle `json:"handles"`
			DisplayName *string         `json:"displayName"`
			AvatarURL   string          `json:"avatarUrl,omitempty"`
			Username    string          `json:"username,omitempty"`
		} `json:"identities"`
	}
	if err := c.doJSON(ctx, http.MethodPost, u, map[string]any{"accountIds": accountIDs}, &out); err != nil {
		return nil, err
	}
	res := make(map[string]AccountIdentity, len(out.Identities))
	for _, id := range out.Identities {
		var displayName string
		if id.DisplayName != nil {
			displayName = *id.DisplayName
		}
		res[id.AccountID] = AccountIdentity{Handles: id.Handles, DisplayName: strings.TrimSpace(displayName), AvatarURL: id.AvatarURL, Username: id.Username}
	}
	return res, nil
}

// doJSON performs an HTTP request with a JSON request body, decoding the JSON
// response into out. Mirrors do's error handling. The 404→ErrNotFound branch is
// inert for the batch POST callers (AuthorAccounts/AccountIdentities): their
// contract is "absent keys omitted, not 404" — a 404 from those paths means a
// misrouted request, and callers treat it as a generic resolve failure (degrade).
func (c *Client) doJSON(ctx context.Context, method, url string, body, out any) error {
	return c.doJSONHeaders(ctx, method, url, body, out, nil)
}

func (c *Client) doJSONHeaders(ctx context.Context, method, url string, body, out any, headers map[string]string) error {
	buf, err := json.Marshal(body)
	if err != nil {
		return fmt.Errorf("coreapi: marshal request: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, method, url, bytes.NewReader(buf))
	if err != nil {
		return fmt.Errorf("coreapi: new request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")
	for key, value := range headers {
		req.Header.Set(key, value)
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("coreapi: %s %s: %w", method, url, err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode == http.StatusNotFound {
		return ErrNotFound
	}
	if resp.StatusCode >= 400 {
		preview, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return &StatusError{Method: method, URL: url, Status: resp.StatusCode, Body: strings.TrimSpace(string(preview))}
	}
	if out == nil {
		return nil
	}
	if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
		return fmt.Errorf("coreapi: decode response: %w", err)
	}
	return nil
}

// maxPlausibleExpiresIn bounds a reported expires_in before it is converted.
// GitHub App installation tokens last ~1h, so anything beyond a day is a
// producer bug rather than a long-lived credential — and converting it is
// unsafe regardless: a float->int64 conversion whose value is out of range is
// IMPLEMENTATION-DEPENDENT in Go, saturating to MaxInt64 on arm64 but returning
// MinInt64 on amd64. Unguarded, one absurd number silently yields an expiry in
// either 2318 or 1734 depending on the build host.
const maxPlausibleExpiresIn = 24 * time.Hour

// expiresInToExpiry turns an expires_in into an absolute expiry, reporting the
// zero Time for anything it cannot use.
//
// It never fails the caller. expires_in is not required for the access_token to
// be usable, so a shape this cannot parse must cost the expiry and nothing else.
// Decoding it strictly alongside access_token would instead fail the whole mint
// on a value previously ignored outright, turning a cosmetic wire difference
// into a dead credential and a blocking gate.
//
// A negative expires_in is honoured as a past instant, so a caller's freshness
// check declines the token rather than mistaking "already expired" for "no
// expiry reported". Zero is honoured the same way — it is what an issuer
// computing whole seconds emits for a token with under a second left.
//
// Note this is deliberately NOT identical to changeforge's tokenExpiresAt, which
// reads the same field off the same endpoint: that one collapses non-positive
// values to "unknown". Divergent on purpose (see this doc's paragraph above),
// and they cannot share code — changeforge imports nothing from this repo.
func expiresInToExpiry(raw json.RawMessage, now time.Time) time.Time {
	// An absent or explicitly null field means "not reported". json.Unmarshal of
	// null returns nil error and leaves the target UNTOUCHED, so without this
	// check a null would read as a reported zero, i.e. "already expired".
	if len(raw) == 0 || string(raw) == "null" {
		return time.Time{}
	}
	var seconds float64
	if err := json.Unmarshal(raw, &seconds); err != nil {
		return time.Time{}
	}
	switch {
	case math.IsNaN(seconds), math.IsInf(seconds, 0):
		return time.Time{}
	case seconds > maxPlausibleExpiresIn.Seconds():
		// Implausible. Report it as unreported rather than clamping to a
		// long window: the caller bounds an unknown lifetime tightly.
		return time.Time{}
	case seconds < -maxPlausibleExpiresIn.Seconds():
		return now.Add(-maxPlausibleExpiresIn)
	}
	return now.Add(time.Duration(seconds * float64(time.Second)))
}

package auth

import (
	"context"
	"errors"
	"log/slog"
	"strings"
	"sync"
	"time"

	"golang.org/x/sync/singleflight"
)

// ApprovalVerdict is the outcome of an account-approval check (COR-940). It
// mirrors entire-core's management-plane gate: 403 only on a confirmed deny,
// retryable on a lookup failure (COR-631 — an unavailable credential is not a
// verdict).
type ApprovalVerdict int

const (
	VerdictApproved ApprovalVerdict = iota
	VerdictWaitlisted
	VerdictUnavailable
)

// ErrAccountNotFound is the lookup's signal that no account row exists (a reaped
// account) — treated as waitlisted, fail closed. The wiring adapter maps
// coreapi's not-found to this so the auth package stays free of the coreapi
// import; any other lookup error is unavailable.
var ErrAccountNotFound = errors.New("auth: account not found")

// serviceAccountPrefix marks machine identities, out of the waitlist by
// construction (provisioned by an approved org manager), so the checker approves
// them without a lookup — mirroring core's IsServiceAccount carve-out.
const serviceAccountPrefix = "svc_"

const (
	defaultApprovalTTL = 60 * time.Second
	// approvalCacheMax hard-caps the verdict cache. Expiry cleanup happens on read
	// (see cached), so this only bounds a churn of distinct callers whose entries
	// are never re-read; a per-region API stays well under it.
	approvalCacheMax = 16384
)

// ApprovalLookup fetches an account's live approved flag. A nil *bool means the
// account exists but Core predates the approved field; ErrAccountNotFound means
// no such account; any other error is a lookup failure.
type ApprovalLookup func(ctx context.Context, accountID string) (*bool, error)

// ApprovalChecker resolves an account's waitlist state for the authenticated
// HTTP surface, backed by a live Core lookup behind a short TTL cache. It is a
// process singleton (one lookup client), safe for concurrent use. Approved and
// waitlisted verdicts are cached for the TTL; an unavailable verdict is never
// cached, so a transient Core blip resolves on the next request.
type ApprovalChecker struct {
	lookup ApprovalLookup
	ttl    time.Duration

	mu    sync.Mutex
	cache map[string]cachedVerdict

	// flight collapses concurrent cold-cache lookups for one account into a
	// single outbound call (a request fan-out otherwise stampedes Core).
	flight singleflight.Group
}

type cachedVerdict struct {
	verdict ApprovalVerdict
	expiry  time.Time
}

// NewApprovalChecker builds a checker over lookup. A non-positive ttl defaults
// to defaultApprovalTTL.
func NewApprovalChecker(lookup ApprovalLookup, ttl time.Duration) *ApprovalChecker {
	if ttl <= 0 {
		ttl = defaultApprovalTTL
	}
	return &ApprovalChecker{
		lookup: lookup,
		ttl:    ttl,
		cache:  make(map[string]cachedVerdict),
	}
}

// Check resolves accountID's approval verdict, serving a fresh cached entry when
// present.
func (c *ApprovalChecker) Check(ctx context.Context, accountID string) ApprovalVerdict {
	if strings.HasPrefix(accountID, serviceAccountPrefix) {
		return VerdictApproved
	}
	if v, ok := c.cached(accountID); ok {
		return v
	}
	v, _, _ := c.flight.Do(accountID, func() (any, error) {
		if v, ok := c.cached(accountID); ok {
			return v, nil
		}
		// Detach the leader's request context: collapsed followers share this one
		// lookup, so a leader disconnecting mid-flight must not cancel it and turn
		// every waiter's verdict into a spurious VerdictUnavailable.
		verdict := c.resolve(context.WithoutCancel(ctx), accountID)
		if verdict != VerdictUnavailable {
			c.store(accountID, verdict)
		}
		return verdict, nil
	})
	return v.(ApprovalVerdict)
}

// resolve maps a live lookup to a verdict.
func (c *ApprovalChecker) resolve(ctx context.Context, accountID string) ApprovalVerdict {
	approved, err := c.lookup(ctx, accountID)
	switch {
	case errors.Is(err, ErrAccountNotFound):
		return VerdictWaitlisted
	case err != nil:
		slog.WarnContext(ctx, "auth: approval lookup failed", slog.String("account_id", accountID), slog.String("error", err.Error()))
		return VerdictUnavailable
	case approved == nil:
		// Core predates the approved field; allow until it ships. The cache
		// bounds this warning to once per account per TTL.
		slog.WarnContext(ctx, "auth: approval flag absent, allowing", slog.String("account_id", accountID))
		return VerdictApproved
	case *approved:
		return VerdictApproved
	default:
		return VerdictWaitlisted
	}
}

// cached returns accountID's live verdict, evicting the entry when it has
// expired so a stale read cleans up after itself instead of leaving the key for
// a later sweep.
func (c *ApprovalChecker) cached(accountID string) (ApprovalVerdict, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.cache[accountID]
	if !ok {
		return 0, false
	}
	if time.Now().After(e.expiry) {
		delete(c.cache, accountID)
		return 0, false
	}
	return e.verdict, true
}

func (c *ApprovalChecker) store(accountID string, v ApprovalVerdict) {
	c.mu.Lock()
	defer c.mu.Unlock()
	// Hard-cap the cache: once full, drop an arbitrary entry to make room. The
	// evicted account just re-resolves on its next request — a cache miss, never a
	// wrong verdict. store only ever inserts a new key (a hit returns before it,
	// and cached evicts an expired key before the miss), so this bounds len.
	if len(c.cache) >= approvalCacheMax {
		for k := range c.cache {
			delete(c.cache, k)
			break
		}
	}
	c.cache[accountID] = cachedVerdict{verdict: v, expiry: time.Now().Add(c.ttl)}
}

