	})
}

func (r *coreProjectRouteResolver) ByReference(ctx context.Context, host, name string) (ProjectRoute, error) {
	resolved, err := r.publicClient(ctx).ResolveProjectFor(ctx, host, name, capabilityModeFrom(ctx))
	if err != nil {
		return ProjectRoute{}, err
	}
	if resolved.Reference.Host != host || !strings.EqualFold(resolved.Reference.Project, name) {
		return ProjectRoute{}, fmt.Errorf("core returned unexpected project reference %q/%q", resolved.Reference.Host, resolved.Reference.Project)
	}
	return ProjectRoute{
		ID: resolved.Project.ID, Name: resolved.Reference.Project, Host: host,
		CanManageTrails:     resolved.Project.Capabilities.CanManageTrails,
		CanManageAgents:     resolved.Project.Capabilities.CanManageAgents,
		DisplayCapabilities: resolved.Mode == coreapi.CapabilitiesDisplay,
		Jurisdiction:        resolved.Project.Region, PrimaryProcessingCell: resolved.Project.PrimaryProcessingCell,
	}, nil
}

func (r *coreProjectRouteResolver) CanManageByID(ctx context.Context, projectID string) (bool, error) {
	project, err := r.publicClient(ctx).ProjectCapabilitiesByIDFor(ctx, projectID, capabilityModeFrom(ctx))
	if err != nil {
		return false, err
	}
	return project.Capabilities.CanManageTrails, nil
}

// ProjectRouteBatchResolver is the optional batch form of ByID.
type ProjectRouteBatchResolver interface {
	ByIDs(context.Context, []string) (map[string]ProjectRoute, error)
}

// projectRoutesByIDs resolves projectIDs in one directory read when the
// resolver supports it, otherwise one ByID per id. Unknown ids are absent.
func projectRoutesByIDs(ctx context.Context, routes ProjectRouteResolver, projectIDs []string) (map[string]ProjectRoute, error) {
	if batch, ok := routes.(ProjectRouteBatchResolver); ok {
		return batch.ByIDs(ctx, projectIDs)
	}
	out := make(map[string]ProjectRoute, len(projectIDs))
	for _, id := range projectIDs {
		route, err := routes.ByID(ctx, id)
		if errors.Is(err, coreapi.ErrNotFound) {
			continue
		}
		if err != nil {
			return nil, err
		}
		out[id] = route
	}
	return out, nil
}

// projectDirectoryChunkSize bounds one BatchGet so a large membership stays
// within the internal client's per-request timeout.
const projectDirectoryChunkSize = 100

func (r *coreProjectRouteResolver) ByIDs(ctx context.Context, projectIDs []string) (map[string]ProjectRoute, error) {
	if r.internal == nil {
		return nil, fmt.Errorf("core project directory unavailable")
	}
	out := make(map[string]ProjectRoute, len(projectIDs))
	for chunk := range slices.Chunk(projectIDs, projectDirectoryChunkSize) {
		projects, err := r.internal.ProjectsByIDs(ctx, chunk)
		if err != nil {
			return nil, err
		}
		for id, project := range projects {
			out[id] = ProjectRoute{
				ID: project.ID, Name: project.Name,
				Jurisdiction: project.Region, PrimaryProcessingCell: project.PrimaryProcessingCell,
			}
		}
	}
	return out, nil
}

func (r *coreProjectRouteResolver) ByID(ctx context.Context, projectID string) (ProjectRoute, error) {
	if r.internal == nil {
		return ProjectRoute{}, fmt.Errorf("core project directory unavailable")
	}
	project, err := r.internal.ProjectByID(ctx, projectID)
	if err != nil {
		return ProjectRoute{}, err
	}
	return ProjectRoute{
		ID: project.ID, Name: project.Name,
		Jurisdiction: project.Region, PrimaryProcessingCell: project.PrimaryProcessingCell,
	}, nil
}

