858			// The waitlist gate is an account-onboarding concept; an automation
859			// principal has no account id and is never subject to it (it is
860			// provisioned by the automation token exchange, not the account
861			// signup flow).
862			if accountID, ok := id.Subject.AccountID(); ok {
863				if enforceApproval(api, ctx, deps.Approval, reqCtx, accountID) {
864					return
865				}
866			}
867			next(huma.WithContext(ctx, reqCtx))
868		}
869	}
870	
871	// enforceApproval applies the waitlist gate to an already-authenticated caller
872	// (COR-940), returning true — after writing the response — when the request must
873	// not proceed. A nil checker is a no-op. Fail-closed: only an explicit approved
874	// verdict passes; waitlisted is 403, and anything else (unavailable, or a future
875	// verdict) is a retryable 503.
876	func enforceApproval(api huma.API, ctx huma.Context, approval *auth.ApprovalChecker, reqCtx context.Context, accountID string) bool {
877		if approval == nil {
878			return false
879		}
880		switch approval.Check(reqCtx, accountID) {
881		case auth.VerdictApproved:
882			return false
883		case auth.VerdictWaitlisted:
884			_ = huma.WriteErr(api, ctx, http.StatusForbidden, "waitlisted: your account is pending approval")
885		default: // VerdictUnavailable, or any future verdict → fail closed, retryable
886			_ = huma.WriteErr(api, ctx, http.StatusServiceUnavailable, "approval check temporarily unavailable")
887		}
888		return true
889	}
890	
891	// jwksRetryAfter is in seconds.
892	const jwksRetryAfter = "5"
893	
894	// writeAuthnErr answers a JWKS outage with 503, else 401.
895	func writeAuthnErr(api huma.API, ctx huma.Context, err error) {
896		if errors.Is(err, auth.ErrJWKSUnavailable) {
897			// The cause can name the JWKS URL.
898			ctx.SetHeader("Retry-After", jwksRetryAfter)
899			_ = huma.WriteErr(api, ctx, http.StatusServiceUnavailable, "authentication temporarily unavailable")
900			return
901		}
902		_ = huma.WriteErr(api, ctx, http.StatusUnauthorized, "authentication required", err)
903	}
904	
905	// optionalAuth attaches the caller's Identity + bearer when a valid token is
906	// present, but never 401s: a token-less (or invalid-token) request proceeds
907	// anonymously and the handler fail-closes on access. A JWKS outage with a
908	// token is 503. The shared-session transcript read is the only optional-auth
909	// route — the BFF calls it unauthenticated for an anonymous viewer. A caller
910	// who does present a valid token takes the live (authorized) branch and is
911	// waitlist-gated exactly like requireAuth; only the anonymous path bypasses
912	// the gate.
913	func optionalAuth(api huma.API, deps *baseDeps) func(huma.Context, func(huma.Context)) {
914		return func(ctx huma.Context, next func(huma.Context)) {
915			tok := auth.BearerToken(ctx.Header("Authorization"))
916			if tok == "" {
917				next(ctx) // anonymous: no identity in context
918				return
919			}
920			id, err := deps.Authenticator.Authenticate(ctx.Context(), httpRequestFromHuma(ctx))
921			if errors.Is(err, auth.ErrJWKSUnavailable) {
922				setAuthnRejectCause(ctx.Context(), err)
923				writeAuthnErr(api, ctx, err)
924				return
925			}
926			if err != nil {
927				next(ctx) // present-but-invalid token → treat as anonymous, not a hard 401
928				return
929			}
930			reqCtx := auth.WithBearer(auth.WithIdentity(ctx.Context(), id), tok)
931			recordCaller(reqCtx, id) // hand the caller up to the capture middleware
932			if accountID, ok := id.Subject.AccountID(); ok {
933				if enforceApproval(api, ctx, deps.Approval, reqCtx, accountID) {
934					return
935				}
936			}
937			next(huma.WithContext(ctx, reqCtx))
938		}
939	}
940	
941	// httpRequestFromHuma reconstructs the minimal http.Request the
942	// Authenticator needs from a Huma context (bearer only).
943	func httpRequestFromHuma(ctx huma.Context) *http.Request {
944		req := &http.Request{Header: http.Header{}}
945		if v := ctx.Header("Authorization"); v != "" {
946			req.Header.Set("Authorization", v)
947		}
948		return req.WithContext(ctx.Context())
949	}

