package httpapi

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/auth"
	"github.com/entirehq/entire-api/internal/coreapi"
	"github.com/entirehq/entire-api/internal/frontendlink"
	"github.com/entirehq/entire-api/internal/store"
)

// TrailParentReference is navigation, not a projection of project intent or
// permissions. Path is API-relative to the project's cell. Resolve the cell ID
// through Core's cluster catalog; never manufacture a URL from a jurisdiction.
type TrailParentReference struct {
	ID                    string `json:"id"`
	Number                int    `json:"number" doc:"Project-local Trail number, not the repository Trail number"`
	ProjectID             string `json:"project_id"`
	Host                  string `json:"host" enum:"gh,et"`
	Project               string `json:"project" doc:"Canonical public project name, never its internal storage name"`
	Path                  string `json:"path" doc:"API-relative parent detail path in the project's cell"`
	Jurisdiction          string `json:"jurisdiction" doc:"Project jurisdiction from Core; empty when unresolved"`
	PrimaryProcessingCell string `json:"primary_processing_cell" doc:"Project cell ID from Core; empty when unassigned (do not infer from the repository)"`
	URL                   string `json:"url,omitempty" doc:"Web app page for the parent Trail; absent when this deployment has no frontend origin"`
}

// resolveChangeParents is shared by repo lists, detail, and the personal list.
// Membership in a parent's CURRENT scope plus Pull on that backing repo grants
// parent read access under authorizeTrailRead. Project View is not required.
// Hydration is one bounded store batch, one bulk Pull check, and cached lookups
// per repo/project/reference, not per Change. It never widens the requested IDs.
func resolveChangeParents(ctx context.Context, deps *RepoActivityDeps, ids []string) (map[string]*TrailParentReference, error) {
	candidates, err := deps.Store.ChangeParents(ctx, ids)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: trail parents", err)
	}
	parents := make(map[string]*TrailParentReference)
	if len(candidates) == 0 {
		return parents, nil
	}
	repoIDs := make([]string, 0, len(candidates))
	for _, p := range candidates {
		repoIDs = append(repoIDs, p.RepoID)
	}
	available, err := readableChangeRepositories(ctx, deps, repoIDs, false)
	if err != nil {
		return nil, err
	}
	directory := make(map[string]*ProjectRoute)
	references := make(map[string]*ProjectRoute)
	for _, p := range candidates {
		if !available[p.RepoID] || !p.Forge.Known() {
			continue
		}
		if deps.ProjectRoutes == nil {
			return nil, huma.Error503ServiceUnavailable("project resolution unavailable")
		}
		parent, err := changeParentReference(ctx, deps.ProjectRoutes, p, directory, references)
		if err != nil {
			return nil, err
		}
		if parent != nil {
			parent.URL = frontendlink.ProjectTrail(deps.Config.FrontendBaseURL, parent.Host, parent.Project, parent.Number)
			parents[p.ChangeID] = parent
		}
	}
	return parents, nil
}

// cachedParentProject caches absent/denied lookups as well as successes. A Core
// outage remains an error: reporting it as parentless could prompt a client to
// create duplicate intent. No unverified name or raw project ID is returned.
func cachedParentProject(cache map[string]*ProjectRoute, key string, load func() (ProjectRoute, error)) (*ProjectRoute, error) {
	if p, ok := cache[key]; ok {
		return p, nil
	}
	p, err := load()
	if err != nil {
		var status *coreapi.StatusError
		if errors.Is(err, coreapi.ErrNotFound) || (errors.As(err, &status) && (status.Status == http.StatusForbidden || status.Status == http.StatusNotFound)) {
			cache[key] = nil
			return nil, nil
		}
		if coreUnauthorized(err) {
			return nil, huma.Error503ServiceUnavailable("core: project directory unauthorized", err)
		}
		return nil, projectRouteError(err)
	}
	cache[key] = &p
	return &p, nil
}

func changeParentReference(ctx context.Context, routes ProjectRouteResolver, p store.ChangeParent, directory, references map[string]*ProjectRoute) (*TrailParentReference, error) {
	project, err := cachedParentProject(directory, p.ProjectID, func() (ProjectRoute, error) {
		return routes.ByID(ctx, p.ProjectID)
	})
	if err != nil || project == nil {
		return nil, err
	}
	if project.ID != p.ProjectID {
		return nil, nil
	}
	host, name := "et", project.Name
	switch p.Forge {
	case coreapi.RepoForgeEntire:
		// Native public names are directory names. This preserves repo-only
		// readers without requiring a project-wide public lookup.
	case coreapi.RepoForgeGitHub:
		host = "gh"
		var ok bool
		name, _, ok = strings.Cut(p.FullName, "/")
		if !ok || !validProjectRouteName(host, name) {
			return nil, nil
		}
		if automationCaller(ctx) {
			// Core's public resolve rejects automation principals. The owner comes
			// from the parent's own backing repo in this cell, so it can be stale.
			if !strings.HasPrefix(project.Name, "gh:mirrors:") {
				return nil, nil
			}
		} else {
			referenced, err := cachedParentProject(references, host+"/"+strings.ToLower(name), func() (ProjectRoute, error) {
				route, err := routes.ByReference(ctx, host, name)
				if coreUnauthorized(err) {
					// The caller authenticated here; Core declining its bearer leaves
					// the parent unresolved rather than failing the authorised read.
					slog.WarnContext(ctx, "trails: parent project reference unauthorized; parent unresolved",
						slog.String("owner", name), slog.Any("err", err))
					return route, coreapi.ErrNotFound
				}
				return route, err
			})
			if err != nil || referenced == nil {
				return nil, err
			}
			// A stale repository name may now name someone else's namespace.
			// Only Core's canonical resolution to THIS parent project admits it.
			if referenced.ID != p.ProjectID {
				return nil, nil
			}
			name = referenced.Name
		}
	default:
		return nil, nil
	}
	if !validProjectRouteName(host, name) {
		return nil, nil
	}
	return &TrailParentReference{
		ID: p.ID, Number: p.Number, ProjectID: p.ProjectID,
		Host: host, Project: strings.ToLower(name), Path: projectTrailPath(host, name, p.ID),
		Jurisdiction: project.Jurisdiction, PrimaryProcessingCell: project.PrimaryProcessingCell,
	}, nil
}

func automationCaller(ctx context.Context) bool {
	id := auth.FromContext(ctx)
	if id == nil {
		return false
	}
	_, ok := id.Subject.Automation()
	return ok
}

func coreUnauthorized(err error) bool {
	var status *coreapi.StatusError
	return errors.As(err, &status) && status.Status == http.StatusUnauthorized
}

