func projectTrailDirectory(ctx context.Context, deps *RepoActivityDeps, projectIDs []string, jurisdiction string) (map[string]ProjectCatalogEntry, int, error) {
	if len(projectIDs) == 0 {
		return map[string]ProjectCatalogEntry{}, 0, nil
	}
	repos, err := deps.Store.ProjectGitHubRepos(ctx, projectIDs)
	if err != nil {
		return nil, 0, projectTrailStoreError("store: project GitHub repos", err)
	}
	owners := projectGitHubOwners(ctx, deps.ForeignRepoNames, repos)
	routes, err := projectRoutesByIDs(ctx, deps.ProjectRoutes, projectIDs)
	if err != nil {
		return nil, 0, huma.Error503ServiceUnavailable("core: project directory", err)
	}
	projects := make(map[string]ProjectCatalogEntry, len(projectIDs))
	dropped := 0
	for _, projectID := range projectIDs {
		route, ok := routes[projectID]
		if !ok {
			dropped++
			continue
		}
		if !strings.EqualFold(route.Jurisdiction, jurisdiction) {
			continue
		}
		entry := ProjectCatalogEntry{ID: projectID, Name: route.Name, PublicName: route.Name, Provider: "entire", Forge: "et", Jurisdiction: route.Jurisdiction, PrimaryProcessingCell: route.PrimaryProcessingCell}
