				continue
			}
			entry.Name, entry.PublicName, entry.Provider, entry.Forge = owner, owner, "github", "gh"
		}
		if !validProjectRouteName(entry.Forge, entry.PublicName) {
			dropped++
			continue
		}
		projects[projectID] = entry
	}
	return projects, dropped, nil
}

func projectGitHubOwners(ctx context.Context, resolver ForeignRepoNameResolver, repos map[string]store.ProjectGitHubRepo) map[string]string {
