33	// resolveChangeParents is shared by repo lists, detail, and the personal list.
34	// Membership in a parent's CURRENT scope plus Pull on that backing repo grants
35	// parent read access under authorizeTrailRead. Project View is not required.
36	// Hydration is one bounded store batch, one bulk Pull check, and cached lookups
37	// per repo/project/reference, not per Change. It never widens the requested IDs.
38	func resolveChangeParents(ctx context.Context, deps *RepoActivityDeps, ids []string) (map[string]*TrailParentReference, error) {
39		candidates, err := deps.Store.ChangeParents(ctx, ids)
40		if err != nil {
41			return nil, huma.Error500InternalServerError("store: trail parents", err)
42		}
43		parents := make(map[string]*TrailParentReference)
44		if len(candidates) == 0 {
45			return parents, nil
46		}
47		repoIDs := make([]string, 0, len(candidates))
48		for _, p := range candidates {
49			repoIDs = append(repoIDs, p.RepoID)
50		}
51		available, err := readableChangeRepositories(ctx, deps, repoIDs, false)
52		if err != nil {
53			return nil, err
54		}
55		directory := make(map[string]*ProjectRoute)
56		references := make(map[string]*ProjectRoute)
57		for _, p := range candidates {
58			if !available[p.RepoID] || !p.Forge.Known() {
59				continue
60			}
61			if deps.ProjectRoutes == nil {
62				return nil, huma.Error503ServiceUnavailable("project resolution unavailable")
63			}
64			parent, err := changeParentReference(ctx, deps.ProjectRoutes, p, directory, references)
65			if err != nil {
66				return nil, err
67			}
68			if parent != nil {
69				parent.URL = frontendlink.ProjectTrail(deps.Config.FrontendBaseURL, parent.Host, parent.Project, parent.Number)
70				parents[p.ChangeID] = parent
71			}
72		}
73		return parents, nil
