77	// outage remains an error: reporting it as parentless could prompt a client to
78	// create duplicate intent. No unverified name or raw project ID is returned.
79	func cachedParentProject(cache map[string]*ProjectRoute, key string, load func() (ProjectRoute, error)) (*ProjectRoute, error) {
80		if p, ok := cache[key]; ok {
81			return p, nil
82		}
83		p, err := load()
84		if err != nil {
85			var status *coreapi.StatusError
86			if errors.Is(err, coreapi.ErrNotFound) || (errors.As(err, &status) && (status.Status == http.StatusForbidden || status.Status == http.StatusNotFound)) {
87				cache[key] = nil
88				return nil, nil
89			}
90			if coreUnauthorized(err) {
91				return nil, huma.Error503ServiceUnavailable("core: project directory unauthorized", err)
92			}
93			return nil, projectRouteError(err)
94		}
95		cache[key] = &p
96		return &p, nil
97	}
