99	func changeParentReference(ctx context.Context, routes ProjectRouteResolver, p store.ChangeParent, directory, references map[string]*ProjectRoute) (*TrailParentReference, error) {
100		project, err := cachedParentProject(directory, p.ProjectID, func() (ProjectRoute, error) {
101			return routes.ByID(ctx, p.ProjectID)
102		})
103		if err != nil || project == nil {
104			return nil, err
105		}
106		if project.ID != p.ProjectID {
107			return nil, nil
108		}
109		host, name := "et", project.Name
110		switch p.Forge {
111		case coreapi.RepoForgeEntire:
112			// Native public names are directory names. This preserves repo-only
113			// readers without requiring a project-wide public lookup.
114		case coreapi.RepoForgeGitHub:
115			host = "gh"
