124				if !strings.HasPrefix(project.Name, "gh:mirrors:") {
125					return nil, nil
126				}
127			} else {
128				referenced, err := cachedParentProject(references, host+"/"+strings.ToLower(name), func() (ProjectRoute, error) {
129					route, err := routes.ByReference(ctx, host, name)
130					if coreUnauthorized(err) {
131						// The caller authenticated here; Core declining its bearer leaves
132						// the parent unresolved rather than failing the authorised read.
133						slog.WarnContext(ctx, "trails: parent project reference unauthorized; parent unresolved",
134							slog.String("owner", name), slog.Any("err", err))
135						return route, coreapi.ErrNotFound
136					}
137					return route, err
138				})
139				if err != nil || referenced == nil {
