package ingest

import (
	"context"
	"errors"
	"time"

	"github.com/entirehq/entire-api/internal/coreapi"
)

// defaultNegativeTTL bounds how long an unresolved pusher stays cached without a
// home placement. Short enough that a live ingester recovers the placement once
// Core can resolve it (the account-by-id endpoint ships); long enough that a
// burst of the same unresolved pusher doesn't re-query Core on every commit.
const defaultNegativeTTL = 15 * time.Minute

// defaultResolveTTL bounds how long a positive author/pusher resolution stays
// cached. Modest, because an identity can change (a pusher's account state, a
// verified-email link that reassigns an author's account/login) — a miss just
// re-resolves against current Core state, so the TTL only trades a periodic
// re-query for staleness, never correctness.
const defaultResolveTTL = time.Hour

// resolveCacheSize caps the author and pusher resolver LRUs. A region-wide
// backfill streams far more distinct emails/ULIDs than a pod needs resident at
// once; the bound keeps memory flat while staying large enough to serve the hot
// set of a busy cell without thrashing.
const resolveCacheSize = 16384

// PusherResolver maps a pusher's account ULID to its home placement, caching
// results. It is three-valued, mirroring coreapi.AccountByID: an empty id, an
// unknown account (ErrNotFound) or one with no placement (ErrNoHome) resolves to
// (nil, nil) — PERMANENTLY unattributable, and never a guessed home; a transport
// error resolves to (nil, err) and is NOT cached, so the caller naks and
// redelivery re-resolves. Before ENT-1816 both collapsed to a bare nil, which
// let a Core outage look exactly like a deleted account.
//
// A positive result caches for resolveTTL and a negative for negativeTTL, both
// in a bounded LRU (resolveCacheSize entries) that can never grow without limit
// across a region-wide backfill. Resolving at ingest against current account
// state can never go stale onto the replayable ref event (nothing about
// placement is frozen there), and every expiry/eviction just re-resolves — so a
// later Core resolution is always picked up without a restart.
// Concurrency-safe; share one across pipeline workers.
type PusherResolver struct {
	core        AccountClient
	ttl         time.Duration // positive-entry lifetime
	negativeTTL time.Duration

	cache *boundedLRU[string, pusherEntry]
}

type pusherEntry struct {
	found bool
	acct  coreapi.Account
}

// NewPusherResolver builds a resolver over the given account lookup. A nil core
// (internal mTLS unconfigured) makes every Resolve return (nil, nil).
func NewPusherResolver(core AccountClient) *PusherResolver {
	return &PusherResolver{
		core:        core,
		ttl:         defaultResolveTTL,
		negativeTTL: defaultNegativeTTL,
		cache:       newBoundedLRU[string, pusherEntry](resolveCacheSize),
	}
}

// Enabled reports whether account resolution is wired at all (an internal-mTLS
// Core client is configured). False in local dev / an unconfigured deployment:
// there is no authority to ask, so a caller must NOT read a miss as "this
// account is unattributable" — see Flow.routableRecipient, which keeps
// attributing by id in that case so the publisher's single-region path still
// routes the forward locally.
func (r *PusherResolver) Enabled() bool { return r != nil && r.core != nil }

// Resolve returns the home placement for a pusher ULID. (nil, nil) means
// permanently unattributable — no such account, or one with no placement; a
// non-nil error means Core is unreachable and the caller should nak. Live cache
// hits (positive, or a still-valid negative) skip the Core call.
func (r *PusherResolver) Resolve(ctx context.Context, accountID string) (*coreapi.Account, error) {
	if accountID == "" || r.core == nil {
		return nil, nil
	}
	if acct, hit := r.cached(accountID); hit {
		return acct, nil
	}

	acct, err := r.core.AccountByID(ctx, accountID)
	if errors.Is(err, coreapi.ErrNotFound) || errors.Is(err, coreapi.ErrNoHome) {
		// Permanent for this id: cache the miss so a burst of the same deleted
		// account doesn't re-query Core on every commit.
		r.cache.put(accountID, pusherEntry{found: false}, r.negativeTTL)
		return nil, nil
	}
	if err != nil {
		// Transport error: do NOT cache, and hand it back rather than reporting
		// "unattributable" — the caller naks and redelivery re-resolves. Logging
		// lives at the caller, which knows which forward is being abandoned.
		return nil, err
	}
	a := *acct
	r.cache.put(accountID, pusherEntry{found: true, acct: a}, r.ttl)
	return &a, nil
}

// cached returns (account, true) on a live hit — a positive entry (nil-safe
// copy) or a still-valid negative (nil account). A miss or an expired entry
// (positive or negative) returns (nil, false) so the caller re-queries Core;
// expiry is enforced by the bounded LRU.
func (r *PusherResolver) cached(accountID string) (*coreapi.Account, bool) {
	e, ok := r.cache.get(accountID)
	if !ok {
		return nil, false
	}
	if e.found {
		acct := e.acct // copy; never hand out a pointer into the cache
		return &acct, true
	}
	return nil, true // negative still valid
}

