9		"strings"
10	)
11	
12	// Cluster is one data-plane cluster as GET /api/v1/clusters reports it.
13	//
14	// The two URLs are different hosts for different jobs and must not be derived
15	// from one another: PublicURL is the git data plane, APIURL the jurisdiction's
16	// entire-api. APIURL is keyed by jurisdiction rather than by cluster, so every
17	// cluster in a jurisdiction reports the same one.
18	type Cluster struct {
19		Slug         string `json:"slug"`
20		Jurisdiction string `json:"jurisdiction"`
21		PublicURL    string `json:"publicUrl"`
22		IsDefault    bool   `json:"isDefault"`
23		APIURL       string `json:"apiUrl,omitempty"`
24	}
25	
26	type clustersResponse struct {
27		Clusters []Cluster `json:"clusters"`
28	}
29	
30	// ListClusters returns the data-plane clusters attached to this control plane.
31	// Authentication is required but no per-cluster authorization: topology is
32	// shared infrastructure rather than a per-tenant resource.
33	func (c *Client) ListClusters(ctx context.Context) ([]Cluster, error) {
34		var out clustersResponse
35		if err := c.do(ctx, http.MethodGet, c.baseURL+"/clusters", &out); err != nil {
36			return nil, err
37		}
38		return out.Clusters, nil
39	}
40	
41	// ResolveCluster finds one cluster by slug, public host, or public URL, so a
42	// caller can name the cluster however they already have it written down. An
43	// empty name takes the control plane's default when it declares one.
44	//
45	// It refuses rather than guesses when several clusters are candidates: they
46	// are different environments holding different data, and picking one silently
47	// is how a load test runs against somewhere nobody meant.
48	func (c *Client) ResolveCluster(ctx context.Context, name string) (*Cluster, error) {
49		clusters, err := c.ListClusters(ctx)
50		if err != nil {
51			return nil, err
52		}
53		if len(clusters) == 0 {
54			return nil, fmt.Errorf("coreapi: this control plane reports no clusters: %w", ErrNotFound)
55		}
56	
57		wanted := clusterHostOf(name)
58		var matched []Cluster
59		for _, cluster := range clusters {
60			if wanted == "" {
61				if cluster.IsDefault {
62					matched = append(matched, cluster)
63				}
64				continue
65			}
66			if strings.EqualFold(cluster.Slug, wanted) || clusterHostOf(cluster.PublicURL) == wanted {
67				matched = append(matched, cluster)
68			}
69		}
70	
71		// Every candidate is collected rather than the first one taken, because
72		// two rows answering to one name means the topology is not what this
73		// caller assumed, and either answer could be the wrong environment.
74		if len(matched) > 1 {
75			if wanted == "" {
76				return nil, fmt.Errorf("coreapi: this control plane declares %d default clusters (%s); name one with --cluster",
77					len(matched), strings.Join(clusterNames(matched), ", "))
78			}
79			return nil, fmt.Errorf("coreapi: %q matches %d clusters (%s); name one by its public host",
80				name, len(matched), strings.Join(clusterNames(matched), ", "))
81		}
82	
83		var found *Cluster
84		if len(matched) == 1 {
85			found = &matched[0]
86		}
87		if found == nil {
88			if wanted == "" {
89				return nil, fmt.Errorf("coreapi: this control plane declares no default cluster; name one of: %s",
90					strings.Join(clusterNames(clusters), ", "))
91			}
92			return nil, fmt.Errorf("coreapi: no cluster named %q; this control plane has: %s: %w",
93				name, strings.Join(clusterNames(clusters), ", "), ErrNotFound)
94		}
95		if found.PublicURL == "" {
96			return nil, fmt.Errorf("coreapi: cluster %q reports no public URL, so it has no git host to push to", found.Slug)
97		}
98		// Documented as omitted when the jurisdiction has no entire-api, which a
99		// reader is told to treat as non-routable. Refuse here rather than hand
100		// back a cluster whose runs could never be read back.
101		if found.APIURL == "" {
102			return nil, fmt.Errorf("coreapi: cluster %q (jurisdiction %q) reports no entire-api host, so its runs cannot be read",
103				found.Slug, found.Jurisdiction)
104		}
105		return found, nil
106	}
107	
108	// clusterHostOf reduces a slug, bare host, host:port, or full public URL to a
109	// comparable lowercase form, matching how Core itself matches a caller-supplied
110	// cluster host against a stored public_url.
111	func clusterHostOf(raw string) string {
112		trimmed := strings.ToLower(strings.TrimSpace(raw))
113		if trimmed == "" {
114			return ""
115		}
116		if !strings.Contains(trimmed, "://") {
117			trimmed = "//" + trimmed
118		}
119		parsed, err := url.Parse(trimmed)
120		if err != nil || parsed.Hostname() == "" {
121			return strings.TrimPrefix(strings.ToLower(strings.TrimSpace(raw)), "//")
122		}
123		return parsed.Hostname()
124	}
125	
126	func clusterNames(clusters []Cluster) []string {
127		names := make([]string, 0, len(clusters))
128		for _, cluster := range clusters {
129			names = append(names, cluster.Slug)
130		}
131		sort.Strings(names)
132		return names
133	}
