// ListClusters returns the data-plane clusters attached to this control plane.
// Authentication is required but no per-cluster authorization: topology is
// shared infrastructure rather than a per-tenant resource.
func (c *Client) ListClusters(ctx context.Context) ([]Cluster, error) {
