// are different environments holding different data, and picking one silently
// is how a load test runs against somewhere nobody meant.
func (c *Client) ResolveCluster(ctx context.Context, name string) (*Cluster, error) {
	clusters, err := c.ListClusters(ctx)
	if err != nil {
		return nil, err
	}
	if len(clusters) == 0 {
		return nil, fmt.Errorf("coreapi: this control plane reports no clusters: %w", ErrNotFound)
	}

