	}
	if found == nil {
		if wanted == "" {
			return nil, fmt.Errorf("coreapi: this control plane declares no default cluster; name one of: %s",
				strings.Join(clusterNames(clusters), ", "))
		}
		return nil, fmt.Errorf("coreapi: no cluster named %q; this control plane has: %s: %w",
			name, strings.Join(clusterNames(clusters), ", "), ErrNotFound)
	}
