	// reader is told to treat as non-routable. Refuse here rather than hand
	// back a cluster whose runs could never be read back.
	if found.APIURL == "" {
		return nil, fmt.Errorf("coreapi: cluster %q (jurisdiction %q) reports no entire-api host, so its runs cannot be read",
			found.Slug, found.Jurisdiction)
	}
	return found, nil
}

// clusterHostOf reduces a slug, bare host, host:port, or full public URL to a
// comparable lowercase form, matching how Core itself matches a caller-supplied
// cluster host against a stored public_url.
func clusterHostOf(raw string) string {
	trimmed := strings.ToLower(strings.TrimSpace(raw))
	if trimmed == "" {
		return ""
	}
	if !strings.Contains(trimmed, "://") {
		trimmed = "//" + trimmed
	}
	parsed, err := url.Parse(trimmed)
	if err != nil || parsed.Hostname() == "" {
		return strings.TrimPrefix(strings.ToLower(strings.TrimSpace(raw)), "//")
	}
	return parsed.Hostname()
}

func clusterNames(clusters []Cluster) []string {
	names := make([]string, 0, len(clusters))
	for _, cluster := range clusters {
		names = append(names, cluster.Slug)
	}
	sort.Strings(names)
	return names
}

