	// ADR 20260720-native-mirroring). The lifecycle bus that carries the flag
	// (native_mirror.created / repo_group.primary_changed) is best-effort, but
	// ensureRepo just (re-)stamped this placement's group from a ref event — a
	// bus-independent path. When Core reports THIS placement as its group's
	// processing primary, heal the flag so a lost bus event can't leave the primary
	// suppressed by the facts-emission gate (processing_primary). Core returns no
	// primaries for a native-mirror placement read by its own ULID, so a mirror
	// never self-elects. Fills only the never-announced gap (see
	// store.SelfHealProcessingPrimary). Best-effort — a heal blip never fails
	// ingest; the next push retries idempotently.
	if p := repoMeta.Primaries; p != nil && p.Processing == repoID {
		if _, err := f.Store.SelfHealProcessingPrimary(ctx, repoID, time.Now().UTC()); err != nil {
			slog.WarnContext(ctx, "ingest: processing-primary self-heal failed (best-effort)",
				slog.Any("error", err), slog.String("repo_id", repoID))
		}
	}
	// Resolve + persist where this repo's checkpoints are stored (a separate
	// checkpoint repo declared in .entire/settings.json). Best-effort: never
	// fails ingest, and a transient read leaves the stored pointer untouched.
	f.resolveCheckpointRepo(ctx, rc, base, repoID, row.FullName, defaultBranch)
	return defaultBranch, nil
}

// upsertRepo writes the row. A native push can beat repo.detached here: the
// write-once forge guard refuses it, and when Core reports detached_at the row
// is detached from Core's answer, as the repo.detached handler would, and
// written again. Without detached_at the conflict stands and dead-letters.
func (f *Flow) upsertRepo(ctx context.Context, repoMeta *coreapi.Repo, row store.Repo) error {
	err := f.Store.UpsertRepo(ctx, row)
	if !errors.Is(err, store.ErrRepoForgeConflict) {
		return err
	}
	in, ok := store.DetachInputFromCore(repoMeta)
	if !ok {
		return err
	}
	res, derr := f.Store.DetachRepo(ctx, in)
	if errors.Is(derr, store.ErrDetachRepoInvalid) {
		return errors.Join(err, derr)
	}
	if derr != nil {
		return fmt.Errorf("ingest: detach repo %s after forge conflict: %w", row.ID, derr)
	}
	slog.InfoContext(ctx, "ingest: forge conflict on a detached repo; detached from Core",
		slog.String("repo_id", row.ID), slog.Bool("forge_changed", res.Detached))
	return f.Store.UpsertRepo(ctx, row)
}

// maybeResyncCheckpointRepo triggers a best-effort resync of a code repo's SEPARATE
// external checkpoints repo (ENT-1172). A git-refs-backend repo pushes its
// checkpoints to refs/entire/checkpoints/* on a DIFFERENT remote (its
// checkpoint_remote), and GitHub emits no webhook for pushes outside
// refs/heads/*|refs/tags/*, so mirror-pipeline never syncs that checkpoint repo on
// its own — sessions never surface. On a normal branch push we tell cell-local Core
// to resync it; Core resolves the placement → GitHub coords and publishes a
// synthetic push webhook onto the central stream, whose fanout does a full sync.
//
// Fires only when a separate checkpoint repo is on file (checkpoint_repo_id set, so
// CheckpointStorageRepoID != the code repo); self-hosted repos (identity) already get
// GitHub webhooks for their checkpoint branch and are skipped. Best-effort by design:
// every failure — the storage-repo lookup or the resync itself (see ResyncMirror for
// the status mapping) — is logged and swallowed. Callers MUST NOT block or fail
// ingestion on it, and Core minute-buckets the synthetic webhook so no local dedup
// is needed.
//
// Called off the ref hot path — from the jobs consumer's commit-job first page, right
// after ensureRepo has (re)resolved checkpoint_repo_id from this push's settings —
// so it adds no RPC or DB round-trip to HandleRef. On a repo's very first branch push
// the pointer may not be resolvable yet (the checkpoint repo not mirrored here), so
// the trigger reflects prior pushes; acceptable for a best-effort resync.
func (f *Flow) maybeResyncCheckpointRepo(ctx context.Context, codeRepoID string) {
	storageRepoID, err := f.Store.CheckpointStorageRepoID(ctx, codeRepoID)
	if err != nil {
		slog.DebugContext(ctx, "ingest: checkpoint-repo resync: storage lookup failed; skipping",
			slog.Any("error", err), slog.String("repo_id", codeRepoID))
		return
	}
	if storageRepoID == codeRepoID {
		return // self-hosted: checkpoints live in the code repo, already webhook-covered
	}
	if err := f.Core.ResyncMirror(ctx, storageRepoID); err != nil {
		slog.InfoContext(ctx, "ingest: checkpoint-repo resync trigger failed (best-effort)",
			slog.Any("error", err), slog.String("repo_id", codeRepoID),
			slog.String("checkpoint_repo_id", storageRepoID))
	}
}

// resolveDefaultBranch resolves the repo's default branch via the Repo API refs
// listing (GET /repos/{id}/refs?prefix=HEAD&symrefs=true → HEAD's symref target,
// e.g. "refs/heads/main"). Rate-limited. "" for a repo with no resolvable HEAD.
func (f *Flow) resolveDefaultBranch(ctx context.Context, rc *repoapi.Client, base, repoID string) (string, error) {
	if err := f.waitRepoAPI(ctx); err != nil {
		return "", err
	}
	branch, err := rc.HeadBranch(ctx, base, repoID)
	if err != nil {
		return "", fmt.Errorf("ingest: resolve HEAD %s: %w", repoID, err)
	}
	return branch, nil
}

