// AuthorizeAgentRunRepositoryAccess requires push and current project ownership.
func AuthorizeAgentRunRepositoryAccess(ctx context.Context, ac *auth.AccessChecker, repos RepoOwners, z Authorization) error {
	allowed, err := ac.HasPermission(ctx, "repo", z.RepositoryID, "push")
	if err != nil {
		return fmt.Errorf("repository permission check: %w", err)
	}
	if !allowed {
		return fmt.Errorf("%w: repository push is required", agentrun.ErrNotAuthorized)
	}
	return authorizeAgentRunRepositoryOwnership(ctx, repos, z)
}

func authorizeAgentRunRepositoryOwnership(ctx context.Context, repos RepoOwners, z Authorization) error {
	if z.ProjectID == "" || z.RepositoryID == "" {
		return fmt.Errorf("%w: project and repository are required", agentrun.ErrNotAuthorized)
	}
	repo, err := repos.GetRepo(ctx, z.RepositoryID)
	switch {
	case errors.Is(err, coreapi.ErrNotFound):
		return fmt.Errorf("%w: Core does not know the repository", agentrun.ErrNotAuthorized)
	case err != nil:
		return fmt.Errorf("core repository read: %w", err)
	case repo == nil || repo.OwningProjectID != z.ProjectID:
		return fmt.Errorf("%w: the repository is not the project's", agentrun.ErrNotAuthorized)
	}
	return nil
}
