func (s Scope) VerifyAgentRunScope(ctx context.Context, projectID, repoID string) error {
	if s.Store == nil || s.Repos == nil {
		return errors.New("agentadmission: dispatch scope is not configured")
	}
	if projectID == "" {
		return fmt.Errorf("%w: the run has no captured project", runner.ErrAgentRunOutOfScope)
	}
	switch err := s.Store.AgentRunRepositoryScope(ctx, projectID, repoID); {
	case errors.Is(err, agentrun.ErrRepositoryInvalid), errors.Is(err, agentrun.ErrNotColocated):
		return fmt.Errorf("%w: %w", runner.ErrAgentRunOutOfScope, err)
	case err != nil:
		return err
	}
	repo, err := s.Repos.GetRepo(ctx, repoID)
	switch {
