// Package githubmeta consumes GitHub repository display metadata
// (stars, description, language, …) from this cell's local
// github_meta_v1 stream and persists it into the cell-local repo store.
//
// The metadata originates from GitHub webhooks (star / fork / repository
// events), which only ever ingress in US. mirror-pipeline's meta-fanout
// producer is the single component that touches the raw GitHub payload:
// it resolves the repo's placements via Core.LookupByMirror and publishes
// one Event into EACH placement's local NATS island, on the subject
// github_meta.v1.<jurisdiction>.<cluster>. This service therefore consumes
// only its OWN cell's stream and carries no GitHub-payload coupling — the
// same per-jurisdiction transport mirror-pipeline already runs for
// git-sync jobs (mirror.git.v1.<jur>.<cluster>).
//
// This is display metadata only. It NEVER gates access — repo authorization
// is decided elsewhere (auth.AccessChecker / entire-core githubperms).
package githubmeta

import "time"

// StreamName is the JetStream stream carrying github_meta_v1 on every
// cluster, provisioned declaratively in fleet (apps/nats-streams, nack
// Stream CR) — not created by this binary. There is one per cell; this
// service binds its local stream and the producer publishes into it.
const StreamName = "github_meta_v1"

// SubjectPrefix roots the placement-scoped wire subject. The full form
// encodes the repo's placement — jurisdiction + cluster — mirroring
// gitjobs' mirror.git.v1.<jur>.<cluster>.<kind>.<op>. Both tokens are
// low-cardinality and routing-relevant; the repo identity is carried in
// the payload (Event.RepoULID), not the subject.
//
// Wire form: github_meta.v1.<jurisdiction>.<cluster>
const SubjectPrefix = "github_meta.v1."

// SchemaVersionPrivateArchived is the schema_version at which the producer began
// stamping the repo's `private` and `archived` visibility bools. Events below it
// (v1) never carried those fields, so the consumer must leave the columns NULL —
// "not yet observed at v2" — rather than persist a fabricated false (see toRow).
const SchemaVersionPrivateArchived = 2

// SubjectFor returns the placement-scoped wire subject. The producer
// composes it per resolved placement; the local consumer subscribes to its
// own (jurisdiction, cluster).
func SubjectFor(jurisdiction, cluster string) string {
	return SubjectPrefix + jurisdiction + "." + cluster
}

// Event is the canonical github_meta_v1 wire contract.
//
// SOURCE OF TRUTH: mirror-pipeline's meta-fanout producer (pkg/metajobs)
// MUST marshal a byte-compatible payload. Any field added/renamed here is a
// contract change that must land on both sides; bump SchemaVersion and keep
// old fields readable across a rollout.
//
// Decode-only here — this service never publishes github_meta_v1.
type Event struct {
	// SchemaVersion lets the consumer handle a mixed-version rollout.
	SchemaVersion int `json:"schema_version,omitempty"`

	// RepoULID is the placement's repo identity — the same per-placement
	// target ULID git-sync routes on (gitjobs.Target.ULID). It is THIS
	// store's key: the consumer upserts github_repo_meta by repo_id, so no
	// github_repo_id↔full_name join is needed. Always present.
	RepoULID string `json:"repo_ulid"`

	// GitHubRepoID is GitHub's numeric repo id (stable across renames).
	// Stored for cross-referencing / debugging; not the primary key.
	GitHubRepoID int64 `json:"github_repo_id,omitempty"`

	// FullName is the GitHub "owner/repo" at observation time.
	FullName string `json:"full_name,omitempty"`

	// Display fields, lifted verbatim from the webhook repository object.
	Description     string   `json:"description,omitempty"`
	HTMLURL         string   `json:"html_url,omitempty"`
	Language        string   `json:"language,omitempty"`
	StargazersCount int      `json:"stargazers_count"`
	ForksCount      int      `json:"forks_count"`
	Topics          []string `json:"topics,omitempty"`
