func (p coreProjectNames) ProjectName(ctx context.Context, projectID string) (string, error) {
	project, err := p.core.ProjectByID(ctx, projectID)
	if err != nil {
		return "", err
	}
	return project.Name, nil
}

// accountLoginResolver renders an account's display login from Core for the
// approvals gate's reviewer snapshot (never for self-approval exclusion).
func accountLoginResolver(core *coreapi.Client) gaterecompute.AccountLoginResolver {
	return func(ctx context.Context, accountID string) (string, error) {
		identities, err := core.AccountIdentities(ctx, []string{accountID})
		if err != nil {
			return "", err
		}
		return identities[accountID].GitHubLogin(), nil
	}
}

// internalMTLSCoreClient builds the internal-mTLS coreapi client used for
// service-to-service Core reads (GetRepo, AccountByID, AuthorAccounts,
// AccountIdentities) — entire-core's internal listener over the shared authmtls
