// isn't configured so the caller can degrade with its own message.
func internalMTLSCoreClient(ctx context.Context, coreInternalURL, cert, key, ca string) (*coreapi.Client, error) {
	r, err := internalMTLSReloader(ctx, coreInternalURL, cert, key, ca)
	if err != nil || r == nil {
		return nil, err
	}
	return coreapi.New(coreInternalURL, authmtls.NewClient(r)), nil
}
