// Routing is metadata, not a Trail search. ID-bearing requests resolve exactly
// one project. Legacy named reads use a bounded namespace index and never load
// Trail candidates or bulk-check unrelated repository permissions.
// Manager-only writes do not use the repository-collaborator fallback.
func resolveTrailProjectRoute(ctx context.Context, deps *RepoActivityDeps, host, name, projectID string, allowScoped bool) (ProjectRoute, error) {
	if projectID != "" {
		parsed, err := ulid.ParseStrict(projectID)
		if err != nil {
			return ProjectRoute{}, huma.Error422UnprocessableEntity("Invalid project_id")
		}
		projectID = parsed.String()
	}
	project, err := deps.ProjectRoutes.ByReference(ctx, host, name)
	if err == nil && projectID != "" && project.ID != projectID {
		return ProjectRoute{}, coreapi.ErrNotFound
	}
	if !projectReferenceDenied(err) || !allowScoped {
		return project, err
	}
	if projectID != "" {
		entries, _, err := projectTrailDirectory(ctx, deps, []string{projectID}, string(deps.Config.Jurisdiction))
		if err != nil {
			return ProjectRoute{}, err
		}
		return trailRouteFromDirectory(ctx, entries, host, name)
	}
	forge := coreapi.RepoForgeEntire
	if host == "gh" {
		forge = coreapi.RepoForgeGitHub
	}
	ids, err := deps.Store.ProjectIDsByRepositoryNamespace(ctx, string(forge), name)
	if err != nil {
		return ProjectRoute{}, projectTrailStoreError("store: project namespace", err)
	}
	if len(ids) > 1 {
		// Ambiguous cached metadata is a lookup miss, not a Core outage.
		slog.WarnContext(ctx, "trails: ambiguous project namespace; routing denied",
			slog.String("forge", host), slog.String("owner", name), slog.Any("project_ids", ids))
		return ProjectRoute{}, coreapi.ErrNotFound
	}
	entries, _, err := projectTrailDirectory(ctx, deps, ids, string(deps.Config.Jurisdiction))
	if err != nil {
		return ProjectRoute{}, err
	}
	return trailRouteFromDirectory(ctx, entries, host, name)
}

