// loadProjectTrailAccess evaluates candidates before pagination or aggregation.
// Project discovery only finds potential Core namespace-admin authority; it
// never admits a parent. Public repo/pull is checked against local candidates,
// not enumerated. Linked Changes cannot expand the parent's admission scope.
//
// addressed is the explicitly addressed projects' metadata, never an access
// grant. It replaces discovery and the directory read on collection routes;
// nil means a personal feed over discovered candidates.
func loadProjectTrailAccess(ctx context.Context, deps *RepoActivityDeps, projectIDs []string, account *store.ProjectTrailAccount, repoID string, addressed map[string]ProjectCatalogEntry) (projectTrailAccess, error) {
	out := projectTrailAccess{Projects: map[string]ProjectCatalogEntry{}, ReadableScopeProjects: map[string]struct{}{}}
	if account == nil && len(projectIDs) == 0 {
		return out, nil
	}
	ac, err := perRequestAccessChecker(ctx, deps.Reader)
	if err != nil {
		return out, huma.Error500InternalServerError("auth: access checker", err)
	}
	candidates, err := deps.Store.ProjectTrailAccessCandidates(ctx, projectIDs, account, repoID)
	if err != nil {
		return out, projectTrailStoreError("store: Trail access candidates", err)
	}
	pids, rids := map[string]struct{}{}, map[string]struct{}{}
	for _, candidate := range candidates {
		pids[candidate.ProjectID] = struct{}{}
		if candidate.RepositoryID != "" {
			rids[candidate.RepositoryID] = struct{}{}
		}
	}
	// Include an explicitly addressed empty collection, so native project
	// viewers/managers can still read it before its first Trail is created.
	if account == nil {
		for _, projectID := range projectIDs {
			pids[projectID] = struct{}{}
		}
	}
