package mirrorjobs

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os"

	"connectrpc.com/connect"
	"github.com/oklog/ulid/v2"
	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	repolookupv1 "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1"
	"github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1/repolookupv1connect"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// ErrMirrorNotFound is returned by MirrorByID when entire-core has no mirror
// for the given ULID (or the placement is suspended). Callers treat it as a
// benign skip, not a transient error to retry.
var ErrMirrorNotFound = errors.New("mirrorjobs: mirror not found")

// RepoLookupClient is the subset of the generated Connect client needed by
// CoreLookupResolver.
type RepoLookupClient interface {
	LookupByMirror(context.Context, *connect.Request[repolookupv1.LookupByMirrorRequest]) (*connect.Response[repolookupv1.LookupByMirrorResponse], error)
	LookupMirrorByID(context.Context, *connect.Request[repolookupv1.LookupMirrorByIDRequest]) (*connect.Response[repolookupv1.LookupMirrorByIDResponse], error)
}

// NewRepoLookupClient builds a Connect-RPC client over the internal mTLS
// listener exposed by entire-core.
func NewRepoLookupClient(certPath, keyPath, caPath, baseURL string) (repolookupv1connect.RepoLookupClient, error) {
	if certPath == "" || keyPath == "" || caPath == "" {
		return nil, errors.New("ENTIRE_INTERNAL_TLS_{CERT,KEY,CA}_FILE all required for repo lookup")
	}
	if baseURL == "" {
		return nil, errors.New("ENTIRE_CORE_INTERNAL_URL is required for repo lookup")
	}

	if _, err := tls.LoadX509KeyPair(certPath, keyPath); err != nil {
		return nil, fmt.Errorf("load tls keypair: %w", err)
	}
	caBytes, err := os.ReadFile(caPath) //nolint:gosec // operator-supplied env var, validated non-empty above
	if err != nil {
		return nil, fmt.Errorf("read internal CA: %w", err)
	}
	caPool := x509.NewCertPool()
	if !caPool.AppendCertsFromPEM(caBytes) {
		return nil, errors.New("internal CA PEM: no certs parsed")
	}

	dt, ok := http.DefaultTransport.(*http.Transport)
	if !ok {
		return nil, errors.New("http.DefaultTransport is not *http.Transport")
	}
	tr := dt.Clone()
	tr.TLSClientConfig = &tls.Config{
		GetClientCertificate: func(_ *tls.CertificateRequestInfo) (*tls.Certificate, error) {
			return loadClientCertificate(certPath, keyPath)
		},
		RootCAs:    caPool,
		MinVersion: tls.VersionTLS13,
	}
	tr.ForceAttemptHTTP2 = true

	httpClient := &http.Client{Transport: otelhttp.NewTransport(tr)}
	return repolookupv1connect.NewRepoLookupClient(httpClient, baseURL), nil
}

func loadClientCertificate(certFile, keyFile string) (*tls.Certificate, error) {
	cert, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		return nil, err
	}
	return &cert, nil
}

// CoreLookupResolver resolves GitHub mirrors through entire-core RepoLookup.
type CoreLookupResolver struct {
	client RepoLookupClient
	skips  metric.Int64Counter
}

// NewCoreLookupResolver returns a RepoLookup-backed route resolver.
func NewCoreLookupResolver(client RepoLookupClient) *CoreLookupResolver {
	// placement_skipped counts placements dropped from a lookup because a
	// required routing field was blank, tagged by reason — an alertable signal
	// that entire-core returned unroutable placement data (otherwise only a WARN
	// log). Built here, after otel setup in main, so it binds to the real meter
	// provider rather than the startup no-op.
	skips, _ := otel.Meter("github.com/entirehq/mirror-pipeline/internal/mirrorjobs").
		Int64Counter("mirrorjobs.placement_skipped",
			metric.WithDescription("Placements dropped from a repo lookup because a required routing field (cluster_slug or repo_id) was blank or malformed, by reason."))
	return &CoreLookupResolver{client: client, skips: skips}
}

// recordSkip increments the placement_skipped counter with a reason label.
// Safe when the counter failed to register (nil).
func (r *CoreLookupResolver) recordSkip(ctx context.Context, reason string) {
	if r.skips != nil {
		r.skips.Add(ctx, 1, metric.WithAttributes(attribute.String("reason", reason)))
	}
}

// RoutesForSource resolves a source event into target mirror routes.
func (r *CoreLookupResolver) RoutesForSource(ctx context.Context, event SourceEvent) ([]MirrorRoute, error) {
	if event.Kind != gitjobs.SourceKindGithub {
		return nil, fmt.Errorf("unsupported source kind %q", event.Kind)
	}

	resp, err := r.client.LookupByMirror(ctx, connect.NewRequest(&repolookupv1.LookupByMirrorRequest{
		Provider:     string(gitjobs.SourceKindGithub),
		Owner:        event.Owner,
		Repo:         event.Repo,
		GithubRepoId: event.GitHubRepoID,
	}))
	if err != nil {
		return nil, fmt.Errorf("repo lookup: %w", err)
	}

	placements := resp.Msg.GetPlacements()
	if len(placements) == 0 {
		// entire-core has no mirror registered for this source. Surface this
		// as an Info log so callers (e.g. the fanout consumer) don't have to
		// each re-discover the case from an empty routes slice.
		slog.InfoContext(ctx, "repo lookup returned no placements; source has no mirror",
			slog.String("source_kind", string(event.Kind)),
			slog.String("source_owner", event.Owner),
			slog.String("source_repo", event.Repo))
	}
	// Placements are unique per cluster for a source: github_repos has a
	// UNIQUE(lower(owner_login), lower(repo_name)) index (one github_repo_id per
	// owner/repo) and mirror_repos has UNIQUE(github_repo_id, cluster_slug) (at
	// most one mirror per cluster). Fan-out memo correctness relies on this — the
	// engine keys its per-delivery dedup memo on Region()==cluster_slug (see
	// fanoutengine.Route), so two routes must never share a cluster in one
	// delivery. If the mirror model ever allows multiple placements per cluster,
	// give routes a finer memo key.
	routes := make([]MirrorRoute, 0, len(placements))
	for _, p := range placements {
		if p.GetClusterSlug() == "" {
			slog.WarnContext(ctx, "repo lookup returned empty cluster slug; skipping placement",
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("repo_id", p.GetRepoId()),
				slog.String("source_owner", event.Owner),
				slog.String("source_repo", event.Repo))
			r.recordSkip(ctx, "empty_cluster_slug")
			continue
		}
		if p.GetRepoId() == "" {
			// A blank mirror repo_id is a server-side data problem for THIS
			// placement only. Skip it (like the empty cluster slug above) so one
			// bad placement can't fail the whole delivery — a downstream that
			// validates the target ULID (e.g. trails-fanout) would otherwise
			// reject the batch as malformed input and drop every placement.
			slog.WarnContext(ctx, "repo lookup returned empty repo_id; skipping placement",
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("source_owner", event.Owner),
				slog.String("source_repo", event.Repo))
			r.recordSkip(ctx, "empty_repo_id")
			continue
		}
		if _, err := ulid.ParseStrict(p.GetRepoId()); err != nil {
			// Same per-placement data problem as a blank repo_id, just non-empty:
			// a malformed ULID would fail trails-fanout's per-placement event
			// validation and Term-drop the whole delivery for every cell.
			slog.WarnContext(ctx, "repo lookup returned malformed repo_id; skipping placement",
				slog.String("repo_id", p.GetRepoId()),
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("source_owner", event.Owner),
				slog.String("source_repo", event.Repo))
			r.recordSkip(ctx, "invalid_repo_id")
			continue
		}
		routes = append(routes, MirrorRoute{
			Placement: gitjobs.Placement{
				Jurisdiction: p.GetJurisdiction(),
				ClusterID:    p.GetClusterSlug(),
			},
			SourceKind: event.Kind,
			Source: gitjobs.Source{
				Owner:   event.Owner,
				Repo:    event.Repo,
				AuthRef: event.AuthRef,
			},
			Target: gitjobs.Target{ULID: p.GetRepoId()},
		})
	}
	return routes, nil
}

// MirrorUpstream is the upstream identity of a mirror, resolved from its repo
// ULID via RepoLookup.LookupMirrorByID — the inverse of RoutesForSource.
type MirrorUpstream struct {
	Provider string
	Owner    string
	Repo     string
}

// MirrorByID resolves a mirror's repo ULID to its upstream coordinates. It
// backs meta-fanout's mirror.created hook: the resource_lifecycle_v1 event
// carries only the mirror ULID, so the (owner, repo) needed to enqueue a
// github_meta backfill must be re-queried from entire-core.
//
// ErrMirrorNotFound is returned for an unknown (or suspended) mirror ULID so
// the caller can treat it as a benign skip rather than a transient failure to
// retry.
func (r *CoreLookupResolver) MirrorByID(ctx context.Context, mirrorID string) (MirrorUpstream, error) {
	if mirrorID == "" {
		return MirrorUpstream{}, errors.New("mirror id is required")
	}

	resp, err := r.client.LookupMirrorByID(ctx, connect.NewRequest(&repolookupv1.LookupMirrorByIDRequest{
		RepoId: mirrorID,
	}))
	if err != nil {
		if connect.CodeOf(err) == connect.CodeNotFound {
			return MirrorUpstream{}, fmt.Errorf("%w: %s", ErrMirrorNotFound, mirrorID)
		}
		return MirrorUpstream{}, fmt.Errorf("lookup mirror by id %s: %w", mirrorID, err)
	}

	return MirrorUpstream{
		Provider: resp.Msg.GetProvider(),
		Owner:    resp.Msg.GetOwner(),
		Repo:     resp.Msg.GetRepo(),
	}, nil
}

package mirrorjobs

import (
	"context"

	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// SourceEvent is the source repository event shape consumed by route resolvers.
type SourceEvent struct {
	Kind    gitjobs.SourceKind
	Owner   string
	Repo    string
	AuthRef string
	// GitHubRepoID is the webhook's immutable repository.id. When non-zero,
	// entire-core only returns placements of that upstream, so a stale
	// owner/repo held by another GitHub repo can't route onto an old mirror
	// (ENT-2822). Zero (backfills, which resolve from our own rows) keeps
	// name-only routing.
	GitHubRepoID int64
}

// MirrorRoute is the resolved target placement for a source repository.
type MirrorRoute struct {
	Placement  gitjobs.Placement
	SourceKind gitjobs.SourceKind
	Source     gitjobs.Source
	Target     gitjobs.Target
}

// RouteResolver resolves source events into mirror routes.
type RouteResolver interface {
	RoutesForSource(context.Context, SourceEvent) ([]MirrorRoute, error)
}

// MirrorPublisher publishes resolved mirror routes as Git sync jobs.
type MirrorPublisher interface {
	PublishGitSyncJob(context.Context, MirrorRoute) error
}

package mirrorjobs

import (
	"context"
	"strconv"
	"sync"
	"time"

	"connectrpc.com/connect"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
	"golang.org/x/sync/singleflight"

	repolookupv1 "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1"
)

// defaultLookupTimeout caps each upstream RepoLookup RPC. It applies inside
// the singleflight slot on a detached context so one caller cancelling can't
// kill an in-flight lookup that other callers are coalesced onto.
const defaultLookupTimeout = 10 * time.Second

// defaultSweepInterval is how often Run scans the entry map for expired
// entries. Lookups already evict on read; the sweeper exists only to drop
// one-shot keys that never get re-read so memory stays bounded over the
// process lifetime.
const defaultSweepInterval = 5 * time.Minute

// CachingRepoLookupClient wraps a RepoLookupClient with a read-through in-memory
// cache keyed on (provider, owner, repo, github_repo_id).
//
// Positive responses live for PosTTL; empty ("no placements") responses live
// for NegTTL, kept short on purpose — a stale negative entry silently delays
// mirror activation when a user wires a new repo in entire-core. A stale
// positive entry can also route pushes to a previously-placed cluster for up
// to PosTTL after a re-placement, but mirror moves are rare and worst case
// we route to the prior cluster set briefly; an outage of the wrong cluster
// is far costlier than a few seconds of stale routing.
//
// Concurrent misses on the same key are coalesced via singleflight so a push
// burst on a cold key fans to a single upstream RPC. Errors are never cached.
//
// The upstream RPC runs on a detached context (the leader's caller cancelling
// would otherwise propagate to every coalesced waiter and silently drop a
// burst of webhook routes). Each caller selects on its own ctx so an
// individual cancellation only affects that caller.
//
// On error the leader retries once inside the same singleflight slot before
// broadcasting, so all coalesced waiters share the retry. Caps upstream
// fanout at 2 RPCs per burst regardless of waiter count — a retry done in
// the outer code would race against late waiters spawning new singleflight
// slots once the first one drains.
type CachingRepoLookupClient struct {
	inner         RepoLookupClient
	posTTL        time.Duration
	negTTL        time.Duration
	lookupTimeout time.Duration
	sweepInterval time.Duration
	now           func() time.Time

	entries sync.Map // map[string]*cacheEntry
	group   singleflight.Group
}

type cacheEntry struct {
	placements []*repolookupv1.Placement
	expiresAt  time.Time
}

// lookupOutcome is the value singleflight broadcasts to all coalesced
// waiters: the placements plus whether the leader had to retry. Carrying
// retried through the singleflight result is what makes all waiters see the
// same telemetry (a shared call shares its outcome).
type lookupOutcome struct {
	placements []*repolookupv1.Placement
	retried    bool
}

// NewCachingRepoLookupClient builds a cache around inner. A zero posTTL or
// negTTL disables caching for that class of response (the call always falls
// through to inner).
func NewCachingRepoLookupClient(inner RepoLookupClient, posTTL, negTTL time.Duration) *CachingRepoLookupClient {
	return &CachingRepoLookupClient{
		inner:         inner,
		posTTL:        posTTL,
		negTTL:        negTTL,
		lookupTimeout: defaultLookupTimeout,
		sweepInterval: defaultSweepInterval,
		now:           time.Now,
	}
}

func (c *CachingRepoLookupClient) LookupByMirror(ctx context.Context, req *connect.Request[repolookupv1.LookupByMirrorRequest]) (*connect.Response[repolookupv1.LookupByMirrorResponse], error) {
	span := trace.SpanFromContext(ctx)
	key := cacheKey(req.Msg)
	if entry, ok := c.lookup(key); ok {
		span.SetAttributes(
			attribute.String("mirrorjobs.lookup.cache", "hit"),
			attribute.Int("mirrorjobs.lookup.placements", len(entry.placements)),
		)
		return connect.NewResponse(&repolookupv1.LookupByMirrorResponse{Placements: entry.placements}), nil
	}

	// Retry once inside the singleflight slot so every coalesced waiter
	// shares the retry. Doing it in the outer code instead would race: late
	// waiters could spawn new singleflight slots once the first one drained,
	// turning the cap into N+1 RPCs on a fast retry. We can't read Shared
	// from inside the closure, so lone callers retry too — the cost is
	// bounded (2x on lone errors) and worth it for a webhook ingest where
	// each unretried error is a dropped push.
	attempt := func() (*connect.Response[repolookupv1.LookupByMirrorResponse], error) {
		// WithoutCancel detaches cancellation/deadline so leader cancellation
		// can't propagate to coalesced waiters, while preserving ctx values
		// (the OTel span, baggage, logger) so the upstream HTTP span still
		// chains under the current trace.
		aCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), c.lookupTimeout)
		defer cancel()
		return c.inner.LookupByMirror(aCtx, req)
	}

	doLookup := func() (any, error) {
		resp, err := attempt()
		retried := false
		if err != nil {
			retried = true
			resp, err = attempt()
			if err != nil {
				return nil, err
			}
		}
		placements := resp.Msg.GetPlacements()
		c.store(key, placements)
		return &lookupOutcome{placements: placements, retried: retried}, nil
	}

	res, err := c.awaitLookup(ctx, key, doLookup)
	if err != nil {
		return nil, err
	}
	if res.Err != nil {
		return nil, res.Err
	}

	out, _ := res.Val.(*lookupOutcome)
	span.SetAttributes(
		attribute.String("mirrorjobs.lookup.cache", "miss"),
		attribute.Bool("mirrorjobs.lookup.cache.coalesced", res.Shared),
		attribute.Bool("mirrorjobs.lookup.cache.retried", out.retried),
		attribute.Int("mirrorjobs.lookup.placements", len(out.placements)),
	)
	return connect.NewResponse(&repolookupv1.LookupByMirrorResponse{Placements: out.placements}), nil
}

// LookupMirrorByID passes through to the inner client uncached. The by-ULID
// lookup is one-shot per mirror creation (a low-volume control-plane event),
// not a hot webhook path, so the read-through cache that fronts LookupByMirror
// buys nothing here — and a mirror ULID maps to immutable upstream coords, so
// there is no staleness window worth managing either.
func (c *CachingRepoLookupClient) LookupMirrorByID(ctx context.Context, req *connect.Request[repolookupv1.LookupMirrorByIDRequest]) (*connect.Response[repolookupv1.LookupMirrorByIDResponse], error) {
	return c.inner.LookupMirrorByID(ctx, req)
}

// awaitLookup runs the singleflight call and blocks until either the result
// arrives or the caller's ctx is canceled. On ctx cancellation the
// singleflight slot keeps running and will still populate the cache for the
// next caller.
func (c *CachingRepoLookupClient) awaitLookup(ctx context.Context, key string, fn func() (any, error)) (singleflight.Result, error) {
	select {
	case res := <-c.group.DoChan(key, fn):
		return res, nil
	case <-ctx.Done():
		return singleflight.Result{}, ctx.Err()
	}
}

// Run periodically evicts expired entries until ctx is canceled. The cache
// works without it (lookups evict on read), but a long-running process that
// sees a long tail of one-shot keys would otherwise grow without bound.
func (c *CachingRepoLookupClient) Run(ctx context.Context) {
	ticker := time.NewTicker(c.sweepInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			c.sweep()
		}
	}
}

func (c *CachingRepoLookupClient) sweep() {
	now := c.now()
	c.entries.Range(func(k, v any) bool {
		entry, ok := v.(*cacheEntry)
		if !ok {
			c.entries.Delete(k)
			return true
		}
		if !now.Before(entry.expiresAt) {
			// CompareAndDelete so a concurrent writer that re-stored a
			// fresh entry under the same key between our Range read and
			// the delete isn't clobbered.
			c.entries.CompareAndDelete(k, v)
		}
		return true
	})
}

func (c *CachingRepoLookupClient) store(key string, placements []*repolookupv1.Placement) {
	ttl := c.posTTL
	if len(placements) == 0 {
		ttl = c.negTTL
	}
	if ttl > 0 {
		c.entries.Store(key, &cacheEntry{
			placements: placements,
			expiresAt:  c.now().Add(ttl),
		})
	}
}

func (c *CachingRepoLookupClient) lookup(key string) (*cacheEntry, bool) {
	v, ok := c.entries.Load(key)
	if !ok {
		return nil, false
	}
	entry, ok := v.(*cacheEntry)
	if !ok {
		return nil, false
	}
	if !c.now().Before(entry.expiresAt) {
		c.entries.Delete(key)
		return nil, false
	}
	return entry, true
}

// cacheKey includes github_repo_id because entire-core filters placements by
// it: two upstreams can hold the same owner/repo over time, and one's cached
// placements must never answer the other's lookup (ENT-2822).
func cacheKey(req *repolookupv1.LookupByMirrorRequest) string {
	return req.GetProvider() + "\x00" + req.GetOwner() + "\x00" + req.GetRepo() + "\x00" + strconv.FormatInt(req.GetGithubRepoId(), 10)
}

package mirrorjobs

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"slices"

	"connectrpc.com/connect"
	"github.com/oklog/ulid/v2"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	repolookupv1 "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// ErrNativeRepoNotFound is returned by NativeMirrorRoutes when entire-core has
// no repo for the given ULID — normal for a repo deleted between a ref event
// being published and consumed. Callers treat it as a benign skip, not a
// transient error to retry.
var ErrNativeRepoNotFound = errors.New("mirrorjobs: native repo not found")

// NativeMirrorLookupClient is the subset of the generated Connect client
// needed by NativeMirrorResolver. Kept separate from RepoLookupClient so the
// GitHub-webhook resolver and its fakes don't grow a method they never call.
type NativeMirrorLookupClient interface {
	LookupNativeMirrorsByRepoID(context.Context, *connect.Request[repolookupv1.LookupNativeMirrorsByRepoIDRequest]) (*connect.Response[repolookupv1.LookupNativeMirrorsByRepoIDResponse], error)
}

// NativeMirrorResolution is one resolved ref event: the group's git-data home
// cluster (the loop-prevention key — the caller drops the event unless its
// local cluster is the home) and one sync route per serving mirror.
type NativeMirrorResolution struct {
	HomeClusterID string
	Routes        []MirrorRoute
	// NamespaceRoutes replicate only refs/heads/entire/native/* (COR-1566)
	// onto the group's namespace mirrors — GitHub placements that own the
	// rest of their ref state. Core populates namespace mirrors only for
	// GitHub groups, which have no native mirrors, so this is never
	// non-empty at the same time as Routes; the caller filters the event's
	// ref name against the namespace before publishing these.
	NamespaceRoutes []MirrorRoute
}

// NativeMirrorResolver resolves repo ULIDs from repo_refs_v1 events into
// native-mirror sync routes through entire-core
// RepoLookup.LookupNativeMirrorsByRepoID.
type NativeMirrorResolver struct {
	client NativeMirrorLookupClient
	skips  metric.Int64Counter
}

// NewNativeMirrorResolver returns a lookup-backed native-mirror route
// resolver. The placement_skipped counter is shared (by name) with
// CoreLookupResolver — same signal, same dashboards: entire-core returned
// unroutable placement data.
func NewNativeMirrorResolver(client NativeMirrorLookupClient) *NativeMirrorResolver {
	skips, _ := otel.Meter("github.com/entirehq/mirror-pipeline/internal/mirrorjobs").
		Int64Counter("mirrorjobs.placement_skipped",
			metric.WithDescription("Placements dropped from a repo lookup because a required routing field (cluster_slug or repo_id) was blank or malformed, by reason."))
	return &NativeMirrorResolver{client: client, skips: skips}
}

func (r *NativeMirrorResolver) recordSkip(ctx context.Context, reason string) {
	if r.skips != nil {
		r.skips.Add(ctx, 1, metric.WithAttributes(attribute.String("reason", reason)))
	}
}

// validateNativeMirrorLookupResponse checks the two response invariants a
// delivery cannot proceed without: a home placement with a cluster slug (the
// loop-prevention key) and, when any routable mirror exists, a source URL
// (the sync job's fetch source). Shared by NativeMirrorRoutes (which fails
// the delivery on a violation → Nak → redelivery until Core is fixed) and
// the caching client (which must NOT store a violating response — a cached
// one would keep failing redeliveries for a full TTL after the Core-side
// fix). Per-placement problems are deliberately NOT here: a single malformed
// placement only skips that route, so it must not block caching either.
func validateNativeMirrorLookupResponse(resp *repolookupv1.LookupNativeMirrorsByRepoIDResponse) error {
	if resp.GetHome().GetClusterSlug() == "" {
		return errors.New("home placement has no cluster slug")
	}
	if resp.GetSourceUrl() == "" &&
		(slices.ContainsFunc(resp.GetNativeMirrors(), routableNativeMirror) ||
			slices.ContainsFunc(resp.GetNamespaceMirrors(), routableNativeMirror)) {
		return fmt.Errorf("home cluster %s has no internal source URL registered", resp.GetHome().GetClusterSlug())
	}
	return nil
}

// routableNativeMirror reports whether a placement would survive
// NativeMirrorRoutes's per-placement validation and become a route.
func routableNativeMirror(p *repolookupv1.Placement) bool {
	if p.GetClusterSlug() == "" || p.GetRepoId() == "" {
		return false
	}
	_, err := ulid.ParseStrict(p.GetRepoId())
	return err == nil
}

// NativeMirrorRoutes resolves the repo id carried by a ref event (any
// placement of the repo — the home primary, or a mirror echoing a worker
// push) to its group's home cluster, one sync route per serving native
// mirror, and one namespace route per namespace mirror. Both route sets
// empty is normal — a repo with no mirrors, i.e. every repo today.
//
// Mirrors of either kind are unique per cluster (UNIQUE(repo_group_id,
// cluster_slug) on native_mirrors; one mirror_repos row per cluster in a
// GitHub group), so two routes never share a Region() in one delivery — the
// fan-out engine's route-memo correctness bound.
//
// Errors: ErrNativeRepoNotFound for an unknown repo id (benign skip — the
// repo was deleted); a plain error otherwise (transient — the caller Naks so
// JetStream redelivers). A response whose home placement is missing its
// cluster slug, or whose source_url is empty while serving mirrors exist, is
// also a plain error: both are server-side data/config problems (an
// unregistered internal URL for the home cluster) that an operator fix
// heals, and dropping the event instead would silently strand the mirrors
// until the next push.
func (r *NativeMirrorResolver) NativeMirrorRoutes(ctx context.Context, repoID string) (NativeMirrorResolution, error) {
	if repoID == "" {
		return NativeMirrorResolution{}, errors.New("repo id is required")
	}

	resp, err := r.client.LookupNativeMirrorsByRepoID(ctx, connect.NewRequest(&repolookupv1.LookupNativeMirrorsByRepoIDRequest{
		RepoId: repoID,
	}))
	if err != nil {
		if connect.CodeOf(err) == connect.CodeNotFound {
			return NativeMirrorResolution{}, fmt.Errorf("%w: %s", ErrNativeRepoNotFound, repoID)
		}
		return NativeMirrorResolution{}, fmt.Errorf("native mirror lookup %s: %w", repoID, err)
	}

	if err := validateNativeMirrorLookupResponse(resp.Msg); err != nil {
		return NativeMirrorResolution{}, fmt.Errorf("native mirror lookup %s: %w", repoID, err)
	}
	return NativeMirrorResolution{
		HomeClusterID:   resp.Msg.GetHome().GetClusterSlug(),
		Routes:          r.routesFor(ctx, repoID, gitjobs.SourceKindEntireDB, resp.Msg.GetSourceUrl(), resp.Msg.GetNativeMirrors()),
		NamespaceRoutes: r.routesFor(ctx, repoID, gitjobs.SourceKindEntireDBNamespace, resp.Msg.GetSourceUrl(), resp.Msg.GetNamespaceMirrors()),
	}, nil
}

// routesFor turns one placement list into sync routes of the given kind,
// skipping (and counting) placements Core returned without the routing
// fields a job needs.
func (r *NativeMirrorResolver) routesFor(ctx context.Context, repoID string, kind gitjobs.SourceKind, sourceURL string, mirrors []*repolookupv1.Placement) []MirrorRoute {
	routes := make([]MirrorRoute, 0, len(mirrors))
	for _, p := range mirrors {
		if p.GetClusterSlug() == "" {
			slog.WarnContext(ctx, "native mirror lookup returned empty cluster slug; skipping placement",
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("mirror_repo_id", p.GetRepoId()),
				slog.String("repo_id", repoID))
			r.recordSkip(ctx, "empty_cluster_slug")
			continue
		}
		if p.GetRepoId() == "" {
			slog.WarnContext(ctx, "native mirror lookup returned empty repo_id; skipping placement",
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("repo_id", repoID))
			r.recordSkip(ctx, "empty_repo_id")
			continue
		}
		if _, err := ulid.ParseStrict(p.GetRepoId()); err != nil {
			slog.WarnContext(ctx, "native mirror lookup returned malformed repo_id; skipping placement",
				slog.String("mirror_repo_id", p.GetRepoId()),
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("repo_id", repoID))
			r.recordSkip(ctx, "invalid_repo_id")
			continue
		}
		routes = append(routes, MirrorRoute{
			Placement: gitjobs.Placement{
				Jurisdiction: p.GetJurisdiction(),
				ClusterID:    p.GetClusterSlug(),
			},
			SourceKind: kind,
			Source:     gitjobs.Source{URL: sourceURL},
			Target:     gitjobs.Target{ULID: p.GetRepoId()},
		})
	}
	return routes
}

