package mirrorjobs

import (
	"context"
	"sync"
	"time"

	"connectrpc.com/connect"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
	"golang.org/x/sync/singleflight"

	repolookupv1 "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1"
)

// CachingNativeMirrorLookupClient wraps a NativeMirrorLookupClient with a
// read-through in-memory cache keyed on repo id — the native-mirror twin of
// CachingRepoLookupClient, with the same coalescing/retry/detached-context
// semantics (see that type's doc for the full rationale).
//
// Responses with at least one serving mirror — native or namespace — live
// for PosTTL; "no mirrors at all" responses — the overwhelmingly common
// case, every repo without replicas resolves to one on every push — live
// for NegTTL, kept short on purpose so a freshly registered mirror starts
// replicating within seconds rather than a full PosTTL. Errors (including
// CodeNotFound for a deleted repo) are never cached.
type CachingNativeMirrorLookupClient struct {
	inner         NativeMirrorLookupClient
	posTTL        time.Duration
	negTTL        time.Duration
	lookupTimeout time.Duration
	sweepInterval time.Duration
	now           func() time.Time

	entries sync.Map // map[string]*nativeCacheEntry
	group   singleflight.Group
}

type nativeCacheEntry struct {
	resp      *repolookupv1.LookupNativeMirrorsByRepoIDResponse
	expiresAt time.Time
}

// nativeLookupOutcome is the value singleflight broadcasts to all coalesced
// waiters (see lookupOutcome for why retried rides along).
type nativeLookupOutcome struct {
	resp    *repolookupv1.LookupNativeMirrorsByRepoIDResponse
	retried bool
}

// NewCachingNativeMirrorLookupClient builds a cache around inner. A zero
// posTTL or negTTL disables caching for that class of response.
func NewCachingNativeMirrorLookupClient(inner NativeMirrorLookupClient, posTTL, negTTL time.Duration) *CachingNativeMirrorLookupClient {
	return &CachingNativeMirrorLookupClient{
		inner:         inner,
		posTTL:        posTTL,
		negTTL:        negTTL,
		lookupTimeout: defaultLookupTimeout,
		sweepInterval: defaultSweepInterval,
		now:           time.Now,
	}
}

func (c *CachingNativeMirrorLookupClient) LookupNativeMirrorsByRepoID(ctx context.Context, req *connect.Request[repolookupv1.LookupNativeMirrorsByRepoIDRequest]) (*connect.Response[repolookupv1.LookupNativeMirrorsByRepoIDResponse], error) {
	span := trace.SpanFromContext(ctx)
	key := req.Msg.GetRepoId()
	if entry, ok := c.lookup(key); ok {
		span.SetAttributes(
			attribute.String("mirrorjobs.native_lookup.cache", "hit"),
			attribute.Int("mirrorjobs.native_lookup.native_mirrors", len(entry.resp.GetNativeMirrors())),
		)
		return connect.NewResponse(entry.resp), nil
	}

	// Retry once inside the singleflight slot so every coalesced waiter
	// shares the retry — same shape and rationale as
	// CachingRepoLookupClient.LookupByMirror.
	attempt := func() (*connect.Response[repolookupv1.LookupNativeMirrorsByRepoIDResponse], error) {
		aCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), c.lookupTimeout)
		defer cancel()
		return c.inner.LookupNativeMirrorsByRepoID(aCtx, req)
	}

	doLookup := func() (any, error) {
		resp, err := attempt()
		retried := false
		if err != nil {
			// CodeNotFound is a definitive answer (deleted repo), not a
			// transient failure — retrying it just doubles the RPC.
			if connect.CodeOf(err) == connect.CodeNotFound {
				return nil, err
			}
			retried = true
			resp, err = attempt()
			if err != nil {
				return nil, err
			}
		}
		c.store(key, resp.Msg)
		return &nativeLookupOutcome{resp: resp.Msg, retried: retried}, nil
	}

	res, err := c.awaitLookup(ctx, key, doLookup)
	if err != nil {
		return nil, err
	}
	if res.Err != nil {
		return nil, res.Err
	}

	out, _ := res.Val.(*nativeLookupOutcome)
	span.SetAttributes(
		attribute.String("mirrorjobs.native_lookup.cache", "miss"),
		attribute.Bool("mirrorjobs.native_lookup.cache.coalesced", res.Shared),
		attribute.Bool("mirrorjobs.native_lookup.cache.retried", out.retried),
		attribute.Int("mirrorjobs.native_lookup.native_mirrors", len(out.resp.GetNativeMirrors())),
	)
	return connect.NewResponse(out.resp), nil
}

// awaitLookup runs the singleflight call and blocks until either the result
// arrives or the caller's ctx is canceled; the slot keeps running and still
// populates the cache for the next caller.
func (c *CachingNativeMirrorLookupClient) awaitLookup(ctx context.Context, key string, fn func() (any, error)) (singleflight.Result, error) {
	select {
	case res := <-c.group.DoChan(key, fn):
		return res, nil
	case <-ctx.Done():
		return singleflight.Result{}, ctx.Err()
	}
}

// Run periodically evicts expired entries until ctx is canceled — same
// bounded-memory rationale as CachingRepoLookupClient.Run.
func (c *CachingNativeMirrorLookupClient) Run(ctx context.Context) {
	ticker := time.NewTicker(c.sweepInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			c.sweep()
		}
	}
}

func (c *CachingNativeMirrorLookupClient) sweep() {
	now := c.now()
	c.entries.Range(func(k, v any) bool {
		entry, ok := v.(*nativeCacheEntry)
		if !ok {
			c.entries.Delete(k)
			return true
		}
		if !now.Before(entry.expiresAt) {
			c.entries.CompareAndDelete(k, v)
		}
		return true
	})
}

func (c *CachingNativeMirrorLookupClient) store(key string, resp *repolookupv1.LookupNativeMirrorsByRepoIDResponse) {
	// Never cache a response the resolver will reject (missing home cluster
	// slug; serving mirrors without a source URL). The resolver's rejection
	// Naks the delivery so JetStream redelivers — but a cached bad response
	// would keep failing those redeliveries for a full TTL after the
	// Core-side fix lands. An uncached one costs an extra RPC per
	// redelivery and heals immediately.
	if validateNativeMirrorLookupResponse(resp) != nil {
		return
	}
	ttl := c.posTTL
	if len(resp.GetNativeMirrors()) == 0 && len(resp.GetNamespaceMirrors()) == 0 {
		ttl = c.negTTL
	}
	if ttl > 0 {
		c.entries.Store(key, &nativeCacheEntry{
			resp:      resp,
			expiresAt: c.now().Add(ttl),
		})
	}
}

func (c *CachingNativeMirrorLookupClient) lookup(key string) (*nativeCacheEntry, bool) {
	v, ok := c.entries.Load(key)
	if !ok {
		return nil, false
	}
	entry, ok := v.(*nativeCacheEntry)
	if !ok {
		return nil, false
	}
	if !c.now().Before(entry.expiresAt) {
		c.entries.Delete(key)
		return nil, false
	}
	return entry, true
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	_ "go.uber.org/automaxprocs"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
	"github.com/entirehq/mirror-pipeline/internal/natsregions"
	"github.com/entirehq/mirror-pipeline/internal/slogutil"
	"github.com/entirehq/mirror-pipeline/internal/svchttp"
	"github.com/entirehq/mirror-pipeline/internal/version"
	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/otelsetup"
	"github.com/entirehq/mirror-pipeline/pkg/refevents"
	"github.com/entirehq/mirror-pipeline/pkg/webhookdlq"
	"github.com/entirehq/mirror-pipeline/pkg/webhookevents"
	"github.com/entireio/go-nuts"
)

// consumerDrainTimeout bounds how long shutdown waits for the consume loop to
// finish its in-flight message before NATS is closed. It must cover one Fetch
// MaxWait plus a terminal delivery's bounded DLQ capture (publishAckWait), so
// an in-flight dead-letter can land on a still-open connection rather than
// being abandoned at exit.
const consumerDrainTimeout = 12 * time.Second // also the nuts.Drain backstop: must exceed DrainTimeout (5s) + publish-flush (5s)

func main() {
	slogutil.Install(slogutil.LevelFromEnv())

	if err := run(); err != nil {
		slog.Error("fanout failed", slog.Any("error", err))
		os.Exit(1)
	}
}

func run() (retErr error) {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	otelShutdown, err := otelsetup.Setup(ctx, otelsetup.Config{
		ServiceName:    "fanout",
		ServiceVersion: version.Version,
	})
	if err != nil {
		return fmt.Errorf("setup opentelemetry: %w", err)
	}
	defer otelsetup.Shutdown(otelShutdown)

	natsURL := os.Getenv("ENTIRE_NATS_URL")
	if natsURL == "" {
		return errors.New("ENTIRE_NATS_URL is required")
	}

	// Consumer selection (COR-1021). The webhook consumer defaults ON — the
	// binary must keep fanning US webhooks when it ships ahead of the fleet
	// flag — and is switched off on non-US clusters, which have no
	// webhooks_github_v1 stream to consume (an enabled consumer there would
	// loop on "stream not found" and hold /readyz false forever). The
	// native-mirror consumer defaults OFF so this binary ships inert; fleet
	// enables it per cluster together with the routing map it needs.
	webhookEnabled, err := parseBoolEnvFrom(os.Getenv, "FANOUT_WEBHOOK_CONSUMER_ENABLED", true)
	if err != nil {
		return err
	}
	nativeMirrorEnabled, err := parseBoolEnvFrom(os.Getenv, "FANOUT_NATIVE_MIRROR_CONSUMER_ENABLED", false)
	if err != nil {
		return err
	}
	if !webhookEnabled && !nativeMirrorEnabled {
		return errors.New("no consumer enabled: at least one of FANOUT_WEBHOOK_CONSUMER_ENABLED / FANOUT_NATIVE_MIRROR_CONSUMER_ENABLED must be true")
	}

	// Repo-lookup client talks to entire-core's internal mTLS listener over
	// the workload PCA cert mounted by fleet's _lib/internal-tls. Both
	// consumers resolve through it (webhook: LookupByMirror; native-mirror:
	// LookupNativeMirrorsByRepoID), each behind its own read-through cache:
	// short negative TTL so new mirrors activate quickly, longer positive
	// TTL since placements rarely change.
	lookupClient, err := mirrorjobs.NewRepoLookupClient(
		os.Getenv("ENTIRE_INTERNAL_TLS_CERT_FILE"),
		os.Getenv("ENTIRE_INTERNAL_TLS_KEY_FILE"),
		os.Getenv("ENTIRE_INTERNAL_TLS_CA_FILE"),
		os.Getenv("ENTIRE_CORE_INTERNAL_URL"),
	)
	if err != nil {
		return fmt.Errorf("init repo lookup client: %w", err)
	}
	var resolver *mirrorjobs.CoreLookupResolver
	if webhookEnabled {
		cachedLookup := mirrorjobs.NewCachingRepoLookupClient(lookupClient, 60*time.Second, 5*time.Second)
		go cachedLookup.Run(ctx)
		resolver = mirrorjobs.NewCoreLookupResolver(cachedLookup)
	}
	var nativeResolver *mirrorjobs.NativeMirrorResolver
	if nativeMirrorEnabled {
		cachedNativeLookup := mirrorjobs.NewCachingNativeMirrorLookupClient(lookupClient, 60*time.Second, 5*time.Second)
		go cachedNativeLookup.Run(ctx)
		nativeResolver = mirrorjobs.NewNativeMirrorResolver(cachedNativeLookup)
	}

	listenAddr := svchttp.ListenAddr(os.Getenv)

	// Required so a multi-region rollout cannot accidentally share consumer
	// state. JetStream durables are stream-scoped; if EU fanout starts
	// consuming from the US upstream stream during a transition with the
	// same durable name as US fanout, the two consumers share delivery
	// cursor and redelivery state. Distinct durable per region (e.g.
	// "fanout-us-east-2", "fanout-eu-central-1") is the cheapest safeguard.
	// (The native-mirror consumer's durable is fixed instead: its stream is
	// per-cluster local, so no two clusters can collide.)
	durable := os.Getenv("FANOUT_DURABLE")
	if webhookEnabled && durable == "" {
		return errors.New("FANOUT_DURABLE is required when the webhook consumer is enabled (e.g. fanout-us-east-2)")
	}

	// Multi-region NATS routing for mirror.git.v1.> publishes (see
	// docs/multi-region/cross-region-nats-cutover.md). FANOUT_NATS_REGIONS
	// is a comma-separated cluster_id=url list of REMOTE NATS clusters
	// fanout should dial in addition to its local NATS. Empty = single-
	// region mode (everything publishes to the local NATS, backward
	// compatible). When set, FANOUT_LOCAL_CLUSTER_ID is required so the
	// local connection is registered in the routing map under the right
	// key; unknown cluster_ids in routes returned by Core then surface
	// as publish errors (consumer Naks, operator fixes the map).
	remoteRegions, err := natsregions.ParseConfig(os.Getenv("FANOUT_NATS_REGIONS"))
	if err != nil {
		return fmt.Errorf("FANOUT_NATS_REGIONS: %w", err)
	}
	localClusterID := os.Getenv("FANOUT_LOCAL_CLUSTER_ID")
	if err := natsregions.ValidateLocalClusterID(localClusterID, remoteRegions); err != nil {
		return fmt.Errorf("FANOUT_LOCAL_CLUSTER_ID: %w", err)
	}
	// The native-mirror consumer needs the local cluster identity even in
	// single-region mode: it is the loop-prevention key — events whose home
	// cluster isn't THIS cluster are dropped. Without it every mirror-side
	// echo of a worker push would be indistinguishable from a home push.
	if nativeMirrorEnabled && localClusterID == "" {
		return errors.New("FANOUT_LOCAL_CLUSTER_ID is required when the native-mirror consumer is enabled")
	}
	if nativeMirrorEnabled && len(remoteRegions) == 0 {
		// Legal (a single-cluster environment has no remotes) but worth a
		// loud note: with an empty region map every publish resolves to the
		// LOCAL NATS, so a sync job for a native mirror hosted on another
		// cluster would land on the local mirror_git_v1 where no worker
		// consumes its subject — it ages out silently after StreamMaxAge.
		slog.Warn("Native-mirror consumer enabled with no FANOUT_NATS_REGIONS: cross-cluster sync jobs would publish to LOCAL NATS and be dropped; fine only while no native mirrors exist for repos homed on this cluster (they are always cross-cluster)")
	}

	// DLQ capture (and its crash backstop) is opt-in (ENTIRE_WEBHOOK_DLQ_ENABLED)
	// so this binary ships ahead of the fleet-provisioned webhooks_github_dlq
	// stream + grants. Webhook-consumer-only: the DLQ preserves webhook
	// deliveries for replay; ref events are healed by the primary's next
	// push instead. Resolve it before dialing: the backstop's permission-error
	// handler must be attached as a dial option (a rejected advisory SUBSCRIBE only
	// surfaces via the connection's async ErrHandler), and it shares one metric set
	// with the backstop, so both are built up front.
	dlqEnabled := webhookEnabled && webhookdlq.Enabled(os.Getenv)
	var backstopMetrics *webhookdlq.BackstopMetrics
	var localDialOpts []nats.Option
	if dlqEnabled {
		backstopMetrics, err = webhookdlq.NewBackstopMetrics()
		if err != nil {
			return fmt.Errorf("init DLQ backstop metrics: %w", err)
		}
		localDialOpts = append(localDialOpts, nats.ErrorHandler(
			webhookdlq.PermErrorHandler(backstopMetrics, webhookevents.StreamName, durable)))
	}

	nc, err := nuts.Connect(ctx, natsURL, nuts.WithNATSOptions(localDialOpts...))
	if err != nil {
		return fmt.Errorf("connect to NATS: %w", err)
	}
	defer func() {
		retErr = errors.Join(retErr, nuts.Drain(ctx, nc, "fanout", nil, consumerDrainTimeout))
	}()

	js, err := nc.JetStream()
	if err != nil {
		return fmt.Errorf("create JetStream context: %w", err)
	}
	// Publishing (Regions + DLQ capture) rides the modern handle; the engine's
	// fetch loops and the advisory backstop's reads stay on the legacy js.
	pubJS, err := jetstream.New(nc)
	if err != nil {
		return fmt.Errorf("create JetStream client: %w", err)
	}

	// Streams are owned declaratively by the nack jetstream-controller
	// (fleet apps/nats-streams) — fanout neither creates nor reconciles
	// mirror_git_v1, it only publishes to it. If the stream isn't present
	// yet, the publish fails and the consumer Naks → JetStream redelivers
	// (the same path as a transient downstream error).
	slog.Info("Local NATS connected", slog.String("url", natsURL))

	// Build the engine's region map. Local is the only target in single-region
	// mode (ByKey nil). In multi-region mode every region's JetStream context is
	// entered under its cluster_id (the local one under FANOUT_LOCAL_CLUSTER_ID),
	// and the engine routes each route's publish by cluster_id, Nak-ing an
	// unmapped one. Each gitSyncRoute builds its mirrorjobs publisher over the
	// engine-resolved region handle, so the publish itself is unchanged.
	regions := fanoutengine.Regions{Local: pubJS}
	remoteConns := map[string]*nats.Conn{} // for natsregions.Health + lifetime ownership
	defer func() {
		for _, c := range remoteConns {
			c.Close()
		}
	}()
	if len(remoteRegions) > 0 {
		regions.ByKey = map[string]fanoutengine.PublishJS{localClusterID: pubJS}
		conns, err := natsregions.DialRemotes(remoteRegions)
		if err != nil {
			return err
		}
		remoteConns = conns
		for clusterID, conn := range conns {
			remoteJS, err := jetstream.New(conn)
			if err != nil {
				return fmt.Errorf("create JetStream context for %s: %w", clusterID, err)
			}
			// The remote mirror_git_v1 is owned by the nack controller local
			// to that cluster; fanout only publishes to it.
			regions.ByKey[clusterID] = remoteJS
		}
	}
	healthRemotes := make(map[string]natsregions.ConnStatus, len(remoteConns))
	for cid, c := range remoteConns {
		healthRemotes[cid] = c
	}
	health := natsregions.NewHealth(nc, healthRemotes)
	if err := registerRegionGauge(health); err != nil {
		return err
	}

	concurrency, fetchBatch, err := resolvePoolConfig(os.Getenv)
	if err != nil {
		return err
	}

	// consumers collects every enabled consumer so readiness and shutdown
	// treat them uniformly: /readyz requires ALL of them subscribed, and the
	// drain below waits for ALL their in-flight messages.
	type runningConsumer struct {
		name string
		cons *fanoutengine.Consumer
		done chan struct{}
	}
	var consumers []*runningConsumer

	if webhookEnabled {
		metrics, err := newFanoutMetrics()
		if err != nil {
			return fmt.Errorf("init metrics: %w", err)
		}
		syncRes := newSyncResolver(resolver)

		// The DLQ is co-located with webhooks_github_v1 (local, US-only), so it rides
		// the local js even in multi-region mode. The advisory backstop captures
		// deliveries this consumer dropped UNcaptured when a pod died between giving up
		// and the inline DLQ publish — out-of-band off the MAX_DELIVERIES/MSG_TERMINATED
		// advisories for this consumer's durable, idempotent against the inline capture
		// via the same Nats-Msg-Id dedup. See pkg/webhookdlq/advisory.go.
		var dlq *webhookdlq.Publisher
		var engineDLQ fanoutengine.DLQ // nil interface when capture is disabled
		if dlqEnabled {
			dlq = webhookdlq.NewPublisher(pubJS)
			engineDLQ = dlqSink{pub: dlq}
			backstop := webhookdlq.NewBackstop(webhookdlq.SourceFanout, webhookevents.StreamName, durable, js, dlq, backstopMetrics)
			go backstop.Run(ctx, nc)
			slog.Info("Webhook DLQ capture enabled",
				slog.String("stream", webhookdlq.StreamName), slog.String("durable", durable))
		}

		consumers = append(consumers, &runningConsumer{
			name: "webhook",
			cons: newConsumer(js, syncRes, regions, metrics, durable, concurrency, fetchBatch, engineDLQ),
			done: make(chan struct{}),
		})
		slog.Info("Webhook consumer enabled",
			slog.String("durable", durable),
			slog.String("subject", webhookevents.SubjectPrefix+">"),
		)
	}

	if nativeMirrorEnabled {
		metrics, err := newNativeMirrorMetrics()
		if err != nil {
			return fmt.Errorf("init native-mirror metrics: %w", err)
		}
		nativeSyncRes := newNativeMirrorSyncResolver(nativeResolver, localClusterID)
		consumers = append(consumers, &runningConsumer{
			name: "native-mirror",
			cons: newNativeMirrorConsumer(js, nativeSyncRes, regions, metrics, concurrency, fetchBatch),
			done: make(chan struct{}),
		})
		slog.Info("Native-mirror consumer enabled",
			slog.String("durable", nativeMirrorDurable),
			slog.String("subject", refevents.NATSSubjectPrefix+">"),
			slog.String("local_cluster_id", localClusterID),
		)
	}

	for _, rc := range consumers {
		go func() {
			defer close(rc.done)
			rc.cons.Run(ctx)
		}()
	}
	slog.Info("Consumers started",
		slog.Int("consumers", len(consumers)),
		slog.Int("dispatch_concurrency", concurrency),
		slog.Int("fetch_batch", fetchBatch),
	)

	// Readiness gates on the LOCAL NATS connection only. Remote-region health
	// is deliberately not a readiness condition: a remote outage already
	// fails the publishes routed there (consumer Naks → JetStream
	// redelivers, no loss inside the webhook stream's MaxAge), and gating
	// on it would stall ALL regions' mirroring for one region's problem.
	// Remote state is surfaced via the fanout.nats.region_connected gauge +
	// disconnect logs instead.
	//
	// Consumer not subscribed → pod is not doing its job. Common causes:
	// NATS user lacks subscribe perm on the upstream subject, or
	// entire-core's RepoLookup allowlist rejects this workload's SPIFFE
	// identity (route resolution fails inside dispatch, but at boot the
	// subscribe itself may fail or stall). Surface as NotReady so k8s + ops
	// can see it.
	mux := svchttp.NewMux(func() (bool, string) {
		if ok, reason := health.Status(); !ok {
			return false, reason
		}
		for _, rc := range consumers {
			if !rc.cons.Ready() {
				return false, rc.name + " consumer not subscribed"
			}
		}
		return true, ""
	})
	if err := svchttp.Serve(ctx, listenAddr, mux); err != nil {
		return err
	}

	// Let every consumer finish its in-flight message before the deferred
	// nuts.Drain closes the connection under it. This matters most for a
	// terminal delivery mid-DLQ-capture: the capture publish is decoupled from
	// the shutdown ctx (see webhookdlq.Publisher.Publish) so it can still land,
	// but only while the connection is alive. One shared deadline (not
	// per-consumer) so a wedged Fetch/publish can't block exit.
	allDone := make(chan struct{})
	go func() {
		defer close(allDone)
		for _, rc := range consumers {
			<-rc.done
		}
	}()
	select {
	case <-allDone:
	case <-time.After(consumerDrainTimeout):
		slog.Warn("Consumer drain timed out on shutdown; in-flight message may be redelivered")
	}
	return nil
}

// resolvePoolConfig reads the worker-pool knobs from the environment and
// validates them together. concurrency defaults to 1 — strictly serial,
// identical to the pre-pool behavior — so this binary ships inert and fleet
// raises FANOUT_DISPATCH_CONCURRENCY only after validating per-pod headroom
// (prod caps fanout at 10 pods, so per-pod throughput is the lever). fetchBatch
// defaults to concurrency: pull exactly enough to keep every worker fed without
// over-fetching. Both must be >= 1 (fail fast, matching FANOUT_DURABLE /
// ParseStreamReplicas), and fetchBatch must not exceed concurrency.
//
// The fetchBatch <= concurrency cap is an AckWait-correctness bound, not just a
// memory one: JetStream starts a message's AckWait clock when it DELIVERS the
// message — i.e. when sub.Fetch returns it to this process — not when a worker
// finally picks it up. The consumeLoop hand-off channel is unbuffered, so if a
// Fetch returns more than `concurrency` messages the surplus sit un-dispatched
// in the just-fetched slice while their AckWait (consumerAckWait, 30s) is
// already running. With fetchBatch >> concurrency the tail of a batch can age
// past AckWait before any worker starts it, and JetStream redelivers it → the
// same webhook dispatches twice (duplicate mirror-git jobs) and NumDelivered
// inflates toward MaxDeliver. Capping at concurrency guarantees every fetched
// message reaches a free worker within ~one dispatch latency. (fetchBatch ==
// concurrency is the sweet spot and the default; a smaller fetchBatch is fine —
// it just means more, smaller Fetches.) Takes getenv so it is unit-testable.
func resolvePoolConfig(getenv func(string) string) (concurrency, fetchBatch int, err error) {
	concurrency, err = parsePositiveEnvFrom(getenv, "FANOUT_DISPATCH_CONCURRENCY", 1)
	if err != nil {
		return 0, 0, err
	}
	fetchBatch, err = parsePositiveEnvFrom(getenv, "FANOUT_FETCH_BATCH", concurrency)
	if err != nil {
		return 0, 0, err
	}
	if fetchBatch > concurrency {
		return 0, 0, fmt.Errorf("FANOUT_FETCH_BATCH (%d) must not exceed FANOUT_DISPATCH_CONCURRENCY (%d): a larger batch would leave fetched messages un-dispatched against AckWait and risk redelivery", fetchBatch, concurrency)
	}
	return concurrency, fetchBatch, nil
}

// parsePositiveEnvFrom reads a positive-integer env var via getenv, returning
// def when unset/empty. Any present value must parse as an integer >= 1;
// non-integer, zero, or negative input is a hard startup error rather than a
// silent fallback. Fail fast is deliberate and matches the rest of fanout's
// config (FANOUT_DURABLE, pkg/gitjobs.ParseStreamReplicas): the worker-pool
// knobs gate correctness (a 0 concurrency would wedge the consumer with no
// workers; a 0 fetchBatch would make every Fetch a no-op), so a typo in deploy
// config should refuse to start, not ship a broken pod that looks healthy.
// (cmd/rekicker's envPositiveInt clamps-with-warning instead; that fits a
// throttle knob with a safe default, but here the value is load-bearing, so we
// reject like the other required fanout vars.) getenv is injected so the parse
// is unit-testable without mutating process environment.
func parsePositiveEnvFrom(getenv func(string) string, key string, def int) (int, error) {
	raw := getenv(key)
	if raw == "" {
		return def, nil
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return 0, fmt.Errorf("%s: invalid integer %q: %w", key, raw, err)
	}
	if n < 1 {
		return 0, fmt.Errorf("%s: must be >= 1, got %d", key, n)
	}
	return n, nil
}

// parseBoolEnvFrom reads a boolean env var via getenv, returning def when
// unset/empty. Any present value must parse with strconv.ParseBool; garbage is
// a hard startup error rather than a silent fallback — these flags select
// which consumers run at all, so a typo must refuse to start, not silently
// ship a pod doing the wrong job (same fail-fast policy as the rest of
// fanout's config). getenv is injected so the parse is unit-testable.
func parseBoolEnvFrom(getenv func(string) string, key string, def bool) (bool, error) {
	raw := getenv(key)
	if raw == "" {
		return def, nil
	}
	v, err := strconv.ParseBool(raw)
	if err != nil {
		return false, fmt.Errorf("%s: invalid boolean %q: %w", key, raw, err)
	}
	return v, nil
}

