1	package mirrorjobs
2	
3	import (
4		"context"
5		"sync"
6		"time"
7	
8		"connectrpc.com/connect"
9		"go.opentelemetry.io/otel/attribute"
10		"go.opentelemetry.io/otel/trace"
11		"golang.org/x/sync/singleflight"
12	
13		repolookupv1 "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1"
14	)
15	
16	// CachingNativeMirrorLookupClient wraps a NativeMirrorLookupClient with a
17	// read-through in-memory cache keyed on repo id — the native-mirror twin of
18	// CachingRepoLookupClient, with the same coalescing/retry/detached-context
19	// semantics (see that type's doc for the full rationale).
20	//
21	// Responses with at least one serving mirror — native or namespace — live
22	// for PosTTL; "no mirrors at all" responses — the overwhelmingly common
23	// case, every repo without replicas resolves to one on every push — live
24	// for NegTTL, kept short on purpose so a freshly registered mirror starts
25	// replicating within seconds rather than a full PosTTL. Errors (including
26	// CodeNotFound for a deleted repo) are never cached.
27	type CachingNativeMirrorLookupClient struct {
28		inner         NativeMirrorLookupClient
29		posTTL        time.Duration
30		negTTL        time.Duration
31		lookupTimeout time.Duration
32		sweepInterval time.Duration
33		now           func() time.Time
34	
35		entries sync.Map // map[string]*nativeCacheEntry
36		group   singleflight.Group
37	}
38	
39	type nativeCacheEntry struct {
40		resp      *repolookupv1.LookupNativeMirrorsByRepoIDResponse
41		expiresAt time.Time
42	}
43	
44	// nativeLookupOutcome is the value singleflight broadcasts to all coalesced
45	// waiters (see lookupOutcome for why retried rides along).
46	type nativeLookupOutcome struct {
47		resp    *repolookupv1.LookupNativeMirrorsByRepoIDResponse
48		retried bool
49	}
50	
51	// NewCachingNativeMirrorLookupClient builds a cache around inner. A zero
52	// posTTL or negTTL disables caching for that class of response.
53	func NewCachingNativeMirrorLookupClient(inner NativeMirrorLookupClient, posTTL, negTTL time.Duration) *CachingNativeMirrorLookupClient {
54		return &CachingNativeMirrorLookupClient{
55			inner:         inner,
56			posTTL:        posTTL,
57			negTTL:        negTTL,
58			lookupTimeout: defaultLookupTimeout,
59			sweepInterval: defaultSweepInterval,
60			now:           time.Now,
61		}
62	}
63	
64	func (c *CachingNativeMirrorLookupClient) LookupNativeMirrorsByRepoID(ctx context.Context, req *connect.Request[repolookupv1.LookupNativeMirrorsByRepoIDRequest]) (*connect.Response[repolookupv1.LookupNativeMirrorsByRepoIDResponse], error) {
65		span := trace.SpanFromContext(ctx)
66		key := req.Msg.GetRepoId()
67		if entry, ok := c.lookup(key); ok {
68			span.SetAttributes(
69				attribute.String("mirrorjobs.native_lookup.cache", "hit"),
70				attribute.Int("mirrorjobs.native_lookup.native_mirrors", len(entry.resp.GetNativeMirrors())),
71			)
72			return connect.NewResponse(entry.resp), nil
73		}
74	
75		// Retry once inside the singleflight slot so every coalesced waiter
76		// shares the retry — same shape and rationale as
77		// CachingRepoLookupClient.LookupByMirror.
78		attempt := func() (*connect.Response[repolookupv1.LookupNativeMirrorsByRepoIDResponse], error) {
79			aCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), c.lookupTimeout)
80			defer cancel()
81			return c.inner.LookupNativeMirrorsByRepoID(aCtx, req)
82		}
83	
84		doLookup := func() (any, error) {
85			resp, err := attempt()
86			retried := false
87			if err != nil {
88				// CodeNotFound is a definitive answer (deleted repo), not a
89				// transient failure — retrying it just doubles the RPC.
90				if connect.CodeOf(err) == connect.CodeNotFound {
91					return nil, err
92				}
93				retried = true
94				resp, err = attempt()
95				if err != nil {
96					return nil, err
97				}
98			}
99			c.store(key, resp.Msg)
100			return &nativeLookupOutcome{resp: resp.Msg, retried: retried}, nil
101		}
102	
103		res, err := c.awaitLookup(ctx, key, doLookup)
104		if err != nil {
105			return nil, err
106		}
107		if res.Err != nil {
108			return nil, res.Err
109		}
110	
111		out, _ := res.Val.(*nativeLookupOutcome)
112		span.SetAttributes(
113			attribute.String("mirrorjobs.native_lookup.cache", "miss"),
114			attribute.Bool("mirrorjobs.native_lookup.cache.coalesced", res.Shared),
115			attribute.Bool("mirrorjobs.native_lookup.cache.retried", out.retried),
116			attribute.Int("mirrorjobs.native_lookup.native_mirrors", len(out.resp.GetNativeMirrors())),
117		)
118		return connect.NewResponse(out.resp), nil
119	}
120	
121	// awaitLookup runs the singleflight call and blocks until either the result
122	// arrives or the caller's ctx is canceled; the slot keeps running and still
123	// populates the cache for the next caller.
124	func (c *CachingNativeMirrorLookupClient) awaitLookup(ctx context.Context, key string, fn func() (any, error)) (singleflight.Result, error) {
125		select {
126		case res := <-c.group.DoChan(key, fn):
127			return res, nil
128		case <-ctx.Done():
129			return singleflight.Result{}, ctx.Err()
130		}
131	}
132	
133	// Run periodically evicts expired entries until ctx is canceled — same
134	// bounded-memory rationale as CachingRepoLookupClient.Run.
135	func (c *CachingNativeMirrorLookupClient) Run(ctx context.Context) {
136		ticker := time.NewTicker(c.sweepInterval)
137		defer ticker.Stop()
138		for {
139			select {
140			case <-ctx.Done():
141				return
142			case <-ticker.C:
143				c.sweep()
144			}
145		}
146	}
147	
148	func (c *CachingNativeMirrorLookupClient) sweep() {
149		now := c.now()
150		c.entries.Range(func(k, v any) bool {
151			entry, ok := v.(*nativeCacheEntry)
152			if !ok {
153				c.entries.Delete(k)
154				return true
155			}
156			if !now.Before(entry.expiresAt) {
157				c.entries.CompareAndDelete(k, v)
158			}
159			return true
160		})
161	}
162	
163	func (c *CachingNativeMirrorLookupClient) store(key string, resp *repolookupv1.LookupNativeMirrorsByRepoIDResponse) {
164		// Never cache a response the resolver will reject (missing home cluster
165		// slug; serving mirrors without a source URL). The resolver's rejection
166		// Naks the delivery so JetStream redelivers — but a cached bad response
167		// would keep failing those redeliveries for a full TTL after the
168		// Core-side fix lands. An uncached one costs an extra RPC per
169		// redelivery and heals immediately.
170		if validateNativeMirrorLookupResponse(resp) != nil {
171			return
172		}
173		ttl := c.posTTL
174		if len(resp.GetNativeMirrors()) == 0 && len(resp.GetNamespaceMirrors()) == 0 {
175			ttl = c.negTTL
176		}
177		if ttl > 0 {
178			c.entries.Store(key, &nativeCacheEntry{
179				resp:      resp,
180				expiresAt: c.now().Add(ttl),
181			})
182		}
183	}
184	
185	func (c *CachingNativeMirrorLookupClient) lookup(key string) (*nativeCacheEntry, bool) {
186		v, ok := c.entries.Load(key)
187		if !ok {
188			return nil, false
189		}
190		entry, ok := v.(*nativeCacheEntry)
191		if !ok {
192			return nil, false
193		}
194		if !c.now().Before(entry.expiresAt) {
195			c.entries.Delete(key)
196			return nil, false
197		}
198		return entry, true
199	}
