func (s dlqSink) Capture(ctx context.Context, dl fanoutengine.DeadLetter) error {
	rec := webhookdlq.DeadLetter{
		Source:          webhookdlq.SourceFanout,
		Reason:          dl.Reason,
		OriginalSubject: dl.Subject,
		DeliveryID:      dl.DeliveryID,
		Event:           dl.Event,
		Deliveries:      dl.Deliveries,
		Envelope:        dl.Envelope,
		DeadLetteredAt:  time.Now(),
	}
	if dl.Err != nil {
		rec.LastError = dl.Err.Error()
	}
	return s.pub.Publish(ctx, rec)
}

