// row's own placement with nothing to replicate (whole-repo GitHub mirroring
// routes through LookupByMirror). Returns ErrNotFound when no registry row
// exists for repoID.
func (s *Service) ResolveRouting(ctx context.Context, repoID model.RepoID) (Routing, error) {
	// One read resolves the row, its group identity, and — via the group's
	// data_primary_repo_id — the primary's own registry row and cluster.
	var (
		ownJur, ownSlug   string
		forge, primaryID  *string
		namespaceOwner    *string
		homeJur, homeSlug *string
		homeInternalURL   *string
	)
	// g is INNER: r.repo_group_id is NOT NULL with a FK to repo_group(id).
	// pr stays LEFT: g.data_primary_repo_id has no FK, and the primary's own
	// registry row can be gone mid-teardown (see below).
	err := s.pool.QueryRow(ctx,
		`SELECT r.jurisdiction, COALESCE(r.cluster_slug, ''),
		        g.forge, g.data_primary_repo_id, g.entire_data_primary,
		        pr.jurisdiction, pr.cluster_slug,
		        hc.internal_url
		 FROM repo_registry r
		 JOIN repo_group g ON g.id = r.repo_group_id
		 LEFT JOIN repo_registry pr ON g.forge = 'entire' AND pr.id = g.data_primary_repo_id
		 LEFT JOIN clusters hc ON hc.slug = pr.cluster_slug
		 WHERE r.id = $1`,
		repoID,
	).Scan(&ownJur, &ownSlug, &forge, &primaryID, &namespaceOwner, &homeJur, &homeSlug, &homeInternalURL)
	if errors.Is(err, pgx.ErrNoRows) {
		return Routing{}, ErrNotFound
	}
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s: %w", repoID, err)
	}

	self := RoutingPlacement{RepoID: repoID, Jurisdiction: ownJur, ClusterSlug: ownSlug}
	if forge != nil && *forge == "github" && namespaceOwner != nil && primaryID != nil {
		return leaseholderFallback(ctx, repoID, s.reads.AOST(), func(aost postgres.AOST) (Routing, error) {
			return s.namespaceRouting(ctx, repoID, self, *namespaceOwner, *primaryID, aost)
		})
	}
	if forge == nil || *forge != "entire" || primaryID == nil || homeJur == nil {
		// Mirror group, ungrouped row, or a group whose primary's registry
		// row is gone mid-teardown: nothing to mirror from here.
		return Routing{Home: self}, nil
	}
	primaryRepoID, err := model.ParseRepoID(*primaryID)
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s: primary id %q: %w", repoID, *primaryID, err)
	}
	home := RoutingPlacement{RepoID: primaryRepoID, Jurisdiction: *homeJur}
	if homeSlug != nil {
		home.ClusterSlug = *homeSlug
	}

	routing := Routing{Home: home}
	if homeInternalURL != nil && *homeInternalURL != "" {
		routing.SourceURL = gitjobs.EntireDBSourceURL(*homeInternalURL, *primaryID)
	}

