	// query, and deliberately repeats the WHERE clause's replication terms
	// instead of narrowing to `nr.status = 'ready'` alone: ReadEligible then
	// carries the whole read gate on its own, so widening the filter later
	// can never quietly widen what the read path accepts.
	rows, err := s.pool.Query(ctx,
		`SELECT nr.id, c.jurisdiction, nr.cluster_slug, `+readEligible+`
		 FROM native_mirrors nr
		 JOIN repo_group g ON g.id = nr.repo_group_id
		 JOIN clusters c ON c.slug = nr.cluster_slug
		 WHERE g.forge = 'entire' AND g.data_primary_repo_id = $1
		   AND `+replicationFilter+`
		 ORDER BY c.jurisdiction, nr.cluster_slug`,
		*primaryID,
	)
