	"entire.io/slogutil"
)

// regionalModeSubsystems is THE manifest of the background units regional mode
// runs, in Serve() start order (COR-832): rate-limit cleanup, the globaldb
// region check, the provisioning reconciler, then the mirror-done /
// perms-backfill / verified-email consumers when NATS built them (NATS is
// required at boot in regional mode, so in practice all three are present),
// the org-invitation token sweep, the detach cleanup relay, and the
// cascade-delete finisher.
//
// The reconciler is unconditional here: regional always wires a full
// JurisdictionCapabilities group (buildJurisdictionCaps in api_server.go), so
// provisioningReconcilerSubsystem's nil-caps guard never trips in practice.
// RunReconciler's own point-of-use check (the unwired-RepoBridge case)
// preserves the warn-and-skip behavior if the bridge is ever unconfigured.
//
// Regional deliberately does NOT run the perms webhook / read-model consumers:
// the GitHub-perms ingress is global-only (regional builds neither consumer).
// The account-erasure poller is started inline in Serve() (it needs the
// fully-wired *api.Server as its region eraser), not via this manifest.
func regionalModeSubsystems(deps serveDeps, srv *coreapi.Server) ([]subsystem, error) {
	var (
		subs []subsystem
		err  error
	)
	if subs, err = requireSubsystem(subs, srv, rateLimitCleanupSubsystem); err != nil {
		return nil, err
	}
	// The check belongs on the GLOBAL pool — the multi-region database with the
	// REGIONAL BY ROW tables — never on this cell's regional pool.
	if subs, err = requireSubsystem(subs, deps.globalPool, globalDBRegionCheckSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv.JurisdictionCaps(), provisioningReconcilerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.mirrorCreateConsumer, mirrorCreateSubsystem); err != nil {
		return nil, err
	}
	for _, c := range deps.mirrorDoneConsumers {
		if subs, err = requireSubsystem(subs, c, mirrorDoneSubsystem); err != nil {
			return nil, err
		}
	}
	if subs, err = maybeSubsystem(subs, deps.nativeMirrorExecutor, nativeMirrorExecutorSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.nativeMirrorCreateConsumer, nativeMirrorCreateSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.nativeMirrorRequestSweep, nativeMirrorRequestSweepSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.entireDataPrimarySink.assignmentPass(), entireDataPrimaryPassSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.trustReconciler, trustReconcilerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.placementAcceptanceWorker, placementAcceptanceSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.trustRootOnCreateSweep, trustRootOnCreateSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.mirrorURLDrainer, mirrorURLDrainerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.repoCellCleanupDrainer, repoCellCleanupDrainerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.permsBackfillConsumer, permsBackfillSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.pluginGrantsConsumer, pluginGrantsSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.verifiedEmailConsumer, verifiedEmailSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.emailRelay, emailRelaySubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.emailConsumer, emailConsumerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, deps.orgInvitationTokenSweeper, orgInvitationTokenSweepSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv, detachCleanupRelaySubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv, repoDetachSweepSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv, cascadeDeleteFinisherSubsystem); err != nil {
		return nil, err
	}
	return subs, nil
}

// buildRegionalServeDeps assembles the full serving-core dependency graph for a
// regional core: identity/regional/authz/resource stores, the account-erasure
// outbox (drained by a per-region poller, ADR 20260708) and the transactional-
// email fan-out (outbox + relay + consumer), signing keys, JWKS,
// the cluster registry (reconciled here — serving cores own it), and the repo
// bridge. The account-deletion reaper does NOT use this bootstrap: it wires a
// lean control-plane-only graph via buildReaperDeps (ADR 20260707), which is why
// this no longer takes withFanout / reconcileRegistry flags.
func buildRegionalServeDeps(ctx context.Context, cfg Config, lifecycleEmitter *resourceevents.Emitter, billingSubjects []runnerpolicy.BillingSubject) (serveDeps, func(), error) {
	var deps serveDeps

	if cfg.GlobalCockroachDSN == "" {
		return deps, func() {}, errors.New("GLOBAL_COCKROACH_DSN is required in regional mode")
	}
	if cfg.Jurisdiction == "" {
		return deps, func() {}, errors.New("--jurisdiction is required in regional mode")
	}
	if cfg.AuthBaseURL == "" {
		return deps, func() {}, errors.New("ENTIRE_CORE_AUTH_BASE_URL is required in regional mode")
	}
	billingEnforcement, err := runnerpolicy.ParseBillingEnforcement(cfg.RunnerBillingEnforcement)
	if err != nil {
		return deps, func() {}, fmt.Errorf("ENTIRE_RUNNER_BILLING_ENFORCEMENT: %w", err)
	}
	if cfg.RegionHosts == "" {
		return deps, func() {}, errors.New("REGION_HOSTS is required in regional mode")
	}

	// Two pools: global (identity, resources, keys) + regional (PII, audit).
	globalPool, err := postgres.NewPool(ctx, cfg.GlobalCockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
	if err != nil {
		return deps, func() {}, fmt.Errorf("connect global cockroachdb: %w", err)
	}

	regionalPool, err := postgres.NewPool(ctx, cfg.CockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
	if err != nil {
		globalPool.Close()
		return deps, func() {}, fmt.Errorf("connect regional cockroachdb: %w", err)
	}
	cleanups := []func(){
		func() { regionalPool.Close() },
		func() { globalPool.Close() },
	}
	cleanup := func() {
		for _, cleanup := range slices.Backward(cleanups) {
			cleanup()
		}
	}

	// Reads go to the local SpiceDB (sidecar/replica); writes go to the
	// read-write authz-writer when configured, else back to the sidecar.
	spiceRead, spiceWrite, err := dialSpiceDB(cfg)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
	// Read-mostly: only contacts the authz-writer when the datastore's schema
	// is stale/absent, so a writer/NLB outage doesn't block boot. Never fatal:
	// a fresh cell that can't write its schema serves schema-less (authz-gated
	// requests 500) and the retry converges once the writer is back.
	if !authz.EnsureSchema(ctx, spiceRead, spiceWrite) {
		retryCtx, cancelRetry := context.WithCancel(ctx)
		cleanups = append(cleanups, cancelRetry)
		go authz.EnsureSchemaUntilCurrent(retryCtx, spiceRead, spiceWrite, time.Minute)
	}

	deps.globalPool = globalPool
	deps.identitySvc = membershipIdentityStore(cfg, globalPool)
	deps.authzSvc = authz.NewStoreRW(spiceRead, spiceWrite)

	// System service-account grants are reconciled by `entire-core
	// bootstrap` (see internal/entirecore/bootstrap.go); they require
	// the system org and service_accounts rows that bootstrap creates.
	// Run bootstrap once before the first serve.

	pluginsStore := plugins.NewStore(globalPool)
	pluginCatalog := plugins.NewCatalogStore(globalPool)
	deps.pluginCatalog, deps.pluginAdmin = pluginCatalog, pluginCatalog
	// Held concrete too: the executor needs PublishRepoInTx, not on the interface.
	resourceStore := resource.NewStore(globalPool, deps.authzSvc,
		resource.WithProcessingCellElection(cfg.MirrorElectInProcessingCellEnabled))
	// The detach runs in the placement's jurisdiction, so only a regional
	// core serves it.
	deps.detachStore = repodetach.NewStore(globalPool)
	deps.resourceSvc = resourceStore
	deps.automationSvc = automation.NewStore(globalPool)
	grantProvisioner := plugins.Provisioner{
		Installations: pluginsStore, Plugins: pluginCatalog, Automations: deps.automationSvc, Grants: deps.authzSvc, Fence: resourceStore,
	}
	deps.detachPluginReconciler = plugins.CoveringReconciler{Installations: pluginsStore, Provisioner: grantProvisioner}
	deps.pluginsSvc = pluginsStore
	deps.runnerPolicySvc = newRunnerPolicyStore(globalPool, billingEnforcement, billingSubjects)
	if err := deps.runnerPolicySvc.RegisterModeGauge(); err != nil {
		slogutil.Warn(ctx, "runner policy mode gauge registration failed", slog.String("error", err.Error()))
	}
	billingEnsure := billing.NewGlobalEnsureStore(globalPool)
	billingDir := newRegionalBillingDirectory(ctx, cfg, deps.resourceSvc, deps.identitySvc)
	deps.billingEnsurer = billing.NewEnsurer(billingEnsure, billingDir)
	deps.runnerPolicySvc.WithBillingEnsurer(deps.billingEnsurer)
	// Built before billing wiring, which sends billing events through it.
	deps.analyticsClient = analytics.New(cfg.AnalyticsConfig())
	deps.billingOverviewCache = billing.NewOverviewCache()
	if err := wireMetronomeWebhooks(cfg, globalPool, billingDir, &deps); err != nil {
		cleanup()
		return deps, func() {}, err
	}
	if err := wireBillingAccountConsumers(cfg, billingConsumerPools{global: globalPool, regional: regionalPool},
		billing.NewMetronomeClient(cfg.MetronomeAPIKey), deps.runnerPolicySvc, billingDir, &deps); err != nil {
		cleanup()
		return deps, func() {}, err
	}
	if deps.billingSvc != nil {
		deps.billingTrialPoller = billing.NewTrialPoller(billingEnsure, deps.billingSvc, billingDir, cfg.Jurisdiction)
	}
	globalRepoDeletionOutbox := repodeletion.NewNativeMirror(globalPool, cfg.Jurisdiction)
	regionalRepoDeletionOutbox := repodeletion.NewRegional(regionalPool, cfg.Jurisdiction)
	deps.repoDeletionRelays = []*repodeletion.Relay{
		globalRepoDeletionOutbox.Relay(lifecycleEmitter),
		regionalRepoDeletionOutbox.Relay(lifecycleEmitter),
	}
	// The created-side twin (COR-1359): the creation executor enqueues the
	// fully marshaled native_mirror.created in the same transaction as its
	// terminal stage CAS; this relay publishes those rows with PubAck. Same
	// global DB and jurisdiction scoping as the native-mirror deletion outbox.
	deps.nativeMirrorCreatedRelay = nativemirror.NewCreatedOutboxRelay(globalPool, cfg.Jurisdiction, lifecycleEmitter)
	// Resource events ride the same global DB as repo_group, which the detach
	// rewire rewrites in the same transaction as the enqueue. The relay also
	// samples stalled detaches.
	deps.resourceEventRelay = outbox.NewRelay(globalPool, cfg.Jurisdiction, lifecycleEmitter,
		outbox.WithSampler(repodetach.NewStalledSampler(globalPool, cfg.Jurisdiction).Record))
	// githubPerms reads/writes the global GitHub-perms mirror; bind it
	// to the global pool.
	deps.githubPerms = githubperms.NewService(globalPool,
		githubperms.WithRepoGroupNameRefresher(resource.NewStore(globalPool, nil)),
		githubperms.WithMirrorURLAliasRefresher(mirrorrepo.NewService(globalPool)),
	)
	// mirrorrepo: placement + URL tables in the global pool; the
	// revoker clears a suspended placement's SpiceDB grants.
	deps.entireDataPrimarySink = &lazyEntireDataPrimaryReconciler{}
	deps.mirrorRepoSvc = newMirrorRepoService(globalPool, deps.resourceSvc, deps.entireDataPrimarySink, lifecycleEmitter)
	deps.nativeMirrorSvc = nativemirror.New(globalPool,
		nativemirror.WithRepoDeletionOutbox(globalRepoDeletionOutbox),
		nativemirror.WithRegistryPublisher(resourceStore))
	// gitJobsPublisher fires the mirror_git_v1 sync_repo on create so
	// the per-cluster mirror-worker picks up the initial clone
	// immediately, instead of waiting for the periodic resync.
	// ENTIRE_NATS_URL is required; boot fails otherwise.
	gitJobsPub, gitJobsCleanup, err := buildGitJobsPublisher(ctx, cfg)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build gitjobs publisher: %w", err)
	}
	cleanups = append(cleanups, gitJobsCleanup)
	deps.gitJobsPublisher = gitJobsPub
	// resyncPublisher fires the synthetic push webhook that triggers a
	// mirror-pipeline resync (ENT-1172). It targets the CENTRAL
	// webhooks_github_v1 stream (cfg.NatsURL), where cmd/fanout consumes —
	// not the in-cell mirror stream gitJobsPublisher uses.
	resyncPub, resyncCleanup, err := buildResyncPublisher(ctx, cfg)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build resync publisher: %w", err)
	}
	cleanups = append(cleanups, resyncCleanup)
	deps.resyncPublisher = resyncPub
	// mirrorDoneConsumers drain sync-completion events (repo_ops_v1 mirror_done
	// op). The composite writer fans each completion to both status stores —
	// mirror_repos and native_mirrors (intent-gated; disjoint ULID spaces, at
	// most one row changes). One binds the local NATS; one more per reuse-core
	// cell binds that cell's remote NATS.
	deps.mirrorSyncMarkerSink = &lazySyncMarker{}
	doneWriter := mirrordone.CompositeStatusWriter{
		Mirrors:       deps.mirrorRepoSvc,
		NativeMirrors: deps.nativeMirrorSvc,
	}
	markStore := mirrordone.CompositeMarkStore{
		Mirrors:       deps.mirrorRepoSvc,
		NativeMirrors: deps.nativeMirrorSvc,
	}
	mirrorDoneConsumers, mirrorDoneCleanup, err := buildMirrorDoneConsumers(ctx, cfg, doneWriter, markStore, deps.mirrorSyncMarkerSink, cfg.Jurisdiction)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build mirror-done consumers: %w", err)
	}
	if mirrorDoneCleanup != nil {
		cleanups = append(cleanups, mirrorDoneCleanup)
	}
	deps.mirrorDoneConsumers = mirrorDoneConsumers
	// perms-backfill: the create path enqueues a collaborator-reconcile job
	// (publisher) that this same in-region consumer drains OFF the request path,
	// riding the in-cell repo_ops_v1 (perms_backfill op) the mirror-done consumer
	// already uses. Scoped to this core's jurisdiction. The periodic reconciler
	// backstops when NATS is absent, so both degrade safely.
	permsBackfillPub, permsBackfillPubCleanup, err := buildPermsBackfillPublisher(ctx, cfg)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build perms-backfill publisher: %w", err)
	}
	if permsBackfillPubCleanup != nil {
		cleanups = append(cleanups, permsBackfillPubCleanup)
	}
	deps.permsBackfillPublisher = permsBackfillPub
	permsBackfillConsumer, permsBackfillConsumerCleanup, err := buildPermsBackfillConsumer(ctx, cfg, mirrorPermsReconcileFunc(&deps), buildGranteeVerifyInline(cfg, &deps), cfg.Jurisdiction)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build perms-backfill consumer: %w", err)
	}
	if permsBackfillConsumerCleanup != nil {
		cleanups = append(cleanups, permsBackfillConsumerCleanup)
	}
	deps.permsBackfillConsumer = permsBackfillConsumer
	deps.serviceAccountSvc = serviceaccount.NewStore(globalPool)
	deps.oidcfedSvc = oidcfed.NewStore(globalPool)
	// Concrete *regional.Store: exposed as the regional.Service interface on
	// deps, but also handed to buildTransactionalEmail below as the
	// email.Resolver (ResolveContactEmail / ContactDisplayName live on the
	// concrete store, not the Service interface).
	regionalStore := regional.NewStore(regionalPool, deps.identitySvc, deps.authzSvc, deps.resourceSvc, cfg.Jurisdiction,
		regional.WithRepoDeletionOutbox(regionalRepoDeletionOutbox),
		regional.WithAutomation(deps.automationSvc))
	deps.regionalSvc = regionalStore
	// The sweeper needs the concrete *regional.Store (it implements
	// regional.OrgInvitationTokenStore); regional.Service does not expose
	// SweepStaleOrgInvitationTokens.
	deps.orgInvitationTokenSweeper = regional.NewOrgInvitationTokenSweeper(regionalStore, regional.OrgInvitationTokenSweepConfig{
		Scopes: invitationScopes{resources: deps.resourceSvc},
	})

	// Account-erasure outbox (multi-region, ADR 20260708): the reaper enqueues an
	// erasure row on teardown; this region's poller (started in serve.go) drains
	// the global outbox and erases the account in its own region. The outbox lives
	// in the global pool alongside the identity it accompanies. No NATS.
	deps.erasureOutbox = accounterasure.NewOutbox(globalPool)
	deps.erasureLedger = erasureledger.NewStore(globalPool)

	// regionalSvc (a *regional.Store) satisfies email.Resolver. The
	// invitation mail reads across the regional invitation row, the two
	// global stores (org name, inviter identity) and, for an account target,
	// the invitee's contact email, so its resolver is built here from
	// regionalStore, deps.resourceSvc and deps.identitySvc.
	invitationResolver := newInvitationResolver(regionalStore, deps.resourceSvc, deps.identitySvc, regionalStore)
	emailOutbox, emailRelay, emailConsumer, emailCleanup, err := buildTransactionalEmail(ctx, cfg, globalPool, regionalPool, regionalStore, deps.identitySvc, invitationResolver)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build transactional-email fan-out: %w", err)
	}
	cleanups = append(cleanups, emailCleanup)
	deps.emailOutbox = emailOutbox
	deps.emailRelay = emailRelay
	deps.emailConsumer = emailConsumer

	// verifiedEmailConsumer drains pre-extracted push commit-author jobs off this
	// jurisdiction's LOCAL github_push_author_v1 island and writes verified_emails
	// for commit authors homed in this jurisdiction (COR-661/COR-757). Built after
	// regionalSvc, which it writes through in-process.
	//
	// Gated (COR-674): a cell running the standalone `entire-core
	// verified-email-consumer` Deployment sets ENTIRE_VERIFIED_EMAIL_CONSUMER_IN_SERVE=false
	// so serve stops carrying the push firehose -- the two must not both drain
	// the same durable in one cell. Default true keeps the in-process consumer
	// everywhere it isn't yet split out.
	if cfg.VerifiedEmailConsumerInServe {
		verifiedEmailConsumer, verifiedEmailCleanup, err := buildVerifiedEmailConsumer(ctx, cfg, deps.identitySvc, deps.regionalSvc, lifecycleEmitter, cfg.Jurisdiction, deps.erasureLedger)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("build verified-email consumer: %w", err)
		}
		if verifiedEmailCleanup != nil {
			cleanups = append(cleanups, verifiedEmailCleanup)
		}
		deps.verifiedEmailConsumer = verifiedEmailConsumer
	} else {
		slogutil.Info(ctx, "verified-email push consumer disabled in serve (ENTIRE_VERIFIED_EMAIL_CONSUMER_IN_SERVE=false); expecting a standalone verified-email-consumer Deployment (COR-674)")
	}

	// Cluster registry lives on the global pool. STS uses it to resolve a
	// CLI-typed data-plane host into a jurisdiction so a mirror lookup can
	// pin to the right row when the same upstream is mirrored in multiple
	// regions. Reconcile applies the embedded cluster fixture to the global
	// table on every boot — every regional core writes the same fixture, so
	// concurrent boots converge on the same state. Serializable isolation makes
	// them CORRECT, not failure-free: the loser of a write-write race still
	// gets SQLSTATE 40001 and has to retry client-side, which Reconcile now
	// does. Before that it exited non-zero here and crashlooped one pod per
	// region on every rolling deploy.
	// In-process TTL cache (COR-371): the registry is near-static fixture
	// data read on every token exchange, so caching keeps the host→cluster
	// lookup off the cross-region global pool after the first read. Reconcile
	// below is unchanged — it still writes the fixture on every boot.
	deps.clusterStore = cluster.NewStore(globalPool, cluster.WithCacheTTL(clusterCacheTTL))
	// The serving core owns the registry: reconcile the fixture
	// (create/update/decommission) here, before regionalMTLSClients below reads
	// the table to build the repo bridge. (The reaper reads a serve-reconciled
	// table via its own lean graph and never reconciles — ADR 20260707.)
	if err := reconcileClusters(ctx, cfg.ClusterFixtureEnv, deps.clusterStore); err != nil {
		cleanup()
		return deps, func() {}, err
	}
	// Domain audit writes stage in the regional outbox (COR-915) — a local-DB
	// durable write on the request path instead of a synchronous cross-region
	// INSERT (~100ms EU, ~185ms AU) — and the relay (started in serve.go)
	// drains them into the global domain_audit_events. Reads stay on the
	// global pool and trail a write by the drain lag, a few seconds worst
	// case. (The reaper writes domain audit straight to the global pool from its
	// own lean graph — plain NewDomainAudit, no regional outbox — ADR 20260707.)
	deps.domainAudit = audit.NewDomainAuditWithOutbox(globalPool, regionalPool)
	deps.domainAuditRelay = audit.NewRelay(regionalPool, globalPool)
	deps.installationEventRelay = plugins.NewEventRelay(globalPool, cfg.Jurisdiction, lifecycleEmitter).
		WithManageURLs(cfg.AppBaseURL, resourceStore.ProjectDisplayMetadata)
	if err := plugins.RegisterUsageGauges(pluginsStore); err != nil {
		slogutil.Warn(ctx, "register plugin usage gauges failed", slog.Any("error", err))
	}
	pluginGrants, pluginGrantsCleanup, err := buildPluginGrantsConsumer(ctx, cfg, grantProvisioner, deps.domainAudit)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("build plugin grant consumer: %w", err)
	}
	if pluginGrantsCleanup != nil {
		cleanups = append(cleanups, pluginGrantsCleanup)
	}
	deps.pluginGrantsConsumer = pluginGrants

	// Native-mirror lifecycle executor: claims this jurisdiction's
	// native_mirrors intents and drives creation or teardown to completion.
	// Flag-gated dark by default. Builds its own repoadmin bridge — the API
	// server's bridge is constructed later, in wireAPIServer — over the same
	// jurisdiction-scoped cluster set, so a regional executor can only ever
	// provision its own clusters.
	if cfg.NativeMirrorEnabled {
		tlsTransport, err := newInternalTLSTransport(cfg)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("native-mirror executor: internal TLS transport: %w", err)
		}
		bridge, err := buildRepoBridge(ctx, cfg, tlsTransport, deps.clusterStore)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("native-mirror executor: build entiredb bridge: %w", err)
		}
		// ClaimedBy MUST be unique per running executor: every fenced
		// transition (Release/AdvanceStage/RecordRetry) matches on it, so two
		// executors sharing an identity could clear each other's lease
		// mid-execute. The pod name (hostname) is unique per replica; a
		// per-process ULID suffix guarantees uniqueness even if the hostname
		// is somehow unavailable, so the fallback can never collapse every
		// replica onto one shared identity.
		host, err := os.Hostname()
		if err != nil || host == "" {
			host = "entire-core-" + cfg.Jurisdiction
		}
		claimedBy := host + "-" + model.NewULID()
		exec, err := nativemirror.NewExecutor(deps.nativeMirrorSvc, deps.resourceSvc, bridge, deps.authzSvc, deps.gitJobsPublisher, deps.clusterStore, lifecycleEmitter, nativemirror.ExecutorConfig{
			Jurisdiction: cfg.Jurisdiction,
			ClaimedBy:    claimedBy,
		})
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("native-mirror executor: %w", err)
		}
		deps.nativeMirrorExecutor = exec
	}

	// Trust-intent reconciler (ADR 20260724-rsl-root-of-trust-mvp, slice 2):
	// drives bootstrap trust intents to published roots. Regional, flag-gated
	// dark. Like the native-mirror executor it builds its own repoadmin bridge
	// over this jurisdiction's clusters (the api server's bridge is built later,
	// in wireAPIServer). buildTrustReconciler returns nil (disabled, no error)
	// until the fleet root seed is wired and the fixture declares a root profile,
	// so enabling the flag before that ceremony idles gracefully: the subsystem
	// is omitted and the admin surface records intents while reporting
	// "not provisioned".
	if cfg.TrustReconcilerEnabled {
		seeds, err := buildRootSeedProvider(ctx, cfg)
		switch {
		case errors.Is(err, errTrustReconcilerDisabled):
			// Seed provider not configured: leave rootSeedProvider nil, which
			// disables the publish path (buildTrustReconciler idles below).
		case err != nil:
			cleanup()
			return deps, func() {}, fmt.Errorf("trust reconciler: root seed provider: %w", err)
		default:
			deps.rootSeedProvider = seeds
		}

		tlsTransport, err := newInternalTLSTransport(cfg)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("trust reconciler: internal TLS transport: %w", err)
		}
		bridge, err := buildRepoBridge(ctx, cfg, tlsTransport, deps.clusterStore)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("trust reconciler: build entiredb bridge: %w", err)
		}
		// The accept phase does not depend on the root seed: it only verifies
		// what an owning core in any jurisdiction staged.
		worker, err := buildPlacementAcceptanceWorker(cfg, deps, bridge)
		switch {
		case errors.Is(err, errTrustReconcilerDisabled):
		case err != nil:
			cleanup()
			return deps, func() {}, err
		default:
			deps.placementAcceptanceWorker = worker
		}

		rec, err := buildTrustReconciler(cfg, deps, bridge)
		switch {
		case errors.Is(err, errTrustReconcilerDisabled):
			// Not provisioned yet (no seed / unpublishable bridge / no fixture root
			// profile): omit the subsystem. The admin surface still records intents
			// and reports "not provisioned".
		case err != nil:
			cleanup()
			return deps, func() {}, err
		default:
			deps.trustReconciler = rec
			sweep, err := buildRootOnCreateSweep(cfg, deps)
			if err != nil {
				cleanup()
				return deps, func() {}, err
			}
			deps.trustRootOnCreateSweep = sweep
		}
	}

	// Mirror-URL data-plane drainer (COR-1221): applies the URL moves the
	// alias reconcile owes to this jurisdiction's clusters. Builds its own
	// bridge like the executor above. A core with no usable bridge (no
	// internal client cert, no clusters) logs and runs without it — the owed
	// rows wait in the outbox rather than failing boot.
	if cfg.MirrorURLDataplaneDrainerEnabled {
		deps.mirrorURLDrainer = buildMirrorURLDrainer(ctx, cfg, deps)
	}

	// Cell-cleanup drainer (COR-1820): tears down the cell resources a
	// terminally failed provisioning left allocated. Unflagged — the queue is
	// the only owner of that state once the control plane gives up on the
	// repo. A core with no usable bridge logs and runs without it; the owed
	// rows wait rather than failing boot.
	deps.repoCellCleanupDrainer = buildRepoCellCleanupDrainer(ctx, cfg, deps)

	signingKeyCipher, err := buildSigningKeyCipher(ctx, cfg)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("signing key cipher: %w", err)
	}
	// Signing keys live in the region's own DB (regionalPool), never global.
	// EnsureSigningKey loads this region's key or mints one if absent. Per-region
	// kids are fine: cross-region verification fetches each region's JWKS.
	deps.keyStore = authn.NewKeyStore(regionalPool, signingKeyCipher, authn.WithCacheTTL(signingKeyCacheTTL))
	if _, err := deps.keyStore.EnsureSigningKey(ctx); err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("ensure signing key: %w", err)
	}
	// RS256 is never the signing algorithm (EdDSA is), but OIDC Core mandates
	// RS256 support, so persist an RSA key for discovery + JWKS (COR-415).
	if _, err := deps.keyStore.EnsureRSAKey(ctx); err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("ensure rsa signing key: %w", err)
	}
	// Keep the signing-key + JWKS cache warm off the request path (COR-846):
	// low-traffic EU/AU pods mint too rarely to keep a TTL-only cache from
	// expiring, so every request paid the KMS decrypt. The loop stops when ctx
	// (the serve-lifetime context) is cancelled.
	deps.keyStore.StartBackgroundRefresh(ctx)
	// iss=aud=cfg.IssuerClaim(). The URL form lets external verifiers
	// derive JWKS from iss (RFC 8414); in this repo verifiers are still
	// configured with explicit JWKS URLs, but the iss must be URL-shaped
	// for callers like the partial.to data plane that do that lookup.
	iss := cfg.IssuerClaim()
	deps.jwtIssuer = authn.NewJWTIssuer(deps.keyStore, authn.LoginTokenTTL, iss, iss)

	// Regional serves its own JWKS on the public listener (localhost) — no
	// amplification risk, so disable the unknown-kid refetch throttle and
	// pick up our own rotated kid at once. Every bearer token on this pod
	// passes through here, so the keeper never idles out.
	deps.verifier = jwtverify.New(cfg.LocalJWKSURL(), 5*time.Minute,
		jwtverify.WithAudiences([]string{cfg.AuthBaseURL}),
		jwtverify.WithObserver(authn.RecordTokenVerifiedObserver("core")),
		jwtverify.WithMinRefetchInterval(0),
		jwtverify.WithPersistentKeeper(),
	)

	deps.oauthStateStore = authn.NewOAuthStateStore(regionalPool)

	// Empty cipher disables the github-tokens path entirely
	// (link/STS routes 503), which is the safe default for a fresh
	// regional cluster before KMS provisioning lands.
	if cfg.GitHubTokenCipher != "" {
		ghCipher, err := buildGitHubTokenCipher(ctx, cfg)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("github token cipher: %w", err)
		}
		// github_user_tokens lives in the GLOBAL tier (COR-932) so a user's
		// GitHub link is readable/writable at every cell, not just the one that
		// seeded it. The cipher key is a multi-region KMS key so any cell can
		// decrypt the shared ciphertext.
		deps.githubTokens = githubtokens.NewService(globalPool, ghCipher, cfg.GitHubClientID, cfg.GitHubClientSecret)

		// Same cipher config protects the COR-596 installation-token cache.
		instCipher, err := buildInstallationTokenCipher(ctx, cfg)
		if err != nil {
			cleanup()
			return deps, func() {}, fmt.Errorf("installation token cipher: %w", err)
		}
		deps.installationTokenStore = githubinsttoken.NewStore(regionalPool, instCipher)
	}

	deps.regionHosts = cfg.ParseRegionHosts()
	authHostsRaw := cfg.ParseJurisdictionAuthHosts()
	deps.jurisdictionAuthHosts = MergeAuthHosts(authHostsRaw, deps.regionHosts)
	if err := errOnPartialJurisdictionAuthHosts(authHostsRaw, deps.regionHosts); err != nil {
		cleanup()
		return deps, func() {}, err
	}
	if cfg.HomeRegionCookieSecret != "" {
		deps.cookie = authn.NewHomeJurisdictionCookie([]byte(cfg.HomeRegionCookieSecret), cfg.CookieDomain)
		deps.commitTokens = committoken.NewSigner([]byte(cfg.HomeRegionCookieSecret))
	}

	deps.refreshStore = authn.NewRefreshStore(regionalPool)
	deps.authRequestStore = authn.NewAuthRequestStore(regionalPool)
	deps.pluginAuthorizations = authn.NewPluginAuthorizationStore(regionalPool)

	deps.idpSessionStore = authn.NewSessionStore(regionalPool, authn.IdpSessionTable, 24*time.Hour)
	deps.consoleSessionStore = authn.NewSessionStore(regionalPool, authn.ConsoleSessionTable, 24*time.Hour)
	deps.deviceGrantStore = authn.NewDeviceGrantStore(regionalPool)

	isSecure := true
	// idp_session is host-only on the auth host — it represents the
	// user's session with the IdP and is read only by handlers on the
	// auth origin. No Domain so the cookie doesn't leak to console.*.
	deps.idpCookie = authn.NewSessionCookie("idp_session", isSecure, "", 24*time.Hour)
	// console_session is host-only on the console host. The OAuth
	// redirect_uri targets the console origin, so Set-Cookie there is
	// host-scoped by construction — no need to span the auth↔console
	// boundary via Domain. Sibling jurisdictions (us.console.* vs
	// eu.console.*) get their own slot and can't clobber each other.
	deps.consoleCookie = authn.NewSessionCookie("console_session", isSecure, "", 24*time.Hour)
	// Browser three-tier session cookies (ADR 20260527), host-only on the
	// auth origin alongside idp_session. Max-Age tracks each tier's TTL: the
	// login JWT (8h) and the opaque refresh token (7d browser).
	deps.loginCookie = authn.NewSessionCookie("login", isSecure, "", authn.LoginTokenTTL)
	deps.refreshCookie = authn.NewSessionCookie("refresh", isSecure, "", authn.BrowserRefreshTokenTTL)

	// Regional is production-only; anything but https leaks the console
	// client_secret on the RP→IdP back-channel and silently breaks login
	// (cookies are minted with Secure=true above, which browsers drop on
	// non-HTTPS connections). No localhost exemption — local dev serves
	// HTTPS via the mkcert bundle.
	if !strings.HasPrefix(cfg.AuthBaseURL, "https://") {
		cleanup()
		return deps, func() {}, fmt.Errorf("ENTIRE_CORE_AUTH_BASE_URL must be https:// in regional mode (got %q)", cfg.AuthBaseURL)
	}
	mtlsClients, err := regionalMTLSClients(ctx, cfg, deps.clusterStore)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
	clientRegistry, consoleClient, err := buildOAuthClientRegistry(ctx, cfg, mtlsClients...)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
	deps.clientRegistry = clientRegistry
	deps.consoleClientID = consoleClient.ID
	deps.consoleClientSecret = REDACTED

	// Sibling discovery uses the raw JURISDICTION_AUTH_HOSTS, never the
	// merged-with-REGION_HOSTS map: JWT iss/aud are always AuthBaseURL,
	// never console URL, so a console-host fallback can't legitimately
	// appear here. errOnPartialJurisdictionAuthHosts above already
	// refused boot if the map is partial.
	siblingURLs := siblingAuthBaseURLs(authHostsRaw, cfg.AuthBaseURL)
	deps.siblingAuthBaseURLs = siblingURLs
	// The waitlist approval gate (assertAccountApproved) treats a nil
	// IdentitySvc as "approval not wired" and fails OPEN — a deliberate
	// unit-test seam. Production must never construct Storage without it,
	// or the gate would silently let waitlisted accounts mint repo tokens.
	if deps.identitySvc == nil {
		cleanup()
		return deps, func() {}, errors.New("oidc storage: IdentitySvc is required (waitlist approval gate fails open without it)")
	}

	var issuerIntrospect oidcop.IssuerIntrospector
	if len(siblingURLs) > 0 {
		// NewStorage builds a per-sibling JWKSVerifier from siblingURLs,
		// each pointed at that sibling's remote JWKS (COR-382). Cross-juris
		// exchange also gates on the subject's current account state before
		// minting a foreign-session token — see ADR 20260520. The state
		// lives in global tables, so the check runs against the shared DB
		// instead of dialing the home region's introspect endpoint.
		issuerIntrospect = oidcop.NewLocalIssuerIntrospector(deps.identitySvc)
	}

	automationLimiter := oidcop.NewAutomationExchangeLimiter(oidcop.AutomationExchangeRateConfig{
		PerMinute: cfg.AutomationExchangeRatePerMinute,
		Burst:     cfg.AutomationExchangeBurst,
	})
	pluginTokenLimiter := oidcop.NewPluginTokenLimiter(cfg.PluginTokenRatePerMinute, cfg.PluginTokenBurst)
	oidcStorage := oidcop.NewStorage(oidcop.StorageConfig{
		KeyStore:              deps.keyStore,
		RefreshStore:          deps.refreshStore,
		IdentitySvc:           deps.identitySvc,
		ClientRegistry:        deps.clientRegistry,
		CIMDResolver:          cimd.NewResolver(cimd.Config{}),
		PluginCatalog:         deps.pluginCatalog,
		AuthRequestStore:      deps.authRequestStore,
		DeviceGrantStore:      deps.deviceGrantStore,
		Authz:                 deps.authzSvc,
		PlatformAdminResource: "platform:" + coreapi.PlatformResourceID,
		RepoResolver:          deps.resourceSvc,
		OrgLister:             deps.resourceSvc,
		ClusterResolver:       newClusterResolver(deps.resourceSvc, deps.clusterStore, deps.mirrorRepoSvc),
		CIWebhooksURL:         cfg.CIWebhooksURL,
		CIWebhooksURLs:        cfg.CIWebhooksURLs,
		MirrorResolver:        newMirrorResolver(deps.mirrorRepoSvc),
		NativeMirrorResolver:  deps.nativeMirrorSvc,
		OIDCFed:               deps.oidcfedSvc,
		ServiceAccount:        deps.serviceAccountSvc,
		Automation:            deps.automationSvc,
		RepoGroupChecker:      deps.resourceSvc,
		AutomationLimiter:     automationLimiter,
		PluginTokenLimiter:    pluginTokenLimiter,
		Audit:                 deps.domainAudit,
		AuthCodeResources:     authn.NewAuthCodeResourceRegistry(cfg.AuthCodeResourceURLs),
		LoginAud:              cfg.AuthBaseURL,
		LoginTokenTTL:         deps.jwtIssuer.TTL(),
		SiblingAuthBaseURLs:   siblingURLs,
		IssuerIntrospector:    issuerIntrospect,
		Analytics:             deps.analyticsClient,
	})
	deps.pluginTokens = oidcStorage
	deps.oidcProvider, err = oidcop.NewProvider(cfg.AuthBaseURL, oidcStorage)
	if err != nil {
		cleanup()
		return deps, func() {}, fmt.Errorf("construct oidc provider: %w", err)
	}
	ratelimit.StartCleanup(ctx, automationLimiter)
	ratelimit.StartCleanup(ctx, pluginTokenLimiter)
	// Same reasoning as keyStore.StartBackgroundRefresh above: a quiet pod's
	// first cross-region exchange after a deploy otherwise pays the sibling
	// JWKS fetch on the request path.
	oidcStorage.WarmSiblingJWKS(ctx)

	deps.loginFlow = loginflow.New(loginflow.Config{
		Identity:          deps.identitySvc,
		Regional:          deps.regionalSvc,
		Jurisdiction:      cfg.Jurisdiction,
		CEOWelcomeEnabled: cfg.CEOWelcomeEnabled,
		// Backfills first-login mirror access in the background and creates the
		// personal mirrors project of an already installed GitHub user. Regional
		// wires the full perms stack (SpiceDB read+write via dialSpiceDB, plus the
		// global-pool githubPerms / mirrorRepoSvc / resourceSvc set above), so
		// buildMirrorPermsReconciler is non-nil here and a fresh account gains its
		// source-managed grants at first login rather than waiting for the
		// periodic reconciler sweep. This matters more since ENT-1058: new-user
		// account creation moved from the global picker to this regional login.
		OnAccountCreated: chainAccountHooks(mirrorPermsAccountBackfill(&deps), mirrorsProjectAccountHook(buildMirrorsProjectProvisioner(ctx, cfg, &deps), mirrorsProjectTriggerSignup)),
		EmailOutbox:      emailEnqueuerOrNilAuthn(deps.emailOutbox),
	})

	deps.systemJWT = authn.NewJWTIssuer(deps.keyStore, 1*time.Hour, cfg.IssuerClaim(), cfg.IssuerClaim())
	deps.systemLogin = authn.NewSystemLogin([]string{cfg.BreakGlassToken, cfg.BreakGlassTokenOld})

	// WorkOS persistence lives in the global pool (org WorkOS IDs,
	// event ledger, event cursor, account state flag).
	wosSvc, err := buildWorkOSService(ctx, cfg, globalPool, deps.identitySvc, deps.resourceSvc)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
