package staleread_test

import (
	"context"
	"errors"
	"testing"

	"entire.io/core/staleread"
	"entire.io/core/staleread/stalereadtest"
)

var errNotFound = errors.New("not found")

func get(v string, err error) func() (string, error) {
	return func() (string, error) { return v, err }
}

// The meter provider is process-global, so these tests cannot run in parallel.
func TestFollowerThenFreshRecordsOutcomes(t *testing.T) {
	canceledCtx, cancel := context.WithCancel(t.Context())
	cancel()
	tests := []struct {
		name     string
		ctx      context.Context //nolint:containedctx // a table of caller contexts
		follower func() (string, error)
		fresh    func() (string, error)
		want     string
		wantVal  string
		wantErr  error
	}{
		{"corrected", t.Context(), get("", errNotFound), get("row", nil), "crdb/project.get/corrected", "row", nil},
		{"confirmed", t.Context(), get("", errNotFound), get("", errNotFound), "crdb/project.get/confirmed", "", errNotFound},
		{"fallback_failed", t.Context(), get("", errNotFound), get("", errors.New("leaseholder down")), "crdb/project.get/fallback_failed", "", errors.New("leaseholder down")},
		{"canceled", canceledCtx, get("", errNotFound), get("", context.Canceled), "crdb/project.get/canceled", "", context.Canceled},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			reader := stalereadtest.Install(t)
			val, err := staleread.FollowerThenFresh(tc.ctx, "project.get", "test: get",
				tc.follower, tc.fresh, staleread.NotFound[string](errNotFound))
			if val != tc.wantVal || (err == nil) != (tc.wantErr == nil) || (tc.wantErr != nil && err.Error() != tc.wantErr.Error()) {
				t.Fatalf("got (%q, %v); want (%q, %v)", val, err, tc.wantVal, tc.wantErr)
			}
			got := reader.Rechecks(t)
			if len(got) != 1 || got[tc.want] != 1 {
				t.Fatalf("rechecks = %v; want exactly %s=1", got, tc.want)
			}
		})
	}
}

// A follower hit never reads fresh. A follower error is a degraded replica,
// not a stale answer, so it falls back without a recheck count.
func TestFollowerThenFreshCountsOnlyAStaleMiss(t *testing.T) {
	reader := stalereadtest.Install(t)
	freshCalls := 0
	fresh := func() (string, error) { freshCalls++; return "fresh", nil }
	notFound := staleread.NotFound[string](errNotFound)

	if v, err := staleread.FollowerThenFresh(t.Context(), "project.get", "test: get", get("stale", nil), fresh, notFound); err != nil || v != "stale" {
		t.Fatalf("follower hit = (%q, %v); want stale", v, err)
	}
	if freshCalls != 0 {
		t.Fatalf("fresh ran %d times after a follower hit", freshCalls)
	}
	if v, err := staleread.FollowerThenFresh(t.Context(), "project.get", "test: get", get("", errors.New("replica down")), fresh, notFound); err != nil || v != "fresh" {
		t.Fatalf("follower error = (%q, %v); want fresh", v, err)
	}
	if got := reader.Rechecks(t); len(got) != 0 {
		t.Fatalf("rechecks = %v; want none for a follower hit or error", got)
	}
}

func TestFollowerThenFreshEmptyListIsAMiss(t *testing.T) {
	reader := stalereadtest.Install(t)
	list := func(rows ...string) func() ([]string, error) {
		return func() ([]string, error) { return rows, nil }
	}
	got, err := staleread.FollowerThenFresh(t.Context(), "repo.resolve_github", "test: resolve",
		list(), list("a"), staleread.Empty[string]())

