// Package staleread counts stale reads that a fresh read corrected, and reads
// that a commit token or revision pinned. SpiceDB and CockroachDB callers share
// it so one pair of counters covers both datastores.
package staleread

import (
	"context"
	"errors"
	"log/slog"
	"sync"
	"sync/atomic"
	"testing"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	"entire.io/slogutil"
)

const (
	// RecheckMetricName counts fresh re-reads of a stale miss or denial.
	RecheckMetricName = "entire.core.stale_read.recheck.total"
	// PinnedMetricName counts reads served at a commit token or revision floor.
	PinnedMetricName = "entire.core.stale_read.pinned.total"
)

// Store names the datastore that served the stale read.
type Store string

const (
	SpiceDB Store = "spicedb"
	CRDB    Store = "crdb"
)

// Outcome is the result of one fresh re-read.
type Outcome string

const (
	// Corrected means a denial became an allow, or a miss became a hit.
	Corrected Outcome = "corrected"
	Confirmed Outcome = "confirmed"
	// FallbackFailed means the fresh read failed.
	FallbackFailed Outcome = "fallback_failed"
	Canceled       Outcome = "canceled"
)

type instruments struct {
	recheck metric.Int64Counter
	pinned  metric.Int64Counter
}

var (
	initMu sync.Mutex
	loaded atomic.Pointer[instruments]
)

// get binds the counters lazily so otel.Meter sees the provider that startup
// wiring installs. A registration error leaves a counter nil and its record
// path a no-op, so a gap shows as missing data and never as a crash.
func get() *instruments {
	if in := loaded.Load(); in != nil {
		return in
	}
	initMu.Lock()
	defer initMu.Unlock()
	if in := loaded.Load(); in != nil {
		return in
	}
	meter := otel.Meter("entire.io/core/staleread")
	in := &instruments{}
	var err error
	in.recheck, err = meter.Int64Counter(RecheckMetricName,
		metric.WithDescription("Fresh re-reads of a stale miss or denial, by store (spicedb, crdb), surface and outcome. outcome=corrected means the fresh answer differed from the stale one (denial became allow, miss became hit): the read-after-write fix working, and a nonzero rate is expected. outcome=confirmed means the fresh answer agreed. outcome=fallback_failed means the fresh read errored and the stale answer stood or the error was returned: a sustained rate means users see stale 403 and 404 responses again. outcome=canceled means the caller hung up."),
		metric.WithUnit("{recheck}"))
	_ = err
	in.pinned, err = meter.Int64Counter(PinnedMetricName,
		metric.WithDescription("Reads served at a commit token snapshot (store=crdb) or a SpiceDB revision floor (store=spicedb), by surface. Shows how often clients send tokens and how often a create path pins its own read-back."),
		metric.WithUnit("{read}"))
	_ = err
	loaded.Store(in)
	return in
}

// ResetForTest drops the bound counters so the next record binds the current
// global meter provider. It is test-only.
func ResetForTest() {
	if !testing.Testing() {
		panic("staleread.ResetForTest is test-only")
	}
	loaded.Store(nil)
}

type attrKey struct {
	store   Store
	surface string
	outcome Outcome
}

var (
	optionsMu sync.RWMutex
	// Surfaces are fixed in code, so the cache stays small.
	options = map[attrKey]metric.AddOption{}
)

func option(k attrKey) metric.AddOption {
	optionsMu.RLock()
	opt, ok := options[k]
	optionsMu.RUnlock()
	if ok {
		return opt
	}
	attrs := []attribute.KeyValue{
		attribute.String("store", string(k.store)),
		attribute.String("surface", k.surface),
	}
	if k.outcome != "" {
		attrs = append(attrs, attribute.String("outcome", string(k.outcome)))
	}
	opt = metric.WithAttributeSet(attribute.NewSet(attrs...))

