func (s *Store) OnboardingCompleted(ctx context.Context, id model.AccountID) (bool, error) {
	var completed bool
	err := s.pool.QueryRow(ctx,
		`SELECT onboarding_completed_at IS NOT NULL FROM accounts WHERE id = $1`,
		id,
	).Scan(&completed)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return false, fmt.Errorf("account %s: %w", id, ErrNotFound)
		}
		return false, fmt.Errorf("onboarding completed: %w", err)
	}
	return completed, nil
}

// GetAccountFollowerRead implements the Service contract; see the
// interface docstring. accounts is GLOBAL, so a present-time read is already
// local and the follower read buys no locality (#4333). Callers move to
// GetAccount in a follow-up. Fresh fallback on ANY follower error: an account
// created just before the exchange is newer than the follower timestamp, and
// a cluster that doesn't serve follower reads must still resolve.
func (s *Store) GetAccountFollowerRead(ctx context.Context, id model.AccountID) (*model.Account, error) {
	// ErrNotFound is the expected follower miss (account created just now);
	// a cancelled ctx fails the fresh read identically. Anything else means
	// the follower path itself is failing and the optimisation is silently
	// degrading to a double read — FollowerThenFresh logs it (the query is
	// also traced via otelpgx; the log adds a push signal).
	return staleread.FollowerThenFresh(ctx, "account.get", "identity: get-account",
		func() (*model.Account, error) { return s.getAccount(ctx, id, s.reads.AOST()) },
		func() (*model.Account, error) { return s.getAccount(ctx, id, postgres.CurrentReadAOST) },
		staleread.NotFound[*model.Account](ErrNotFound))
}

// getAccount runs a current read on s.db(ctx), not s.pool directly, so
// GetAccount composes with a caller's transaction — the attach-completion
// transaction (COR-1386) reads blocked_at/deletion_requested_at/approved on
// the same transaction as its handle insert, so each refusal judges the same
// snapshot rather than a separately-committed read.
//
// An AOST read must not join that transaction: CockroachDB rejects an inline
// AS OF SYSTEM TIME mid-transaction, and because that error aborts the
// transaction it also takes out GetAccountFollowerRead's fresh fallback and
// every later statement the caller had planned. Follower reads therefore stay
// on the pool, as gitHubUserIDForAccount's does — which is what a deliberately
// stale read means anyway.
func (s *Store) getAccount(ctx context.Context, id model.AccountID, aost postgres.AOST) (*model.Account, error) {
	db := s.db(ctx)
	if aost != postgres.CurrentReadAOST {
		db = s.pool
	}
	acct := &model.Account{ID: id}
	var blockedBy *string
	err := db.QueryRow(ctx,
		`SELECT home_jurisdiction, created_at, approved, approved_at, blocked_at, blocked_by, deletion_requested_at, onboarding_completed_at FROM accounts `+string(aost)+`WHERE id = $1`,
		id,
	).Scan(&acct.HomeJurisdiction, &acct.CreatedAt, &acct.Approved, &acct.ApprovedAt, &acct.BlockedAt, &blockedBy, &acct.DeletionRequestedAt, &acct.OnboardingCompletedAt)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, fmt.Errorf("account %s: %w", id, ErrNotFound)
		}
		return nil, fmt.Errorf("get account: %w", err)
	}
	acct.BlockedBy = accountIDPtr(blockedBy)
	return acct, nil
}

// accountIDPtr converts a nullable blocked_by column value to the model's
// typed pointer. Nullable custom-ID columns scan via *string (AccountID's
// Scanner has no NULL case — see scanGrant in authn/device_grants.go).
func accountIDPtr(s *string) *model.AccountID {
	if s == nil {
		return nil
	}
	id := model.AccountID(*s)
	return &id
}

