// resolveLoginScopes mirrors core/api Server.resolveLoginScopes for login
// token issuance: includes entire:ops-access iff the subject holds either
// admin tier (admin_read). The issued ops-access token is narrowed to
// scope=admin:read for a read-only admin at exchange time.
// SpiceDB-unreachable degrades to the non-admin set; callers decide how to
// report the check failure.
//
// The check is stale on purpose. Almost every login is denied here, and
// Can re-checks a deny at full consistency, which is a cross-region read
// from every non-US replica on every login. A freshly granted admin logs in
// again after the follower-read delay. The revoked direction is unchanged:
// Can never re-checked an allow either, and the scope only admits the
// ops-access exchange, which checks admin_read live.
func (s *Storage) resolveLoginScopes(ctx context.Context, accountID string) ([]string, error) {
	scopes := authn.LoginScopesFor(false)
	var authzErr error
	if s.authzSvc != nil && s.platformAdminResourceTag != "" {
		allowed, err := s.authzSvc.Can(ctx, authz.AllowStale, "account:"+accountID, "admin_read", s.platformAdminResourceTag)
		switch {
		case err != nil:
			authzErr = err
		case allowed:
			scopes = authn.LoginScopesFor(true)
		}
	}
	out := make([]string, len(scopes))
	for i, sc := range scopes {
		out[i] = string(sc)
	}
	return out, authzErr
}

