// checkMirrorAccess decides whether the caller may take action on the
// resolved mirror. A promoted mirror is a native repo, so the gate is the
// same SpiceDB repo#pull / repo#push check validateRepoExchange runs —
// keyed on repo:<mirror_repos.id>. The one mirror-specific carve-out is
// the public-pull short-circuit: a public upstream
// (github_repos.is_private = false) may be cloned by anyone, matching
// GitHub's visibility and the behaviour the legacy githubperms.CanPull
// gate had. Push never short-circuits (visibility never grants write).
//
// The short-circuit re-reads is_private *fresh* via the resolver rather
// than trusting ref.IsPrivate, which came from the follower-read JOIN.
// The short-circuit bypasses SpiceDB, so it's part of the access decision
// and per COR-371 access decisions stay fresh — otherwise an upstream that
// just turned private would keep minting ungated pull tokens for the
// follower-staleness window. The fresh read fires only when the follower
// hint says public; a follower hint of "private" goes straight to SpiceDB
// (safe either way — SpiceDB is the real gate), so private pulls pay no
// extra read.
//
// requestedRepoAction only returns ScopeRepoPull or ScopeRepoPush; the
// default stays defensive so a future scope addition can't fall through
// to allow.
func (s *Storage) checkMirrorAccess(ctx context.Context, subject string, action authn.Scope, ref *MirrorRef) (bool, error) {
	if action == authn.ScopeRepoPull && !ref.IsPrivate {
		// Follower hint says public — confirm against a fresh read before
		// bypassing SpiceDB. A missing upstream row or a freshly-private
		// repo falls through to the SpiceDB gate; an infra error surfaces.
		private, err := s.mirrorResolver.IsRepoPrivate(ctx, ref.GitHubRepoID)
		switch {
		case errors.Is(err, ErrMirrorNotFound):
			// Upstream row vanished between JOIN and confirm — don't
			// short-circuit; let SpiceDB decide.
		case err != nil:
			return false, fmt.Errorf("confirm mirror visibility: %w", err)
		case !private:
			return true, nil
		}
	}
	if s.authzSvc == nil {
		// Unwired authz only happens in tests; production always wires it
		// (NewStorage). Fail closed rather than silently admitting.
		return false, nil
	}
	//exhaustive:ignore — only repo pull and push are mirror actions; the default rejects everything else.
	switch action {
	case authn.ScopeRepoPull, authn.ScopeRepoPush:
		allowed, err := s.authzSvc.Can(ctx, authz.RetryDeniedFresh, "account:"+subject, string(action), "repo:"+ref.MirrorRepoID.String())
		if err != nil {
			return false, fmt.Errorf("authz check: %w", err)
		}
		return allowed, nil
	default:
		return false, fmt.Errorf("unsupported mirror action %q", action)
	}
}

