		return allowed, nil
	default:
		return false, fmt.Errorf("unsupported mirror action %q", action)
	}
}

// validateServiceEntiredbExchange gates the on-behalf-of exchange that
// fronts entiredb's :8281 RepoAdmin RPCs. RFC 8693 shape:
//
//   - subject_token = REDACTED user's login JWT (verified by pkg/op's
//     built-in own-issuer access-token verifier before we run).
//   - actor_token  = REDACTED client_credentials token, audience
//     service:entiredb, sub names the entire-core workload. Verified
//     by VerifyExchangeActorToken upstream; the resulting claims map
//     is surfaced via req.GetExchangeActorTokenClaims.
//
// The issued JWT keeps `sub` as the user's account id; `act` carries
// {iss, sub} per RFC 8693 §4.1 — both are necessary to identify the
// actor. `aud` is service:entiredb. Receivers gate on the audience +
// actor identity: the subject's scope on the login JWT decides whether
// the user could request the on-behalf-of pair at all, and the actor's
// mTLS-bound client_credentials token decides whether the workload
// behind the exchange is entire-core.

