// datastore's primary region.
func NewStoreRW(read, write *authzed.Client) *Store {
	return &Store{read: primaryRoutedReader{local: read, primary: write}, write: write}
}

// NewStoreForTest builds a single-client Store whose stale-tolerant reads run
// fully consistent, so write-then-read assertions are deterministic instead of
// racing SpiceDB's revision-quantization window — 1ms in dev/CI, but -race
// widens the write→read gap well past it. The vulnerable direction is
// revoke-then-assert-deny: a stale ALLOW is served as-is (only denies get the
// fully-consistent re-check), so any suite that revokes and asserts flakes
// under NewStore. Convention: EVERY test setup that builds a Store against
// the shared SpiceDB uses this constructor. The prod minimize_latency policy
// keeps its coverage in store_consistency_test.go (fake client) and
// reader_integration_test.go (real SpiceDB, deliberately NewReaderFromClient).
// TEST ONLY: panics outside a `go test` binary — fully-consistent reads in a
// prod pathway would silently defeat the minimize_latency policy (see Store)
// that EU/AU latency depends on.
func NewStoreForTest(client *authzed.Client) *Store {
	if !testing.Testing() {
		panic("authz.NewStoreForTest is test-only: its fully-consistent reads defeat the minimize_latency read policy prod depends on — use NewStore/NewStoreRW")
	}
	return &Store{read: client, write: client, fullyConsistentReadsForTest: true}
}

// NewStoreRWForTest is NewStoreForTest with separate read and write clients,
// for tests that need to attach a recorder to each client independently
// (e.g. to distinguish reads from writes in an RPC trace).
func NewStoreRWForTest(read, write *authzed.Client) *Store {
	if !testing.Testing() {
		panic("authz.NewStoreRWForTest is test-only: its fully-consistent reads defeat the minimize_latency read policy prod depends on — use NewStore/NewStoreRW")
	}
	return &Store{read: read, write: write, fullyConsistentReadsForTest: true}
}

// staleRead is the consistency for the Store's stale-tolerant reads:
// minimize_latency in prod, fully_consistent under NewStoreForTest. The deny
// re-checks (Can, HasPublicAccess) call fullyConsistent() directly and are
// unaffected.
func (s *Store) staleRead() *v1.Consistency {
	if s.fullyConsistentReadsForTest {
		return fullyConsistent()
	}
	return minimizeLatency()
}

func (s *Store) consistencyForPolicy(policy ConsistencyPolicy) (*v1.Consistency, error) {
	switch policy {
	case AllowStale, RetryDeniedFresh:
		return s.staleRead(), nil
	case FullyConsistent:
		return fullyConsistent(), nil
	default:
		return nil, fmt.Errorf("invalid consistency policy: %d", policy)
	}
}

// Can reports whether subject may perform action on resource under policy.
// RetryDeniedFresh accepts stale allows; it does not establish current revocation safety.
func (s *Store) Can(ctx context.Context, policy ConsistencyPolicy, subject, action, resource string) (bool, error) {
	c, err := s.consistencyForPolicy(policy)
	if err != nil {
		return false, err
	}
	subjectType, subjectID, err := parseRef(subject)
	if err != nil {
		return false, fmt.Errorf("parse subject: %w", err)
	}
	resourceType, resourceID, err := parseRef(resource)
	if err != nil {
		return false, fmt.Errorf("parse resource: %w", err)
	}

	// Can's own subject/action/resource stay plain strings (subject/resource are
	// pre-encoded "type:id" refs, not single vocabulary values), so the parsed
	// pieces are cast onto checkAt's typed parameters here — the one boundary
	// where Can's dynamic parseRef output meets the typed API.
	allowed, err := s.checkAt(ctx, c, SubjectType(subjectType), subjectID, Action(action), ResourceType(resourceType), resourceID)
	if err != nil {
		return false, err
	}
	if allowed || policy != RetryDeniedFresh {
		return allowed, nil
	}
	fresh, err := s.checkAt(ctx, fullyConsistent(), SubjectType(subjectType), subjectID, Action(action), ResourceType(resourceType), resourceID)
	staleread.Rechecked(ctx, staleread.SpiceDB, surface(ResourceType(resourceType), Action(action)), fresh, err)
	return fresh, err
}

// RequireGroupOnlyVisibilitySchema fails unless SpiceDB recognizes the
// COR-1353 rollout marker. The marker denies access by design. Its existence
// proves that legacy placement public_viewer tuples cannot grant repo pull.
func (s *Store) RequireGroupOnlyVisibilitySchema(ctx context.Context) error {
	_, err := s.checkAt(ctx, fullyConsistent(),
		AccountSubjectType, "anonymous",
		Action("cor_1353_group_only_visibility"),
		ResourceType("schema_guard"), "current")
	if err != nil {
		return fmt.Errorf("require group-only visibility schema: %w", err)
	}
	return nil

